CREATE DOMAIN "public"."audience" AS "text"
	CONSTRAINT "audience_values" CHECK ((VALUE = ANY (ARRAY['public'::"text", 'connections'::"text", 'group'::"text", 'venue_members'::"text", 'private'::"text"])));


ALTER DOMAIN "public"."audience" OWNER TO "postgres";


COMMENT ON DOMAIN "public"."audience" IS 'Who can see a thing. public = any signed-in user; connections = people the author is connected to; group = approved members of the linked group; venue_members = members of the owning venue; private = the author only. events uses this. matches.open_audience, leagues.visibility, venue_events.visibility and groups.visibility predate it and should migrate onto it rather than each keeping their own list.';



