CREATE OR REPLACE FUNCTION "public"."_is_active_owner"("p_venue_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1 from public.venue_users
    where venue_id = p_venue_id and user_id = auth.uid()
      and role = 'owner' and status = 'active'
  );
$$;


ALTER FUNCTION "public"."_is_active_owner"("p_venue_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_merge_venues"("p_loser_venue_id" "uuid", "p_survivor_venue_id" "uuid", "p_actor" "text" DEFAULT 'system'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_loser  public.padel_venues%rowtype;
  v_surv   public.padel_venues%rowtype;
  v_moved  integer := 0;
  v_m      integer := 0;
  v_e      integer := 0;
  v_l      integer := 0;
begin
  if p_loser_venue_id = p_survivor_venue_id then
    return jsonb_build_object('success', false, 'error', 'same_venue');
  end if;

  select * into v_loser from public.padel_venues where venue_id = p_loser_venue_id;
  if not found then return jsonb_build_object('success', false, 'error', 'loser_not_found'); end if;
  select * into v_surv  from public.padel_venues where venue_id = p_survivor_venue_id;
  if not found then return jsonb_build_object('success', false, 'error', 'survivor_not_found'); end if;

  if v_loser.venues_id is not null then
    return jsonb_build_object('success', false, 'error', 'loser_is_claimed',
      'detail', 'The losing venue has been claimed. Resolve with its owner before merging.');
  end if;
  if v_surv.merged_into is not null then
    return jsonb_build_object('success', false, 'error', 'survivor_already_merged',
      'detail', 'Pick the venue that survived that merge instead.');
  end if;

  -- Every key apply_venue_enrichment() can write. jsonb_strip_nulls drops the
  -- ones the loser had nothing to say about, and the coalesce() in
  -- apply_venue_enrichment means a key present here never blanks the survivor.
  insert into public.venue_enrichment (venue_id, source, external_id, fetched_at, payload, raw)
  select p_survivor_venue_id,
         'legacy_manual_2026_03_30',
         'merged-from:' || p_loser_venue_id::text,
         now(),
         jsonb_strip_nulls(jsonb_build_object(
           'number_of_courts',            nullif(v_loser.number_of_courts, 0),
           'indoor_courts',               nullif(v_loser.indoor_courts, 0),
           'outdoor_courts',              nullif(v_loser.outdoor_courts, 0),
           'covered_courts',              nullif(v_loser.covered_courts, 0),
           'singles_courts',              nullif(v_loser.singles_courts, 0),
           'panoramic_courts',            nullif(v_loser.panoramic_courts, 0),
           'typical_court_price_peak',    v_loser.typical_court_price_peak,
           'typical_court_price_offpeak', v_loser.typical_court_price_offpeak,
           'currency',                    nullif(v_loser.currency, ''),
           'description',                 nullif(v_loser.description, ''),
           'surface_type',                nullif(v_loser.surface_type, ''),
           'phone',                       nullif(v_loser.phone, ''),
           'email',                       nullif(v_loser.email, ''),
           'website',                     nullif(v_loser.website, ''),
           'instagram',                   nullif(v_loser.instagram, ''),
           'booking_url',                 nullif(v_loser.booking_url, ''),
           'booking_platform',            nullif(v_loser.booking_platform, ''),
           'booking_advance_info',        nullif(v_loser.booking_advance_info, ''),
           'membership_note',             nullif(v_loser.membership_note, ''),
           'whatsapp_number',             nullif(v_loser.whatsapp_number, ''),
           'rating',                      v_loser.rating,
           'total_reviews',               nullif(v_loser.total_reviews, 0),
           'amenities',                   v_loser.amenities,
           'facilities',                  v_loser.facilities,
           'photos',                      v_loser.photos,
           'opening_hours',               v_loser.opening_hours,
           -- Booleans: only a TRUE is carried. A false on the loser must never
           -- turn a true on the survivor into anything, and coalesce() would
           -- happily write false over true if we passed it through.
           'is_members_only',             nullif(v_loser.is_members_only, false),
           'parking_available',           nullif(v_loser.parking_available, false),
           'changing_rooms',              nullif(v_loser.changing_rooms, false),
           'cafe_bar',                    nullif(v_loser.cafe_bar, false),
           'coaching_available',          nullif(v_loser.coaching_available, false),
           'equipment_rental',            nullif(v_loser.equipment_rental, false)
         )),
         jsonb_build_object('merged_from_name', v_loser.venue_name)
  on conflict do nothing;

  update public.venue_enrichment
     set venue_id = p_survivor_venue_id,
         external_id = coalesce(external_id, '') || ' (via ' || p_loser_venue_id::text || ')'
   where venue_id = p_loser_venue_id
     and not exists (
       select 1 from public.venue_enrichment e2
        where e2.venue_id = p_survivor_venue_id
          and e2.source = venue_enrichment.source
     );
  get diagnostics v_moved = row_count;

  update public.venue_claim_requests      set venue_id = p_survivor_venue_id where venue_id = p_loser_venue_id;
  update public.venue_claim_verifications set venue_id = p_survivor_venue_id where venue_id = p_loser_venue_id;

  -- THE LOCATION CONTRACT. Anything anchored to the loser follows the survivor.
  update public.matches set padel_venue_id = p_survivor_venue_id where padel_venue_id = p_loser_venue_id;
  get diagnostics v_m = row_count;
  update public.events  set padel_venue_id = p_survivor_venue_id where padel_venue_id = p_loser_venue_id;
  get diagnostics v_e = row_count;
  update public.leagues set padel_venue_id = p_survivor_venue_id where padel_venue_id = p_loser_venue_id;
  get diagnostics v_l = row_count;

  delete from public.venue_duplicate_dismissals
   where (venue_id_a = p_loser_venue_id and venue_id_b = p_survivor_venue_id)
      or (venue_id_a = p_survivor_venue_id and venue_id_b = p_loser_venue_id);

  update public.padel_venues
     set merged_into   = p_survivor_venue_id,
         status        = 'merged',
         needs_review  = false,
         review_reason = null,
         classified_by = p_actor,
         classified_at = now(),
         updated_at    = now()
   where venue_id = p_loser_venue_id;

  perform public.apply_venue_enrichment(p_survivor_venue_id);

  return jsonb_build_object(
    'success', true,
    'merged', v_loser.venue_name,
    'into', v_surv.venue_name,
    'enrichment_rows_moved', v_moved,
    'matches_repointed', v_m,
    'events_repointed', v_e,
    'leagues_repointed', v_l
  );
end;
$$;


ALTER FUNCTION "public"."_merge_venues"("p_loser_venue_id" "uuid", "p_survivor_venue_id" "uuid", "p_actor" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."accept_connection_request"("p_requester_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM player_connections
    WHERE user_id = p_requester_id
      AND connected_user_id = auth.uid()
      AND status = 'pending'
  ) THEN
    RAISE EXCEPTION 'No pending request from this user';
  END IF;

  UPDATE player_connections
  SET status = 'accepted', updated_at = now()
  WHERE user_id = p_requester_id
    AND connected_user_id = auth.uid()
    AND status = 'pending';

  INSERT INTO player_connections (user_id, connected_user_id, status)
  VALUES (auth.uid(), p_requester_id, 'accepted')
  ON CONFLICT (user_id, connected_user_id) DO UPDATE
    SET status = 'accepted', updated_at = now();
END;
$$;


ALTER FUNCTION "public"."accept_connection_request"("p_requester_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."accept_venue_contract"("p_contract_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_venue uuid;
begin
  select venue_id into v_venue from public.venue_contracts
    where id = p_contract_id and status = 'active';
  if v_venue is null then raise exception 'contract_not_found_or_inactive'; end if;
  if not exists (
    select 1 from public.venue_users vu
    where vu.venue_id = v_venue and vu.user_id = auth.uid()
      and vu.role = 'owner' and vu.status = 'active'
  ) then raise exception 'not_authorised'; end if;

  update public.venue_contracts
     set accepted_at = coalesce(accepted_at, now()),
         accepted_by = coalesce(accepted_by, auth.uid()),
         updated_at = now()
   where id = p_contract_id;

  -- Clear grandfather flag — venue is now on the standard active+accepted gate
  update public.venues
     set grandfathered_ppa_bookable = false
   where id = v_venue and grandfathered_ppa_bookable = true;

  return jsonb_build_object('contract_id', p_contract_id, 'accepted_at', now());
end $$;


ALTER FUNCTION "public"."accept_venue_contract"("p_contract_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."activate_venue_contract"("p_contract_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_c public.venue_contracts;
begin
  if not exists (select 1 from public.platform_admins where user_id = auth.uid())
  then raise exception 'not_authorised'; end if;

  select * into v_c from public.venue_contracts where id = p_contract_id;
  if not found then raise exception 'contract_not_found'; end if;

  -- Expire siblings
  update public.venue_contracts set status = 'expired', updated_at = now()
    where venue_id = v_c.venue_id and id <> p_contract_id and status = 'active';

  -- Atomically grant grace if venue is live (ppa_bookable)
  update public.venues set grandfathered_ppa_bookable = true
   where id = v_c.venue_id
     and grandfathered_ppa_bookable = false
     and exists (
       select 1 from public.padel_venues pv
        where pv.venues_id = v_c.venue_id and pv.ppa_bookable = true
     );

  -- Activate the new contract
  update public.venue_contracts set status = 'active',
    signed_by = coalesce(signed_by, auth.uid()),
    signed_at = coalesce(signed_at, now()),
    updated_at = now()
    where id = p_contract_id;

  -- Push terms to venues.*
  update public.venues set
    commission_rate_bps     = coalesce(v_c.commission_rate_bps, commission_rate_bps),
    plan_tier               = coalesce(v_c.plan_tier, plan_tier),
    monthly_price_pence     = v_c.monthly_price_pence,
    subscription_free_until = v_c.subscription_free_until,
    is_founding_venue       = true,
    deal_notes              = coalesce(v_c.special_terms, deal_notes)
  where id = v_c.venue_id;

  return jsonb_build_object('contract_id', p_contract_id, 'venue_id', v_c.venue_id, 'status', 'active');
end $$;


ALTER FUNCTION "public"."activate_venue_contract"("p_contract_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_venue_activity"("p_venue_id" "uuid", "p_kind" "text", "p_body" "text", "p_metadata" "jsonb" DEFAULT NULL::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_id uuid;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  if not exists (select 1 from public.platform_admins where user_id = v_uid)
  then raise exception 'not_authorized'; end if;

  insert into public.venue_activity_log (venue_id, actor_id, kind, body, metadata)
  values (p_venue_id, v_uid, p_kind, p_body, p_metadata)
  returning id into v_id;

  return v_id;
end $$;


ALTER FUNCTION "public"."add_venue_activity"("p_venue_id" "uuid", "p_kind" "text", "p_body" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_venue_teammate"("p_venue_id" "uuid", "p_email" "text", "p_role" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid;
  v_name text;
  v_existing record;
begin
  if not public._is_active_owner(p_venue_id) then
    return jsonb_build_object('status','not_authorised');
  end if;
  if p_role not in ('owner','manager','staff','coach') then
    return jsonb_build_object('status','bad_role');
  end if;

  select id, name into v_uid, v_name from public.profiles
    where lower(email) = lower(trim(p_email)) limit 1;
  if v_uid is null then
    return jsonb_build_object('status','no_account');
  end if;

  select * into v_existing from public.venue_users
    where venue_id = p_venue_id and user_id = v_uid limit 1;

  if v_existing.id is not null then
    if v_existing.status = 'active' then
      return jsonb_build_object('status','already_member','name',v_name);
    end if;
    update public.venue_users
      set role = p_role, status = 'active', accepted_at = now()
      where id = v_existing.id;
    return jsonb_build_object('status','added','name',v_name,'user_id',v_uid);
  end if;

  insert into public.venue_users (venue_id, user_id, role, status, invited_by, invited_at, accepted_at)
    values (p_venue_id, v_uid, p_role, 'active', auth.uid(), now(), now());
  return jsonb_build_object('status','added','name',v_name,'user_id',v_uid);
end;
$$;


ALTER FUNCTION "public"."add_venue_teammate"("p_venue_id" "uuid", "p_email" "text", "p_role" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_approve_claim"("p_venue_users_venue_id" "uuid", "p_venue_users_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_caller uuid := auth.uid();
begin
  if v_caller is null then raise exception 'not_authenticated'; end if;
  if not exists (select 1 from public.platform_admins where user_id = v_caller) then raise exception 'not_authorised'; end if;
  update public.venue_users set status = 'active'
    where venue_id = p_venue_users_venue_id and user_id = p_venue_users_user_id and status = 'pending';
  if not found then return jsonb_build_object('success', false, 'error', 'no_pending_claim_found'); end if;
  -- If this was a self-created venue awaiting review, publish it now.
  update public.padel_venues set status = 'active'
    where venues_id = p_venue_users_venue_id and status = 'pending_review';
  return jsonb_build_object('success', true);
end;
$$;


ALTER FUNCTION "public"."admin_approve_claim"("p_venue_users_venue_id" "uuid", "p_venue_users_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_billing_venues"() RETURNS TABLE("venue_id" "uuid", "venue_name" "text", "city" "text", "country" "text", "plan_tier" "text", "commission_rate_bps" integer, "is_founding_venue" boolean, "subscription_free_until" timestamp with time zone, "monthly_price_pence" integer, "deal_notes" "text", "currency" "text", "ppa_bookable" boolean, "charges_enabled" boolean, "owner_email" "text", "created_at" timestamp with time zone, "contract_id" "uuid", "contract_accepted_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not exists (
    select 1 from public.platform_admins pa where pa.user_id = auth.uid()
  ) then
    raise exception 'not_authorized';
  end if;

  return query
  select v.id,
         coalesce(v.name, pv.venue_name),
         coalesce(v.city, pv.city),
         coalesce(v.country, pv.country),
         v.plan_tier, v.commission_rate_bps, v.is_founding_venue,
         v.subscription_free_until, v.monthly_price_pence, v.deal_notes,
         coalesce(pv.currency, 'GBP'),
         coalesce(pv.ppa_bookable, false),
         coalesce(vsa.charges_enabled, false),
         (select p.email
            from public.venue_users vu
            join public.profiles p on p.id = vu.user_id
           where vu.venue_id = v.id
             and vu.role = 'owner' and vu.status = 'active'
           order by vu.created_at asc limit 1),
         v.created_at,
         ac.id,               -- contract_id
         ac.accepted_at       -- contract_accepted_at
    from public.venues v
    cross join lateral (                                   -- exactly one row per venue
      select c.id, c.accepted_at
        from public.venue_contracts c
       where c.venue_id = v.id and c.status = 'active'
       order by c.accepted_at desc nulls last,
                c.updated_at desc
       limit 1
    ) ac
    left join public.padel_venues pv on pv.venues_id = v.id
    left join public.venue_stripe_accounts vsa on vsa.venue_id = v.id
   order by v.created_at desc;
end $$;


ALTER FUNCTION "public"."admin_billing_venues"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_classify_venue"("p_venue_id" "uuid", "p_venue_type" "text" DEFAULT NULL::"text", "p_clear_review" boolean DEFAULT true, "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_caller uuid := auth.uid();
begin
  if v_caller is null then
    raise exception 'not_authenticated';
  end if;
  if not exists (select 1 from public.platform_admins where user_id = v_caller) then
    raise exception 'not_authorised';
  end if;
  if p_venue_type is not null and p_venue_type not in ('club', 'coach', 'not_padel') then
    raise exception 'invalid_venue_type';
  end if;

  update public.padel_venues
  set venue_type    = coalesce(p_venue_type, venue_type),
      classified_by = 'admin:' || v_caller::text,
      classified_at = now(),
      needs_review  = case when p_clear_review then false else needs_review end,
      review_reason = case
                        when p_clear_review then null
                        when p_note is not null then p_note
                        else review_reason
                      end
  where venue_id = p_venue_id;

  if not found then
    return jsonb_build_object('success', false, 'error', 'venue_not_found');
  end if;

  return jsonb_build_object('success', true);
end;
$$;


ALTER FUNCTION "public"."admin_classify_venue"("p_venue_id" "uuid", "p_venue_type" "text", "p_clear_review" boolean, "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_dismiss_duplicate_pair"("p_venue_id_a" "uuid", "p_venue_id_b" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_caller uuid := auth.uid();
  v_lo uuid := least(p_venue_id_a, p_venue_id_b);
  v_hi uuid := greatest(p_venue_id_a, p_venue_id_b);
begin
  if v_caller is null then raise exception 'not_authenticated'; end if;
  if not exists (select 1 from public.platform_admins where user_id = v_caller) then
    raise exception 'not_authorised';
  end if;
  if v_lo = v_hi then return jsonb_build_object('success', false, 'error', 'same_venue'); end if;

  insert into public.venue_duplicate_dismissals (venue_id_a, venue_id_b, dismissed_by, note)
  values (v_lo, v_hi, v_caller, p_note)
  on conflict (venue_id_a, venue_id_b) do nothing;

  return jsonb_build_object('success', true);
end;
$$;


ALTER FUNCTION "public"."admin_dismiss_duplicate_pair"("p_venue_id_a" "uuid", "p_venue_id_b" "uuid", "p_note" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_dismiss_duplicate_pair"("p_venue_id_a" "uuid", "p_venue_id_b" "uuid", "p_note" "text") IS 'Record that two venues are NOT duplicates, so the pair stops appearing in the candidate queue.';



CREATE OR REPLACE FUNCTION "public"."admin_founder_slots"() RETURNS TABLE("country_code" "text", "cap" integer, "used" integer, "remaining" integer, "enabled" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not exists (select 1 from public.platform_admins pa where pa.user_id = auth.uid()) then
    raise exception 'not_platform_admin';
  end if;
  return query
    select fp.country_code, fp.cap, coalesce(c.used,0)::int,
           case when fp.cap is null then null else greatest(fp.cap - coalesce(c.used,0),0) end::int,
           fp.enabled
    from public.founder_programs fp
    left join (
      select pricing_country_code AS cc, count(*) AS used
      from public.venue_contracts where founder_seq is not null group by pricing_country_code
    ) c on c.cc = fp.country_code
    where fp.country_code <> '*'
    order by fp.country_code;
end $$;


ALTER FUNCTION "public"."admin_founder_slots"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_list_venue_contracts"() RETURNS TABLE("venue_id" "uuid", "venue_name" "text", "city" "text", "owner_email" "text", "contract_id" "uuid", "status" "text", "signatory_name" "text", "company_name" "text", "vat_number" "text", "currency" "text", "plan_tier" "text", "founder_seq" integer, "commission_rate_bps" integer, "monthly_price_pence" integer, "monthly_credit_pence" integer, "subscription_free_until" timestamp with time zone, "start_date" "date", "end_date" "date", "special_terms" "text", "accepted_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not exists (select 1 from public.platform_admins where user_id = auth.uid()) then
    raise exception 'not_authorised';
  end if;
  return query
  select v.id, coalesce(v.name, pv.venue_name), coalesce(v.city, pv.city),
    (select p.email from public.venue_users vu join public.profiles p on p.id = vu.user_id
      where vu.venue_id = v.id and vu.role='owner' and vu.status='active' order by vu.created_at limit 1),
    c.id, c.status, c.signatory_name, c.company_name, c.vat_number,
    c.currency, c.plan_tier, c.founder_seq,
    c.commission_rate_bps, c.monthly_price_pence, c.monthly_credit_pence,
    c.subscription_free_until, c.start_date, c.end_date, c.special_terms,
    c.accepted_at, c.updated_at
  from public.venue_contracts c
  join public.venues v on v.id = c.venue_id
  left join public.padel_venues pv on pv.venues_id = v.id
  where c.status = (select x.status from public.venue_contracts x where x.venue_id = c.venue_id
                    order by (x.status='active') desc, x.updated_at desc limit 1)
  order by c.updated_at desc;
end $$;


ALTER FUNCTION "public"."admin_list_venue_contracts"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_merge_venues"("p_loser_venue_id" "uuid", "p_survivor_venue_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_caller uuid := auth.uid();
begin
  if v_caller is null then
    raise exception 'not_authenticated';
  end if;
  if not exists (select 1 from public.platform_admins where user_id = v_caller) then
    raise exception 'not_authorised';
  end if;

  return public._merge_venues(p_loser_venue_id, p_survivor_venue_id, 'admin:' || v_caller::text);
end;
$$;


ALTER FUNCTION "public"."admin_merge_venues"("p_loser_venue_id" "uuid", "p_survivor_venue_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_merge_venues"("p_loser_venue_id" "uuid", "p_survivor_venue_id" "uuid") IS 'Soft-merge a duplicate directory venue into another. Never deletes: the loser keeps its id so existing links resolve, gains merged_into, and leaves the directory via status=merged. Refuses claimed losers and merge chains.';



CREATE OR REPLACE FUNCTION "public"."admin_onboarding_insights"() RETURNS TABLE("venue_id" "uuid", "venue_name" "text", "city" "text", "country" "text", "offers_coaching" boolean, "current_provider" "text", "needs" "text"[], "created_at" timestamp with time zone, "owner_email" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not exists (select 1 from public.platform_admins pa where pa.user_id = auth.uid()) then
    raise exception 'not_authorized';
  end if;

  return query
  select
    vo.venue_id,
    coalesce(v.name, pv.venue_name)      as venue_name,
    coalesce(v.city, pv.city)            as city,
    coalesce(v.country, pv.country)      as country,
    vo.offers_coaching,
    vo.current_provider,
    vo.needs,
    vo.created_at,
    (select p.email
       from public.venue_users vu
       join public.profiles p on p.id = vu.user_id
      where vu.venue_id = vo.venue_id and vu.role = 'owner'
      order by vu.created_at asc
      limit 1)                            as owner_email
  from public.venue_onboarding vo
  left join public.venues v       on v.id = vo.venue_id
  left join public.padel_venues pv on pv.venues_id = vo.venue_id
  order by vo.created_at desc nulls last;
end;
$$;


ALTER FUNCTION "public"."admin_onboarding_insights"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_reject_claim"("p_venue_users_venue_id" "uuid", "p_venue_users_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_caller uuid := auth.uid();
begin
  if v_caller is null then raise exception 'not_authenticated'; end if;
  if not exists (select 1 from public.platform_admins where user_id = v_caller) then raise exception 'not_authorised'; end if;
  update public.venue_users set status = 'revoked'
    where venue_id = p_venue_users_venue_id and user_id = p_venue_users_user_id and status = 'pending';
  if not found then return jsonb_build_object('success', false, 'error', 'no_pending_claim_found'); end if;
  update public.padel_venues set status = 'rejected'
    where venues_id = p_venue_users_venue_id and status = 'pending_review';
  return jsonb_build_object('success', true);
end;
$$;


ALTER FUNCTION "public"."admin_reject_claim"("p_venue_users_venue_id" "uuid", "p_venue_users_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_resolve_venue_postcode"("p_venue_id" "uuid", "p_postcode" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_caller uuid := auth.uid();
  v_clean  text := nullif(btrim(p_postcode), '');
begin
  if v_caller is null then
    raise exception 'not_authenticated';
  end if;
  if not exists (select 1 from public.platform_admins where user_id = v_caller) then
    raise exception 'not_authorised';
  end if;
  if v_clean is null then
    raise exception 'postcode_required';
  end if;

  update public.padel_venues
  set postcode      = v_clean,
      -- postal_code is deprecated; a resolved conflict has one answer, not two.
      postal_code   = null,
      needs_review  = case
                        when review_reason = 'postcode and postal_code disagree' then false
                        else needs_review
                      end,
      review_reason = case
                        when review_reason = 'postcode and postal_code disagree' then null
                        else btrim(regexp_replace(review_reason,
                               '(; )?postcode and postal_code disagree', '', 'g'), '; ')
                      end
  where venue_id = p_venue_id;

  if not found then
    return jsonb_build_object('success', false, 'error', 'venue_not_found');
  end if;

  return jsonb_build_object('success', true, 'postcode', v_clean);
end;
$$;


ALTER FUNCTION "public"."admin_resolve_venue_postcode"("p_venue_id" "uuid", "p_postcode" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_review_venue"("p_padel_venue_id" "uuid", "p_approve" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_caller uuid := auth.uid();
begin
  if v_caller is null then raise exception 'not_authenticated'; end if;
  if not exists (select 1 from public.platform_admins where user_id = v_caller) then raise exception 'not_authorised'; end if;
  update public.padel_venues
     set status = case when p_approve then 'active' else 'rejected' end
   where venue_id = p_padel_venue_id and status = 'pending_review';
  if not found then return jsonb_build_object('success', false, 'error', 'no_pending_venue'); end if;
  return jsonb_build_object('success', true);
end; $$;


ALTER FUNCTION "public"."admin_review_venue"("p_padel_venue_id" "uuid", "p_approve" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_search_venues"("p_q" "text") RETURNS TABLE("venue_id" "uuid", "venue_name" "text", "city" "text", "country" "text", "has_owner" boolean, "has_contract" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not exists (
    select 1 from public.platform_admins where user_id = auth.uid()
  ) then
    raise exception 'not_authorised';
  end if;

  return query
  select v.id,
         coalesce(v.name, pv.venue_name),
         coalesce(v.city, pv.city),
         coalesce(v.country, pv.country),
         exists(select 1 from public.venue_users vu
                 where vu.venue_id = v.id and vu.status = 'active'
                   and vu.role = 'owner'),
         exists(select 1 from public.venue_contracts c
                 where c.venue_id = v.id)
    from public.venues v
    left join public.padel_venues pv on pv.venues_id = v.id
   where coalesce(p_q, '') <> ''
     and (
       coalesce(v.name, pv.venue_name) ilike '%' || p_q || '%'
       or coalesce(v.city, pv.city)    ilike '%' || p_q || '%'
       or pv.postcode                  ilike '%' || p_q || '%'
       or pv.full_address              ilike '%' || p_q || '%'
     )
   order by coalesce(v.name, pv.venue_name)
   limit 20;
end $$;


ALTER FUNCTION "public"."admin_search_venues"("p_q" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_venue_support"("p_venue_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_result jsonb;
begin
  -- Gate: platform admin + authenticated
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  if not exists (
    select 1 from public.platform_admins where user_id = auth.uid()
  ) then raise exception 'not_authorized'; end if;

  select jsonb_build_object(
    -- Core venue (venues table)
    'venue_id', v.id,
    'name', v.name,
    'city', v.city,
    'country', v.country,
    'plan_tier', v.plan_tier,
    'commission_rate_bps', v.commission_rate_bps,
    'is_founding_venue', v.is_founding_venue,
    'subscription_free_until', v.subscription_free_until,
    'monthly_price_pence', v.monthly_price_pence,
    'deal_notes', v.deal_notes,
    'created_at', v.created_at,

    -- Directory listing (padel_venues) — profile fields, no secrets
    'listing', (
      select jsonb_build_object(
        'venue_name', pv.venue_name,
        'description', pv.description,
        'full_address', pv.full_address,
        'city', pv.city,
        'postcode', pv.postcode,
        'country', pv.country,
        'country_code', pv.country_code,
        'phone', pv.phone,
        'email', pv.email,
        'website', pv.website,
        'instagram', pv.instagram,
        'booking_url', pv.booking_url,
        'booking_platform', pv.booking_platform,
        'indoor_courts', pv.indoor_courts,
        'outdoor_courts', pv.outdoor_courts,
        'covered_courts', pv.covered_courts,
        'surface_type', pv.surface_type,
        'number_of_courts', pv.number_of_courts,
        'price_per_hour', pv.price_per_hour,
        'currency', pv.currency,
        'ppa_bookable', pv.ppa_bookable,
        'rating', pv.rating,
        'review_count', pv.review_count,
        'photos', pv.photos,
        'amenities', pv.amenities,
        'opening_hours', pv.opening_hours,
        'status', pv.status,
        'verified', pv.verified,
        'dynamic_pricing_enabled', pv.dynamic_pricing_enabled
      )
      from public.padel_venues pv where pv.venues_id = v.id limit 1
    ),

    -- Stripe status — booleans only, NO stripe_account_id
    'stripe', (
      select jsonb_build_object(
        'charges_enabled', vsa.charges_enabled,
        'payouts_enabled', vsa.payouts_enabled,
        'details_submitted', vsa.details_submitted
      )
      from public.venue_stripe_accounts vsa where vsa.venue_id = v.id limit 1
    ),

    -- Latest contract
    'contract', (
      select jsonb_build_object(
        'id', c.id,
        'status', c.status,
        'signatory_name', c.signatory_name,
        'company_name', c.company_name,
        'vat_number', c.vat_number,
        'commission_rate_bps', c.commission_rate_bps,
        'monthly_price_pence', c.monthly_price_pence,
        'monthly_credit_pence', c.monthly_credit_pence,
        'subscription_free_until', c.subscription_free_until,
        'start_date', c.start_date,
        'end_date', c.end_date,
        'special_terms', c.special_terms,
        'accepted_at', c.accepted_at,
        'signed_at', c.signed_at,
        'updated_at', c.updated_at
      )
      from public.venue_contracts c
      where c.venue_id = v.id
      order by (c.status = 'active') desc, c.updated_at desc
      limit 1
    ),

    -- Team — roles, statuses, emails (CS needs emails to contact owners)
    'team', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'user_id', vu.user_id,
        'role', vu.role,
        'status', vu.status,
        'email', p.email,
        'created_at', vu.created_at
      ) order by vu.created_at), '[]'::jsonb)
      from public.venue_users vu
      join public.profiles p on p.id = vu.user_id
      where vu.venue_id = v.id
    ),

    -- Courts
    'courts', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'id', ct.id,
        'court_name', ct.court_name,
        'is_indoor', ct.is_indoor,
        'surface_type', ct.surface_type,
        'status', ct.status
      ) order by ct.court_name), '[]'::jsonb)
      from public.courts ct where ct.venue_id = v.id
    ),

    -- Availability settings
    'availability', (
      select jsonb_build_object(
        'open_time', cas.open_time,
        'close_time', cas.close_time,
        'slot_duration_min', cas.slot_duration_min,
        'max_advance_days', cas.max_advance_days,
        'cancellation_notice_hours', cas.cancellation_notice_hours
      )
      from public.court_availability_settings cas
      where cas.venue_id = v.id limit 1
    ),

    -- Active pricing rule count
    'pricing_rule_count', (
      select count(*) from public.pricing_rules pr
      where pr.venue_id = v.id and pr.active = true
    )
  )
  into v_result
  from public.venues v
  where v.id = p_venue_id;

  if v_result is null then raise exception 'venue_not_found'; end if;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."admin_venue_support"("p_venue_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_league_match_standings"("p_match_result_id" "uuid", "p_league_id" "uuid", "p_sets" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_already_processed boolean;
  v_set               jsonb;
  v_elo_update        jsonb;
  v_uid               uuid;
  v_new_elo           int;
  v_winners           uuid[];
  v_losers            uuid[];
  v_all_players       uuid[];
  v_is_draw           boolean;
  v_sets_applied      int := 0;
BEGIN
  SELECT league_standings_processed INTO v_already_processed
  FROM match_results WHERE id = p_match_result_id FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'match_result not found');
  END IF;
  IF v_already_processed THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'already_processed');
  END IF;

  FOR v_set IN SELECT * FROM jsonb_array_elements(p_sets)
  LOOP
    v_is_draw := (v_set->>'is_draw')::boolean;

    FOR v_elo_update IN SELECT * FROM jsonb_array_elements(v_set->'season_elo_updates')
    LOOP
      v_uid := (v_elo_update->>'user_id')::uuid;
      v_new_elo := (v_elo_update->>'new_season_elo')::int;
      UPDATE league_standings SET season_elo = v_new_elo
      WHERE league_id = p_league_id AND user_id = v_uid;
    END LOOP;

    SELECT ARRAY(SELECT (elem #>> '{}')::uuid FROM jsonb_array_elements(v_set->'winners') AS elem) INTO v_winners;
    SELECT ARRAY(SELECT (elem #>> '{}')::uuid FROM jsonb_array_elements(v_set->'losers') AS elem) INTO v_losers;

    IF v_is_draw THEN
      v_all_players := v_winners || v_losers;
      UPDATE league_standings
      SET draws = draws + 1, matches_played = matches_played + 1, ranking_points = ranking_points + league_points_for_result('draw')
      WHERE league_id = p_league_id AND user_id = ANY(v_all_players);
    ELSE
      UPDATE league_standings
      SET wins = wins + 1, matches_played = matches_played + 1, ranking_points = ranking_points + league_points_for_result('win')
      WHERE league_id = p_league_id AND user_id = ANY(v_winners);
      UPDATE league_standings
      SET losses = losses + 1, matches_played = matches_played + 1
      WHERE league_id = p_league_id AND user_id = ANY(v_losers);
    END IF;

    v_sets_applied := v_sets_applied + 1;
  END LOOP;

  UPDATE match_results SET league_standings_processed = true WHERE id = p_match_result_id;
  RETURN jsonb_build_object('applied_sets', v_sets_applied);
END;
$$;


ALTER FUNCTION "public"."apply_league_match_standings"("p_match_result_id" "uuid", "p_league_id" "uuid", "p_sets" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_match_elo"("p_match_result_id" "uuid", "p_match_id" "uuid", "p_updates" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_already_processed boolean;
  v_player            jsonb;
  v_player_id         uuid;
  v_rating_change     int;
  v_rating_before     int;
  v_rating_after      int;
  v_expected_score    numeric;
  v_actual_score      numeric;
  v_k_factor          int;
  v_opponent_ids      uuid[];
  v_opponent_avg      int;
  v_is_provisional    boolean;
  v_is_winner         boolean;
  v_applied           int := 0;
  v_today             date := CURRENT_DATE;
BEGIN
  -- 1. Idempotency gate (lock the match_result row)
  SELECT elo_processed INTO v_already_processed
  FROM match_results
  WHERE id = p_match_result_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'match_result not found');
  END IF;

  IF v_already_processed THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'already_processed');
  END IF;

  -- 2. Lock all participating player rows, sorted by id (deadlock-safe)
  PERFORM p.id
  FROM profiles p
  WHERE p.id IN (
    SELECT (elem->>'player_id')::uuid
    FROM jsonb_array_elements(p_updates) AS elem
  )
  ORDER BY p.id
  FOR UPDATE;

  -- 3. Apply each player's rating change as a DELTA
  FOR v_player IN SELECT * FROM jsonb_array_elements(p_updates)
  LOOP
    v_player_id      := (v_player->>'player_id')::uuid;
    v_rating_change  := (v_player->>'rating_change')::int;
    v_rating_before  := (v_player->>'rating_before')::int;
    v_rating_after   := (v_player->>'rating_after')::int;
    v_expected_score := (v_player->>'expected_score')::numeric;
    v_actual_score   := (v_player->>'actual_score')::numeric;
    v_k_factor       := (v_player->>'k_factor')::int;
    v_opponent_avg   := (v_player->>'opponent_avg_rating')::int;
    v_is_provisional := (v_player->>'is_provisional')::boolean;
    v_is_winner      := (v_player->>'is_winner')::boolean;

    SELECT ARRAY(
      SELECT (elem #>> '{}')::uuid
      FROM jsonb_array_elements(v_player->'opponent_ids') AS elem
    ) INTO v_opponent_ids;

    UPDATE profiles
    SET internal_ranking = GREATEST(0, LEAST(3000, internal_ranking + v_rating_change)),
        matches_played   = matches_played + 1,
        is_provisional   = (matches_played + 1) < 10,
        peak_elo         = CASE
                             WHEN GREATEST(0, LEAST(3000, internal_ranking + v_rating_change)) > COALESCE(peak_elo, 0)
                             THEN GREATEST(0, LEAST(3000, internal_ranking + v_rating_change))
                             ELSE peak_elo
                           END,
        peak_elo_date    = CASE
                             WHEN GREATEST(0, LEAST(3000, internal_ranking + v_rating_change)) > COALESCE(peak_elo, 0)
                             THEN v_today
                             ELSE peak_elo_date
                           END
    WHERE id = v_player_id;

    INSERT INTO rating_history (
      user_id, match_result_id, rating_before, rating_after, rating_change,
      expected_score, actual_score, k_factor, opponent_ids, opponent_avg_rating, is_provisional
    ) VALUES (
      v_player_id, p_match_result_id, v_rating_before, v_rating_after, v_rating_change,
      v_expected_score, v_actual_score, v_k_factor, v_opponent_ids, v_opponent_avg, v_is_provisional
    )
    ON CONFLICT (user_id, match_result_id) DO NOTHING;

    INSERT INTO ranking_changes (
      player_id, match_id, match_result_id, previous_points, new_points,
      points_change, opponent_ids, opponent_avg_rating, is_winner
    ) VALUES (
      v_player_id, p_match_id, p_match_result_id, v_rating_before, v_rating_after,
      v_rating_change, v_opponent_ids, v_opponent_avg, v_is_winner
    )
    ON CONFLICT (player_id, match_result_id) DO NOTHING;

    v_applied := v_applied + 1;
  END LOOP;

  -- 4. Mark processed (same transaction)
  UPDATE match_results
  SET elo_processed = true,
      verified_at = COALESCE(verified_at, NOW())
  WHERE id = p_match_result_id;

  RETURN jsonb_build_object('applied', v_applied);
END;
$$;


ALTER FUNCTION "public"."apply_match_elo"("p_match_result_id" "uuid", "p_match_id" "uuid", "p_updates" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_venue_enrichment"("p_venue_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_updated integer;
begin
  with winning as (
    select e.venue_id,
           kv.key,
           (array_agg(kv.value order by s.precedence desc, e.fetched_at desc))[1] as value
      from public.venue_enrichment e
      join public.venue_enrichment_sources s on s.source = e.source
      cross join lateral jsonb_each(jsonb_strip_nulls(e.payload)) kv
     where e.error is null
       and (p_venue_id is null or e.venue_id = p_venue_id)
     group by e.venue_id, kv.key
  ),
  merged as (
    select venue_id, jsonb_object_agg(key, value) as m
      from winning
     group by venue_id
  )
  update public.padel_venues t
     set number_of_courts            = coalesce((mg.m->>'number_of_courts')::integer, t.number_of_courts),
         indoor_courts               = coalesce((mg.m->>'indoor_courts')::integer, t.indoor_courts),
         outdoor_courts              = coalesce((mg.m->>'outdoor_courts')::integer, t.outdoor_courts),
         covered_courts              = coalesce((mg.m->>'covered_courts')::integer, t.covered_courts),
         singles_courts              = coalesce((mg.m->>'singles_courts')::integer, t.singles_courts),
         panoramic_courts            = coalesce((mg.m->>'panoramic_courts')::integer, t.panoramic_courts),
         typical_court_price_peak    = coalesce((mg.m->>'typical_court_price_peak')::numeric, t.typical_court_price_peak),
         typical_court_price_offpeak = coalesce((mg.m->>'typical_court_price_offpeak')::numeric, t.typical_court_price_offpeak),
         currency                    = coalesce(mg.m->>'currency', t.currency),
         description                 = coalesce(mg.m->>'description', t.description),
         surface_type                = coalesce(mg.m->>'surface_type', t.surface_type),
         phone                       = coalesce(mg.m->>'phone', t.phone),
         email                       = coalesce(mg.m->>'email', t.email),
         website                     = coalesce(mg.m->>'website', t.website),
         instagram                   = coalesce(mg.m->>'instagram', t.instagram),
         booking_url                 = coalesce(mg.m->>'booking_url', t.booking_url),
         booking_platform            = coalesce(mg.m->>'booking_platform', t.booking_platform),
         booking_advance_info        = coalesce(mg.m->>'booking_advance_info', t.booking_advance_info),
         membership_note             = coalesce(mg.m->>'membership_note', t.membership_note),
         whatsapp_number             = coalesce(mg.m->>'whatsapp_number', t.whatsapp_number),
         rating                      = coalesce((mg.m->>'rating')::numeric, t.rating),
         total_reviews               = coalesce((mg.m->>'total_reviews')::integer, t.total_reviews),
         amenities                   = coalesce(mg.m->'amenities', t.amenities),
         facilities                  = coalesce(mg.m->'facilities', t.facilities),
         photos                      = coalesce(mg.m->'photos', t.photos),
         opening_hours               = coalesce(mg.m->'opening_hours', t.opening_hours),
         is_members_only             = coalesce((mg.m->>'is_members_only')::boolean, t.is_members_only),
         parking_available           = coalesce((mg.m->>'parking_available')::boolean, t.parking_available),
         changing_rooms              = coalesce((mg.m->>'changing_rooms')::boolean, t.changing_rooms),
         cafe_bar                    = coalesce((mg.m->>'cafe_bar')::boolean, t.cafe_bar),
         coaching_available          = coalesce((mg.m->>'coaching_available')::boolean, t.coaching_available),
         equipment_rental            = coalesce((mg.m->>'equipment_rental')::boolean, t.equipment_rental),
         updated_at                  = now()
    from merged mg
   where t.venue_id = mg.venue_id
     and (
       t.venues_id is null
       or exists (
         select 1
           from public.venue_enrichment e2
           join public.venue_enrichment_sources s2 on s2.source = e2.source
          where e2.venue_id = t.venue_id
            and s2.precedence >= 90
       )
     );

  get diagnostics v_updated = row_count;

  return jsonb_build_object('success', true, 'venues_updated', v_updated);
end;
$$;


ALTER FUNCTION "public"."apply_venue_enrichment"("p_venue_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_venue_enrichment"("p_venue_id" "uuid") IS 'Merge venue_enrichment into padel_venues, highest-precedence source winning per field. Skips claimed venues unless an admin/owner source asserts. Idempotent.';



CREATE OR REPLACE FUNCTION "public"."are_connected"("a" "uuid", "b" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1 from public.player_connections pc
    where pc.status = 'accepted'
      and ((pc.user_id = a and pc.connected_user_id = b)
        or (pc.user_id = b and pc.connected_user_id = a))
  );
$$;


