CREATE OR REPLACE FUNCTION "public"."auto_resolve_expired_reviews"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_result record;
  v_proposal record;
BEGIN
  FOR v_result IN
    SELECT mr.id, mr.match_id, mr.last_proposal_by, mr.team1_players, mr.team2_players
    FROM match_results mr
    WHERE mr.verification_status IN ('submitter_review', 'opponent_review')
      AND mr.review_deadline IS NOT NULL
      AND mr.review_deadline < NOW()
  LOOP
    SELECT proposed_sets_data, proposed_team1_score, proposed_team2_score, proposed_result_type
    INTO v_proposal
    FROM match_result_votes
    WHERE match_result_id = v_result.id
      AND voter_id = v_result.last_proposal_by
      AND proposed_sets_data IS NOT NULL
    ORDER BY created_at DESC
    LIMIT 1;

    IF v_proposal IS NULL THEN
      RAISE WARNING 'auto_resolve: no proposal for match_result %, last_proposal_by %', v_result.id, v_result.last_proposal_by;
      CONTINUE;
    END IF;

    UPDATE match_results
    SET team1_score = v_proposal.proposed_team1_score,
        team2_score = v_proposal.proposed_team2_score,
        result_type = v_proposal.proposed_result_type,
        sets_data = v_proposal.proposed_sets_data,
        verification_status = 'verified',
        review_deadline = NULL,
        last_proposal_by = NULL
    WHERE id = v_result.id;

    INSERT INTO notifications (user_id, type, title, message, related_id, read)
    SELECT p.id, 'result_auto_accepted', 'Result auto-accepted',
           'No response within 24 hours. The proposed result has been accepted.',
           v_result.match_id, false
    FROM profiles p
    WHERE p.id = ANY(v_result.team1_players || v_result.team2_players);
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."auto_resolve_expired_reviews"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."auto_verify_expired_results"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  updated_count INTEGER;
BEGIN
  UPDATE match_results
  SET 
    verified = true,
    auto_verified = true,
    verified_at = NOW()
  WHERE 
    verified = false
    AND created_at < NOW() - INTERVAL '24 hours';
  
  GET DIAGNOSTICS updated_count = ROW_COUNT;
  
  RETURN updated_count;
END;
$$;


ALTER FUNCTION "public"."auto_verify_expired_results"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."auto_verify_old_pending_results"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_hours      int;
  v_result     record;
  v_recipients uuid[];
BEGIN
  SELECT COALESCE(value::int, 24)
    INTO v_hours
    FROM app_settings
   WHERE key = 'auto_verify_hours';

  IF v_hours IS NULL THEN
    v_hours := 24;
  END IF;

  FOR v_result IN
    SELECT id, match_id, team1_players, team2_players
    FROM match_results
    WHERE verification_status = 'pending'
      AND created_at < NOW() - make_interval(hours => v_hours)
    ORDER BY COALESCE(verified_at, created_at) ASC, created_at ASC, id ASC
  LOOP
    UPDATE match_results
    SET verification_status = 'verified',
        verified_at         = NOW()
    WHERE id = v_result.id;

    v_recipients := public.notifiable_players(
                      v_result.team1_players || v_result.team2_players
                    );

    IF array_length(v_recipients, 1) > 0 THEN
      INSERT INTO notifications (user_id, type, title, message, related_id, read)
      SELECT
        unnest(v_recipients),
        'result_verified',
        'Match result auto-verified',
        'No disputes within ' || v_hours || ' hours. ELO updated.',
        v_result.match_id,
        false;
    END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."auto_verify_old_pending_results"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."auto_verify_pending_results"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_result RECORD;
BEGIN
  FOR v_result IN (
    SELECT mr.id, mr.match_id
    FROM match_results mr
    WHERE mr.verification_status = 'pending'
      AND mr.verified = false
      AND (mr.is_friendly IS NULL OR mr.is_friendly = false)
      AND mr.created_at < NOW() - INTERVAL '24 hours'
  )
  LOOP
    UPDATE match_results
    SET
      verification_status = 'verified',
      verified             = true,
      auto_verified        = true,
      verified_at          = NOW(),
      verification_date    = NOW()
    WHERE id = v_result.id;

    UPDATE matches
    SET status = 'completed'
    WHERE id = v_result.match_id
      AND status != 'completed';

    RAISE NOTICE 'Auto-verified match result %', v_result.id;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."auto_verify_pending_results"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."auto_void_disputed_matches"() RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  UPDATE matches
  SET 
    status = 'voided',
    voided_at = NOW(),
    void_reason = 'Auto-voided after 7 days of unresolved dispute'
  WHERE id IN (
    SELECT DISTINCT match_id 
    FROM match_results 
    WHERE verification_status = 'disputed'
    AND disputed_at < NOW() - INTERVAL '7 days'
  )
  AND status != 'voided';
END;
$$;


ALTER FUNCTION "public"."auto_void_disputed_matches"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."award_career_badges_on_verify"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_player_ids   uuid[];
  v_uid          uuid;
  v_total        int;
  v_wins         int;
  v_win_rate     numeric;
  v_streak       int;
  v_group_count  int;
  v_result       record;
  v_is_winner    boolean;
  v_in_team1     boolean;

  v_badges jsonb := '{
    "first_win":     {"emoji": "🏆", "name": "First Victory"},
    "on_fire":       {"emoji": "🔥", "name": "On Fire"},
    "consistent":    {"emoji": "⚡", "name": "Consistent"},
    "sharp_shooter": {"emoji": "🎯", "name": "Sharp Shooter"},
    "social":        {"emoji": "👥", "name": "Social Butterfly"},
    "veteran":       {"emoji": "🌟", "name": "Veteran"},
    "perfectionist": {"emoji": "💎", "name": "Perfectionist"}
  }'::jsonb;
BEGIN
  -- Guard: only fire on transition TO verified
  IF NEW.verification_status <> 'verified' THEN RETURN NEW; END IF;
  IF OLD.verification_status IS NOT NULL AND OLD.verification_status = 'verified' THEN RETURN NEW; END IF;

  -- Wrap entire body so badge errors never block verification
  BEGIN
    v_player_ids := COALESCE(NEW.team1_players, '{}') || COALESCE(NEW.team2_players, '{}');
    IF array_length(v_player_ids, 1) IS NULL THEN RETURN NEW; END IF;

    FOREACH v_uid IN ARRAY v_player_ids LOOP
      SELECT
        COUNT(*),
        COUNT(*) FILTER (WHERE
          (mr.team1_players @> ARRAY[v_uid] AND mr.result_type = 'team1_win')
          OR (mr.team2_players @> ARRAY[v_uid] AND mr.result_type = 'team2_win')
        )
      INTO v_total, v_wins
      FROM match_results mr
      WHERE mr.verification_status = 'verified'
        AND (mr.team1_players @> ARRAY[v_uid] OR mr.team2_players @> ARRAY[v_uid]);

      v_win_rate := CASE WHEN v_total > 0 THEN (v_wins::numeric / v_total) * 100 ELSE 0 END;

      v_streak := 0;
      FOR v_result IN
        SELECT mr.result_type, mr.team1_players, mr.team2_players
        FROM match_results mr
        WHERE mr.verification_status = 'verified'
          AND (mr.team1_players @> ARRAY[v_uid] OR mr.team2_players @> ARRAY[v_uid])
        ORDER BY mr.created_at DESC
      LOOP
        v_in_team1 := v_result.team1_players @> ARRAY[v_uid];
        v_is_winner := (v_in_team1 AND v_result.result_type = 'team1_win')
                    OR (NOT v_in_team1 AND v_result.result_type = 'team2_win');
        IF v_is_winner THEN v_streak := v_streak + 1;
        ELSE EXIT;
        END IF;
      END LOOP;

      SELECT COUNT(*) INTO v_group_count
      FROM group_members
      WHERE user_id = v_uid AND status = 'approved';

      IF v_wins >= 1
         AND NOT EXISTS (SELECT 1 FROM user_badges WHERE user_id = v_uid AND badge_key = 'first_win')
      THEN
        INSERT INTO user_badges (user_id, badge_key) VALUES (v_uid, 'first_win');
        INSERT INTO notifications (user_id, type, title, message, related_id, read)
        VALUES (v_uid, 'achievement',
          (v_badges->'first_win'->>'emoji') || ' ' || (v_badges->'first_win'->>'name') || ' earned!',
          'Won your first match', v_uid, false);
      END IF;

      IF v_streak >= 3
         AND NOT EXISTS (SELECT 1 FROM user_badges WHERE user_id = v_uid AND badge_key = 'on_fire')
      THEN
        INSERT INTO user_badges (user_id, badge_key) VALUES (v_uid, 'on_fire');
        INSERT INTO notifications (user_id, type, title, message, related_id, read)
        VALUES (v_uid, 'achievement',
          (v_badges->'on_fire'->>'emoji') || ' ' || (v_badges->'on_fire'->>'name') || ' earned!',
          '3 wins in a row', v_uid, false);
      END IF;

      IF v_total >= 10
         AND NOT EXISTS (SELECT 1 FROM user_badges WHERE user_id = v_uid AND badge_key = 'consistent')
      THEN
        INSERT INTO user_badges (user_id, badge_key) VALUES (v_uid, 'consistent');
        INSERT INTO notifications (user_id, type, title, message, related_id, read)
        VALUES (v_uid, 'achievement',
          (v_badges->'consistent'->>'emoji') || ' ' || (v_badges->'consistent'->>'name') || ' earned!',
          'Played 10 matches', v_uid, false);
      END IF;

      IF v_total >= 10 AND v_win_rate >= 70
         AND NOT EXISTS (SELECT 1 FROM user_badges WHERE user_id = v_uid AND badge_key = 'sharp_shooter')
      THEN
        INSERT INTO user_badges (user_id, badge_key) VALUES (v_uid, 'sharp_shooter');
        INSERT INTO notifications (user_id, type, title, message, related_id, read)
        VALUES (v_uid, 'achievement',
          (v_badges->'sharp_shooter'->>'emoji') || ' ' || (v_badges->'sharp_shooter'->>'name') || ' earned!',
          '70%+ win rate (10+ matches)', v_uid, false);
      END IF;

      IF v_group_count >= 3
         AND NOT EXISTS (SELECT 1 FROM user_badges WHERE user_id = v_uid AND badge_key = 'social')
      THEN
        INSERT INTO user_badges (user_id, badge_key) VALUES (v_uid, 'social');
        INSERT INTO notifications (user_id, type, title, message, related_id, read)
        VALUES (v_uid, 'achievement',
          (v_badges->'social'->>'emoji') || ' ' || (v_badges->'social'->>'name') || ' earned!',
          'Member of 3+ groups', v_uid, false);
      END IF;

      IF v_total >= 50
         AND NOT EXISTS (SELECT 1 FROM user_badges WHERE user_id = v_uid AND badge_key = 'veteran')
      THEN
        INSERT INTO user_badges (user_id, badge_key) VALUES (v_uid, 'veteran');
        INSERT INTO notifications (user_id, type, title, message, related_id, read)
        VALUES (v_uid, 'achievement',
          (v_badges->'veteran'->>'emoji') || ' ' || (v_badges->'veteran'->>'name') || ' earned!',
          '50+ matches played', v_uid, false);
      END IF;

      -- perfectionist (repeatable)
      v_in_team1 := NEW.team1_players @> ARRAY[v_uid];
      v_is_winner := (v_in_team1 AND NEW.result_type = 'team1_win')
                  OR (NOT v_in_team1 AND NEW.result_type = 'team2_win');

      IF v_is_winner AND NEW.sets_data IS NOT NULL THEN
        DECLARE
          v_sets     jsonb;
          v_set      jsonb;
          v_set_count int;
          v_all_perfect boolean := true;
          v_my_score   int;
          v_their_score int;
        BEGIN
          v_sets := CASE
            WHEN jsonb_typeof(NEW.sets_data::jsonb) = 'array' THEN NEW.sets_data::jsonb
            ELSE '[]'::jsonb
          END;
          v_set_count := jsonb_array_length(v_sets);
          IF v_set_count >= 2 THEN
            FOR i IN 0 .. v_set_count - 1 LOOP
              v_set := v_sets->i;
              IF v_in_team1 THEN
                v_my_score := COALESCE((v_set->>'team1')::int, (v_set->>'team1_score')::int, -1);
                v_their_score := COALESCE((v_set->>'team2')::int, (v_set->>'team2_score')::int, -1);
              ELSE
                v_my_score := COALESCE((v_set->>'team2')::int, (v_set->>'team2_score')::int, -1);
                v_their_score := COALESCE((v_set->>'team1')::int, (v_set->>'team1_score')::int, -1);
              END IF;
              IF v_my_score <> 6 OR v_their_score <> 0 THEN
                v_all_perfect := false;
                EXIT;
              END IF;
            END LOOP;
            IF v_all_perfect THEN
              INSERT INTO user_badges (user_id, badge_key) VALUES (v_uid, 'perfectionist');
              INSERT INTO notifications (user_id, type, title, message, related_id, read)
              VALUES (v_uid, 'achievement',
                (v_badges->'perfectionist'->>'emoji') || ' ' || (v_badges->'perfectionist'->>'name') || ' earned!',
                'Won 6-0, 6-0', v_uid, false);
            END IF;
          END IF;
        END;
      END IF;

    END LOOP;

  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING '[career-badges] failed for match_result %: %', NEW.id, SQLERRM;
  END;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."award_career_badges_on_verify"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."award_entertainer_jersey"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_week_start       date := (date_trunc('week', CURRENT_DATE) - INTERVAL '7 days')::date;
  v_league           record;
  v_top_count        bigint;
  v_winner_id        uuid;
  v_current_holder   uuid;
  v_history_exists   boolean;
BEGIN
  FOR v_league IN SELECT id FROM leagues WHERE status = 'active' LOOP

    SELECT MAX(vote_count) INTO v_top_count
    FROM get_weekly_league_vote_standings(v_league.id, v_week_start);

    IF v_top_count IS NULL OR v_top_count = 0 THEN CONTINUE; END IF;

    SELECT user_id INTO v_current_holder
    FROM league_jerseys
    WHERE league_id = v_league.id AND jersey_type = 'entertainer';

    IF v_current_holder IS NOT NULL AND EXISTS (
      SELECT 1 FROM get_weekly_league_vote_standings(v_league.id, v_week_start)
      WHERE user_id = v_current_holder AND vote_count = v_top_count
    ) THEN
      v_winner_id := v_current_holder;
    ELSE
      SELECT user_id INTO v_winner_id
      FROM get_weekly_league_vote_standings(v_league.id, v_week_start)
      WHERE vote_count = v_top_count
      ORDER BY user_id ASC
      LIMIT 1;
    END IF;

    IF v_winner_id IS NULL THEN CONTINUE; END IF;

    SELECT EXISTS (
      SELECT 1 FROM entertainer_jersey_history
      WHERE league_id = v_league.id AND week_start = v_week_start
    ) INTO v_history_exists;

    IF NOT v_history_exists THEN
      INSERT INTO entertainer_jersey_history (league_id, user_id, week_start, vote_count)
      VALUES (v_league.id, v_winner_id, v_week_start, v_top_count)
      ON CONFLICT (league_id, week_start) DO NOTHING;

      IF v_current_holder IS NULL OR v_current_holder <> v_winner_id THEN
        INSERT INTO notifications (user_id, type, title, message, related_id, read)
        VALUES (
          v_winner_id,
          'achievement',
          '🔵 Entertainer Jersey!',
          'You''re the Entertainer — most peer votes in your league this week (' || v_top_count || ').',
          v_league.id,
          false
        );
      END IF;
    END IF;

    INSERT INTO league_jerseys (league_id, user_id, jersey_color, jersey_type, awarded_week, reason, previous_holder)
    VALUES (
      v_league.id,
      v_winner_id,
      'blue',
      'entertainer',
      v_week_start,
      'Entertainer — most peer votes (' || v_top_count || ')',
      v_current_holder
    )
    ON CONFLICT (league_id, jersey_type)
    DO UPDATE SET
      previous_holder = league_jerseys.user_id,
      user_id         = EXCLUDED.user_id,
      awarded_week    = EXCLUDED.awarded_week,
      reason          = EXCLUDED.reason
    WHERE league_jerseys.awarded_week < EXCLUDED.awarded_week
       OR league_jerseys.user_id <> EXCLUDED.user_id;

  END LOOP;
END;
$$;


ALTER FUNCTION "public"."award_entertainer_jersey"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."award_giant_slayer_on_rating"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Skip during rebuild (session variable set by rebuild-ratings)
  IF current_setting('app.skip_badge_triggers', true) = 'true' THEN
    RETURN NEW;
  END IF;

  BEGIN
    IF NEW.actual_score <> 1 THEN RETURN NEW; END IF;
    IF NEW.opponent_avg_rating - NEW.rating_before < 200 THEN RETURN NEW; END IF;

    INSERT INTO user_badges (user_id, badge_key, match_result_id)
    VALUES (NEW.user_id, 'giant_slayer', NEW.match_result_id)
    ON CONFLICT (user_id, badge_key, match_result_id) WHERE badge_key = 'giant_slayer'
    DO NOTHING;

    IF FOUND THEN
      INSERT INTO notifications (user_id, type, title, message, related_id, read)
      VALUES (
        NEW.user_id,
        'achievement',
        '🗡️ Giant Slayer earned!',
        'Beat opponents rated 200+ ELO above you',
        NEW.user_id,
        false
      );
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING '[giant-slayer] failed for user % on rating_history insert: %', NEW.user_id, SQLERRM;
  END;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."award_giant_slayer_on_rating"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."award_peer_vote_badges"("p_user_ids" "uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid           uuid;
  v_row           record;
  v_existing_tier text;
  v_new_tier      text;
  v_tier_rank_old int;
  v_tier_rank_new int;
  v_emoji         text;
  v_badge_name    text;
  v_tier_label    text;
  v_badges        jsonb := '{
    "shot_of_match":      {"emoji": "🎾", "name": "Shot of the Match"},
    "tactical_genius":    {"emoji": "🧠", "name": "Tactical Genius"},
    "best_recovery_shot": {"emoji": "🪃", "name": "Best Recovery Shot"},
    "comedy_gold":        {"emoji": "😂", "name": "Comedy Gold"},
    "hustle_award":       {"emoji": "💪", "name": "Hustle Award"}
  }'::jsonb;
BEGIN
  FOREACH v_uid IN ARRAY p_user_ids LOOP
    FOR v_row IN
      SELECT vote_category, vote_count
      FROM get_verified_peer_vote_counts(v_uid)
    LOOP
      IF NOT v_badges ? v_row.vote_category THEN CONTINUE; END IF;

      IF    v_row.vote_count >= 40 THEN v_new_tier := 'gold';
      ELSIF v_row.vote_count >= 15 THEN v_new_tier := 'silver';
      ELSIF v_row.vote_count >= 5  THEN v_new_tier := 'bronze';
      ELSE  CONTINUE;
      END IF;

      SELECT tier INTO v_existing_tier
      FROM user_badges
      WHERE user_id = v_uid AND badge_key = v_row.vote_category;

      v_tier_rank_old := CASE v_existing_tier
        WHEN 'gold' THEN 3 WHEN 'silver' THEN 2 WHEN 'bronze' THEN 1 ELSE 0 END;
      v_tier_rank_new := CASE v_new_tier
        WHEN 'gold' THEN 3 WHEN 'silver' THEN 2 WHEN 'bronze' THEN 1 ELSE 0 END;

      IF v_tier_rank_old >= v_tier_rank_new THEN CONTINUE; END IF;

      IF v_existing_tier IS NOT NULL THEN
        UPDATE user_badges
        SET tier = v_new_tier, earned_at = now()
        WHERE user_id = v_uid AND badge_key = v_row.vote_category;
      ELSE
        INSERT INTO user_badges (user_id, badge_key, tier)
        VALUES (v_uid, v_row.vote_category, v_new_tier);
      END IF;

      v_emoji := v_badges->v_row.vote_category->>'emoji';
      v_badge_name := v_badges->v_row.vote_category->>'name';
      v_tier_label := INITCAP(v_new_tier);

      INSERT INTO notifications (user_id, type, title, message, related_id, read)
      VALUES (
        v_uid,
        'achievement',
        v_emoji || ' ' || v_tier_label || ' ' || v_badge_name || '!',
        'You''ve received ' || v_row.vote_count || ' verified votes — ' || v_tier_label || ' tier unlocked.',
        v_uid,
        false
      );
    END LOOP;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."award_peer_vote_badges"("p_user_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."award_weekly_jerseys"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_league         record;
  v_yellow_uid     uuid;
  v_black_uid      uuid;
  v_green_uid1     uuid;
  v_green_uid2     uuid;
  v_green_gap      int;
  v_green_reason   text;
  v_red_uid        uuid;
  v_red_gain       int;
  v_week_start     date := (date_trunc('week', CURRENT_DATE) - INTERVAL '7 days')::date;
  v_week_end       date := (date_trunc('week', CURRENT_DATE))::date;
  v_prev_yellow    uuid;
  v_prev_black     uuid;
  v_prev_green     uuid[];
  v_prev_red       uuid;
  v_lost_uid       uuid;
BEGIN
  FOR v_league IN SELECT id FROM leagues WHERE status = 'active' LOOP

    v_yellow_uid := NULL; v_black_uid := NULL;
    v_green_uid1 := NULL; v_green_uid2 := NULL; v_green_gap := NULL;
    v_red_uid := NULL; v_red_gain := NULL;

    SELECT user_id INTO v_prev_yellow
    FROM league_jerseys
    WHERE league_id = v_league.id AND jersey_type = 'yellow'
    LIMIT 1;

    SELECT user_id INTO v_prev_black
    FROM league_jerseys
    WHERE league_id = v_league.id AND jersey_type = 'black'
    LIMIT 1;

    SELECT ARRAY(
      SELECT user_id FROM league_jerseys
      WHERE league_id = v_league.id AND jersey_type = 'green'
    ) INTO v_prev_green;

    SELECT user_id INTO v_prev_red
    FROM league_jerseys
    WHERE league_id = v_league.id AND jersey_type = 'red'
    LIMIT 1;

    DELETE FROM league_jerseys
    WHERE league_id = v_league.id
      AND jersey_type IN ('yellow', 'black', 'green', 'red');

    DROP TABLE IF EXISTS tmp_game_diff;
    CREATE TEMP TABLE tmp_game_diff AS
      SELECT
        pid AS user_id,
        SUM(CASE WHEN mr.team1_players @> ARRAY[pid]
                 THEN COALESCE((s.val->>'team1')::int, (s.val->>'team1_score')::int, 0)
                 ELSE COALESCE((s.val->>'team2')::int, (s.val->>'team2_score')::int, 0) END) AS games_won,
        SUM(CASE WHEN mr.team1_players @> ARRAY[pid]
                 THEN COALESCE((s.val->>'team2')::int, (s.val->>'team2_score')::int, 0)
                 ELSE COALESCE((s.val->>'team1')::int, (s.val->>'team1_score')::int, 0) END) AS games_lost
      FROM match_results mr
      JOIN matches m ON m.id = mr.match_id AND m.league_id = v_league.id
      CROSS JOIN LATERAL jsonb_array_elements(mr.sets_data) AS s(val)
      CROSS JOIN LATERAL unnest(mr.team1_players || mr.team2_players) AS pid
      WHERE mr.verification_status = 'verified'
      GROUP BY pid;

    SELECT ls.user_id INTO v_yellow_uid
    FROM league_standings ls
    JOIN profiles p ON p.id = ls.user_id
    LEFT JOIN tmp_game_diff gd ON gd.user_id = ls.user_id
    WHERE ls.league_id = v_league.id AND ls.matches_played > 0
    ORDER BY (ls.ranking_points + 9.0) / (ls.matches_played + 6) DESC,
             ls.ranking_points DESC,
             ls.matches_played ASC,
             (COALESCE(gd.games_won,0)-COALESCE(gd.games_lost,0)) DESC,
             p.internal_ranking ASC
    LIMIT 1;

    IF v_yellow_uid IS NOT NULL THEN
      INSERT INTO league_jerseys (league_id, user_id, jersey_color, jersey_type, awarded_week, reason)
      VALUES (v_league.id, v_yellow_uid, 'yellow', 'yellow', CURRENT_DATE, 'League leader');
    END IF;

    SELECT ls.user_id INTO v_black_uid
    FROM league_standings ls
    JOIN profiles p ON p.id = ls.user_id
    LEFT JOIN tmp_game_diff gd ON gd.user_id = ls.user_id
    WHERE ls.league_id = v_league.id AND ls.matches_played > 0
    ORDER BY (ls.ranking_points + 9.0) / (ls.matches_played + 6) ASC,
             ls.ranking_points ASC,
             ls.matches_played DESC,
             (COALESCE(gd.games_won,0)-COALESCE(gd.games_lost,0)) ASC,
             p.internal_ranking DESC
    LIMIT 1;

    IF v_black_uid IS NOT NULL THEN
      INSERT INTO league_jerseys (league_id, user_id, jersey_color, jersey_type, awarded_week, reason)
      VALUES (v_league.id, v_black_uid, 'black', 'black', CURRENT_DATE, 'Bottom of standings');
    END IF;

    DROP TABLE IF EXISTS tmp_green_candidates;
    CREATE TEMP TABLE tmp_green_candidates AS
    WITH sets_expanded AS (
      SELECT
        mr.id AS match_result_id,
        mr.team1_players,
        mr.team2_players,
        mr.verified_at,
        COALESCE((s.val->>'team1')::int, (s.val->>'team1_score')::int, 0) AS g1,
        COALESCE((s.val->>'team2')::int, (s.val->>'team2_score')::int, 0) AS g2,
        s.ordinality AS set_num
      FROM match_results mr
      JOIN matches m ON m.id = mr.match_id AND m.league_id = v_league.id
      CROSS JOIN LATERAL jsonb_array_elements(mr.sets_data) WITH ORDINALITY AS s(val, ordinality)
      WHERE mr.verification_status = 'verified'
        AND NOT COALESCE(mr.is_friendly, false)
        AND COALESCE(mr.verified_at, mr.created_at) >= v_week_start
        AND COALESCE(mr.verified_at, mr.created_at) < v_week_end
    ),
    classified_sets AS (
      SELECT
        se.*,
        c.is_completed,
        c.is_void,
        CASE
          WHEN se.g1 > se.g2 THEN 'team1'
          WHEN se.g2 > se.g1 THEN 'team2'
          ELSE NULL
        END AS winning_team
      FROM sets_expanded se
      CROSS JOIN LATERAL classify_set_sql(se.g1, se.g2) c
    ),
    qualifying_sets AS (
      SELECT
        cs.match_result_id,
        cs.team1_players,
        cs.team2_players,
        cs.verified_at,
        cs.winning_team,
        cs.set_num,
        (SELECT COALESCE(SUM(rh.rating_before), 0)
         FROM rating_history rh
         WHERE rh.match_result_id = cs.match_result_id
           AND rh.user_id = ANY(cs.team1_players)) AS team1_combined_elo,
        (SELECT COALESCE(SUM(rh.rating_before), 0)
         FROM rating_history rh
         WHERE rh.match_result_id = cs.match_result_id
           AND rh.user_id = ANY(cs.team2_players)) AS team2_combined_elo
      FROM classified_sets cs
      WHERE NOT cs.is_void
        AND cs.winning_team IS NOT NULL
    )
    SELECT
      qs.match_result_id,
      qs.verified_at,
      qs.winning_team,
      qs.team1_players,
      qs.team2_players,
      CASE qs.winning_team
        WHEN 'team1' THEN qs.team2_combined_elo - qs.team1_combined_elo
        WHEN 'team2' THEN qs.team1_combined_elo - qs.team2_combined_elo
      END AS elo_gap
    FROM qualifying_sets qs
    WHERE CASE qs.winning_team
            WHEN 'team1' THEN qs.team2_combined_elo - qs.team1_combined_elo
            WHEN 'team2' THEN qs.team1_combined_elo - qs.team2_combined_elo
          END >= 150;

    SELECT
      CASE winning_team
        WHEN 'team1' THEN team1_players[1]
        WHEN 'team2' THEN team2_players[1]
      END,
      CASE winning_team
        WHEN 'team1' THEN team1_players[2]
        WHEN 'team2' THEN team2_players[2]
      END,
      elo_gap
    INTO v_green_uid1, v_green_uid2, v_green_gap
    FROM tmp_green_candidates
    ORDER BY elo_gap DESC, verified_at DESC, match_result_id DESC
    LIMIT 1;

    IF v_green_uid1 IS NOT NULL THEN
      v_green_reason := 'Underdog — ' || v_green_gap || ' ELO gap upset';

      INSERT INTO league_jerseys (league_id, user_id, jersey_color, jersey_type, awarded_week, reason)
      VALUES (v_league.id, v_green_uid1, 'green', 'green', CURRENT_DATE, v_green_reason);

      IF v_green_uid2 IS NOT NULL THEN
        INSERT INTO league_jerseys (league_id, user_id, jersey_color, jersey_type, awarded_week, reason)
        VALUES (v_league.id, v_green_uid2, 'green', 'green', CURRENT_DATE, v_green_reason);
      END IF;
    END IF;

    SELECT rh.user_id, SUM(rh.rating_change) AS total_gain
    INTO v_red_uid, v_red_gain
    FROM rating_history rh
    JOIN match_results mr ON mr.id = rh.match_result_id
    JOIN matches m ON m.id = mr.match_id AND m.league_id = v_league.id
    WHERE mr.verification_status = 'verified'
      AND NOT COALESCE(mr.is_friendly, false)
      AND COALESCE(mr.verified_at, mr.created_at) >= v_week_start
      AND COALESCE(mr.verified_at, mr.created_at) < v_week_end
    GROUP BY rh.user_id
    HAVING SUM(rh.rating_change) > 0
    ORDER BY SUM(rh.rating_change) DESC,
             (SELECT internal_ranking FROM profiles WHERE id = rh.user_id) ASC,
             rh.user_id ASC
    LIMIT 1;

    IF v_red_uid IS NOT NULL THEN
      INSERT INTO league_jerseys (league_id, user_id, jersey_color, jersey_type, awarded_week, reason)
      VALUES (v_league.id, v_red_uid, 'red', 'red', CURRENT_DATE,
              'Most Improved — +' || v_red_gain || ' ELO this week');
    END IF;

    IF v_yellow_uid IS NOT NULL AND (v_prev_yellow IS NULL OR v_prev_yellow <> v_yellow_uid) THEN
      INSERT INTO notifications (user_id, type, title, message, related_id, read)
      VALUES (v_yellow_uid, 'achievement', '🟡 League Leader!',
              'You''re top of the standings — the yellow jersey is yours!',
              v_league.id, false);
    END IF;
    IF v_prev_yellow IS NOT NULL AND (v_yellow_uid IS NULL OR v_prev_yellow <> v_yellow_uid) THEN
      INSERT INTO notifications (user_id, type, title, message, related_id, read)
      VALUES (v_prev_yellow, 'achievement', 'Yellow jersey passed on',
              'You''ve lost the league leader jersey. Fight back next week!',
              v_league.id, false);
    END IF;

    IF v_black_uid IS NOT NULL AND (v_prev_black IS NULL OR v_prev_black <> v_black_uid) THEN
      INSERT INTO notifications (user_id, type, title, message, related_id, read)
      VALUES (v_black_uid, 'achievement', '⚫ Wooden Spoon!',
              'You''re holding the wooden spoon — time to climb the table!',
              v_league.id, false);
    END IF;
    IF v_prev_black IS NOT NULL AND (v_black_uid IS NULL OR v_prev_black <> v_black_uid) THEN
      INSERT INTO notifications (user_id, type, title, message, related_id, read)
      VALUES (v_prev_black, 'achievement', 'Spoon passed on!',
              'You''ve escaped the wooden spoon — keep it up!',
              v_league.id, false);
    END IF;

    IF v_green_uid1 IS NOT NULL THEN
      IF v_prev_green IS NULL OR NOT (v_green_uid1 = ANY(v_prev_green)) THEN
        INSERT INTO notifications (user_id, type, title, message, related_id, read)
        VALUES (v_green_uid1, 'achievement', '🟢 Underdog!',
                'Your team beat a much stronger pair — ' || v_green_gap || ' ELO gap upset!',
                v_league.id, false);
      END IF;
      IF v_green_uid2 IS NOT NULL AND (v_prev_green IS NULL OR NOT (v_green_uid2 = ANY(v_prev_green))) THEN
        INSERT INTO notifications (user_id, type, title, message, related_id, read)
        VALUES (v_green_uid2, 'achievement', '🟢 Underdog!',
                'Your team beat a much stronger pair — ' || v_green_gap || ' ELO gap upset!',
                v_league.id, false);
      END IF;
    END IF;
    IF v_prev_green IS NOT NULL AND array_length(v_prev_green, 1) > 0 THEN
      FOREACH v_lost_uid IN ARRAY v_prev_green LOOP
        IF v_green_uid1 IS NOT NULL AND v_lost_uid = v_green_uid1 THEN CONTINUE; END IF;
        IF v_green_uid2 IS NOT NULL AND v_lost_uid = v_green_uid2 THEN CONTINUE; END IF;
        INSERT INTO notifications (user_id, type, title, message, related_id, read)
        VALUES (v_lost_uid, 'achievement', 'Underdog jersey passed on',
                'Another team pulled off a bigger upset this week.',
                v_league.id, false);
      END LOOP;
    END IF;

    IF v_red_uid IS NOT NULL AND (v_prev_red IS NULL OR v_prev_red <> v_red_uid) THEN
      INSERT INTO notifications (user_id, type, title, message, related_id, read)
      VALUES (v_red_uid, 'achievement', '🔴 Most Improved!',
              'You gained the most ELO in your league this week — +' || v_red_gain || '!',
              v_league.id, false);
    END IF;
    IF v_prev_red IS NOT NULL AND (v_red_uid IS NULL OR v_prev_red <> v_red_uid) THEN
      INSERT INTO notifications (user_id, type, title, message, related_id, read)
      VALUES (v_prev_red, 'achievement', 'Most Improved jersey passed on',
              'Someone else had a bigger ELO gain this week.',
              v_league.id, false);
    END IF;

  END LOOP;

  DROP TABLE IF EXISTS tmp_game_diff;
  DROP TABLE IF EXISTS tmp_green_candidates;
END;
$$;


ALTER FUNCTION "public"."award_weekly_jerseys"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."book_class"("p_session_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_sess public.coaching_sessions%rowtype;
  v_count int;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  select * into v_sess from public.coaching_sessions where id = p_session_id for update;
  if not found then raise exception 'not_found'; end if;
  if v_sess.status <> 'scheduled' then return jsonb_build_object('status','unavailable'); end if;
  if v_sess.start_at < now() then return jsonb_build_object('status','past'); end if;
  if exists (select 1 from public.coaching_bookings
             where session_id = p_session_id and player_id = v_uid and status = 'booked') then
    return jsonb_build_object('status','already_booked');
  end if;
  select count(*) into v_count from public.coaching_bookings
    where session_id = p_session_id and status = 'booked';
  if v_count >= v_sess.capacity then return jsonb_build_object('status','full'); end if;
  insert into public.coaching_bookings (session_id, player_id, status)
    values (p_session_id, v_uid, 'booked')
    on conflict (session_id, player_id) do update set status = 'booked';
  return jsonb_build_object('status','booked');
end $$;


ALTER FUNCTION "public"."book_class"("p_session_id" "uuid") OWNER TO "postgres";


