CREATE OR REPLACE FUNCTION "public"."calculate_league_tiers"("p_league_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_league RECORD;
  v_total_players INTEGER;
  v_elite_count INTEGER;
  v_championship_count INTEGER;
  v_challenger_count INTEGER;
BEGIN
  -- Get league details
  SELECT * INTO v_league FROM leagues WHERE id = p_league_id;
  
  -- Only process if tier system is enabled
  IF NOT v_league.enable_tier_system THEN
    RETURN;
  END IF;
  
  -- Count total players
  SELECT COUNT(DISTINCT user_id) INTO v_total_players
  FROM league_standings
  WHERE league_id = p_league_id AND category = 'overall';
  
  IF v_total_players = 0 THEN
    RETURN;
  END IF;
  
  -- Calculate tier sizes
  v_elite_count := GREATEST(1, ROUND(v_total_players * (v_league.tier_percentages->>'elite')::numeric / 100));
  v_championship_count := GREATEST(1, ROUND(v_total_players * (v_league.tier_percentages->>'championship')::numeric / 100));
  v_challenger_count := GREATEST(1, ROUND(v_total_players * (v_league.tier_percentages->>'challenger')::numeric / 100));
  
  -- Clear existing tiers
  DELETE FROM league_tiers WHERE league_id = p_league_id;
  
  -- Create Elite tier
  INSERT INTO league_tiers (league_id, tier_name, tier_level, min_rank, max_rank, tier_color, tier_icon)
  VALUES (
    p_league_id,
    'Elite Division',
    1,
    1,
    v_elite_count,
    'text-yellow-500',
    '🥇'
  );
  
  -- Create Championship tier
  INSERT INTO league_tiers (league_id, tier_name, tier_level, min_rank, max_rank, tier_color, tier_icon)
  VALUES (
    p_league_id,
    'Championship',
    2,
    v_elite_count + 1,
    v_elite_count + v_championship_count,
    'text-blue-500',
    '⭐'
  );
  
  -- Create Challenger tier
  INSERT INTO league_tiers (league_id, tier_name, tier_level, min_rank, max_rank, tier_color, tier_icon)
  VALUES (
    p_league_id,
    'Challenger',
    3,
    v_elite_count + v_championship_count + 1,
    v_elite_count + v_championship_count + v_challenger_count,
    'text-purple-500',
    '🎯'
  );
  
  -- Create Rising Stars tier
  INSERT INTO league_tiers (league_id, tier_name, tier_level, min_rank, max_rank, tier_color, tier_icon)
  VALUES (
    p_league_id,
    'Rising Stars',
    4,
    v_elite_count + v_championship_count + v_challenger_count + 1,
    v_total_players,
    'text-green-500',
    '🌱'
  );
END;
$$;


ALTER FUNCTION "public"."calculate_league_tiers"("p_league_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_margin_multiplier"("games_diff" integer) RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN CASE games_diff
    WHEN 0 THEN 1.0
    WHEN 1 THEN 1.2
    WHEN 2 THEN 1.5
    WHEN 3 THEN 1.8
    WHEN 4 THEN 2.0
    WHEN 5 THEN 2.3
    ELSE 2.5
  END;
END;
$$;


ALTER FUNCTION "public"."calculate_margin_multiplier"("games_diff" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_see_group"("_group_id" "uuid", "_user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1 from public.groups g
     where g.id = _group_id
       and (
         g.visibility in ('public', 'open')
         or g.admin_id = _user_id
       )
  )
  or exists (
    select 1 from public.group_members gm
     where gm.group_id = _group_id
       and gm.user_id  = _user_id
       and gm.status in ('approved', 'ringer', 'pending', 'pending_ringer')
  );
$$;


ALTER FUNCTION "public"."can_see_group"("_group_id" "uuid", "_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_class"("p_session_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_uid uuid := auth.uid();
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  update public.coaching_bookings set status = 'cancelled'
    where session_id = p_session_id and player_id = v_uid and status = 'booked';
  return jsonb_build_object('status','cancelled');
end $$;


