CREATE OR REPLACE FUNCTION "public"."change_plan_contract"("p_venue_id" "uuid", "p_plan_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid         uuid := auth.uid();
  v_old         public.venue_contracts;
  v_plan        public.standard_plans;
  v_cc          text;
  v_price       record;
  v_listed      public.country_plan_prices;
  v_currency    text;
  v_monthly     integer;
  v_contract_id uuid;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;

  if not exists (
    select 1 from public.venue_users vu
     where vu.venue_id = p_venue_id and vu.user_id = v_uid
       and vu.role = 'owner' and vu.status = 'active'
  ) then raise exception 'not_venue_owner'; end if;

  select * into v_old
    from public.venue_contracts
   where venue_id = p_venue_id and status = 'active'
     for update;
  if not found then raise exception 'no_active_contract'; end if;

  if v_old.founder_seq is not null then
    raise exception 'founder_contract_admin_only';
  end if;

  select * into v_plan from public.standard_plans where key = p_plan_key;
  if not found then raise exception 'invalid_plan'; end if;

  if v_old.plan_tier = p_plan_key then raise exception 'plan_unchanged'; end if;

  select pv.country_code into v_cc
    from public.padel_venues pv
   where pv.venues_id = p_venue_id
   limit 1;

  select * into v_price from public.resolve_country_pricing(v_cc);
  select * into v_listed
    from public.country_plan_prices
   where country_code = v_cc and plan_key = p_plan_key;

  if v_plan.court_hour_multiple = 0 then
    v_monthly  := 0;
    v_currency := coalesce(v_listed.currency, v_old.currency, v_price.currency);
  else
    if v_listed.country_code is null then
      raise exception 'pricing_unavailable_in_country';
    end if;
    v_monthly  := v_listed.monthly_price_minor;
    v_currency := v_listed.currency;
  end if;

  update public.venue_contracts
     set status     = 'superseded',
         updated_at = now(),
         notes      = concat_ws(E'\n', nullif(notes, ''),
                        format('Superseded %s: plan changed %s -> %s by %s',
                               current_date, v_old.plan_tier, p_plan_key, v_uid))
   where id = v_old.id;

  insert into public.venue_contracts (
    venue_id, status,
    signatory_name, signatory_role, signatory_email,
    company_name, company_registration, vat_number,
    billing_contact_name, billing_contact_email,
    currency, plan_tier, commission_rate_bps,
    monthly_price_pence, monthly_credit_pence,
    subscription_free_until,
    auto_renew, notice_period_days, special_terms,
    start_date, signed_by, signed_at, created_by,
    pricing_country_code, pricing_band_key, reference_court_hour_minor, court_hour_multiple
  ) values (
    p_venue_id, 'active',
    v_old.signatory_name, v_old.signatory_role, v_old.signatory_email,
    v_old.company_name, v_old.company_registration, v_old.vat_number,
    v_old.billing_contact_name, v_old.billing_contact_email,
    v_currency, p_plan_key, v_plan.commission_rate_bps,
    v_monthly, 0,
    v_old.subscription_free_until,
    v_plan.auto_renew, v_plan.notice_period_days, v_plan.special_terms,
    current_date, v_uid, now(), v_uid,
    v_cc, v_price.band_key, v_price.reference_court_hour_minor, v_plan.court_hour_multiple
  ) returning id into v_contract_id;

  update public.venues set
    commission_rate_bps = v_plan.commission_rate_bps,
    plan_tier           = p_plan_key,
    monthly_price_pence = v_monthly,
    currency            = v_currency
  where id = p_venue_id;

  return jsonb_build_object(
    'contract_id', v_contract_id,
    'superseded_contract_id', v_old.id,
    'previous_plan', v_old.plan_tier,
    'plan', p_plan_key,
    'currency', v_currency,
    'monthly_price_minor', v_monthly,
    'pricing_country', v_cc
  );
end $$;


ALTER FUNCTION "public"."change_plan_contract"("p_venue_id" "uuid", "p_plan_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_cron_health"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_job record; v_prev record; v_status text; v_should_alert boolean;
  v_title text; v_msg text;
  v_alerts int := 0; v_checked int := 0; v_unhealthy int := 0;
BEGIN
  FOR v_job IN
    WITH runs AS (
      SELECT d.jobid, d.status, d.return_message, d.start_time,
             row_number() OVER (PARTITION BY d.jobid ORDER BY d.start_time DESC) AS rn,
             lag(d.start_time) OVER (PARTITION BY d.jobid ORDER BY d.start_time DESC) AS newer_start
      FROM cron.job_run_details d
      WHERE d.start_time > now() - interval '30 days'
    ),
    cadence AS (
      SELECT jobid, percentile_cont(0.5) WITHIN GROUP (
               ORDER BY EXTRACT(epoch FROM (newer_start - start_time))) AS median_gap_secs
      FROM runs WHERE rn <= 10 AND newer_start IS NOT NULL GROUP BY jobid
    ),
    latest AS (SELECT jobid, status, return_message, start_time FROM runs WHERE rn = 1),
    fails AS (
      SELECT d.jobid, count(*) AS failures_24h FROM cron.job_run_details d
      WHERE d.status = 'failed' AND d.start_time > now() - interval '24 hours' GROUP BY d.jobid
    )
    SELECT j.jobid, j.jobname, l.status AS last_status, l.return_message,
           l.start_time AS last_run_at, COALESCE(f.failures_24h, 0) AS failures_24h,
           c.median_gap_secs
    FROM cron.job j
    LEFT JOIN latest l ON l.jobid = j.jobid
    LEFT JOIN fails f ON f.jobid = j.jobid
    LEFT JOIN cadence c ON c.jobid = j.jobid
    WHERE j.active
  LOOP
    v_checked := v_checked + 1;

    SELECT * INTO v_prev FROM cron_health_state WHERE jobid = v_job.jobid;

    IF v_job.last_run_at IS NULL THEN
      IF COALESCE(v_prev.first_seen_at, now()) > now() - interval '24 hours' THEN
        v_status := 'pending';
      ELSE
        v_status := 'stalled';
      END IF;
    ELSIF v_job.median_gap_secs IS NOT NULL
          AND v_job.last_run_at < now() - make_interval(
                secs => GREATEST(v_job.median_gap_secs * 3, 5400)) THEN
      v_status := 'stalled';
    ELSIF v_job.last_status = 'failed' THEN
      v_status := 'failing';
    ELSIF v_job.failures_24h >= 3 THEN
      v_status := 'degraded';
    ELSE
      v_status := 'ok';
    END IF;

    IF v_status NOT IN ('ok', 'pending') THEN
      v_unhealthy := v_unhealthy + 1;
    END IF;

    v_should_alert :=
         (v_status NOT IN ('ok','pending')
            AND (v_prev.jobid IS NULL OR v_prev.status IN ('ok','pending')))
      OR (v_status NOT IN ('ok','pending') AND v_prev.alerted_at IS NOT NULL
            AND v_prev.alerted_at < now() - interval '24 hours')
      OR (v_status = 'ok' AND v_prev.jobid IS NOT NULL
            AND v_prev.status NOT IN ('ok','pending'));

    IF v_should_alert THEN
      IF v_status = 'ok' THEN
        v_title := 'Scheduled job recovered';
        v_msg   := v_job.jobname || ' is running cleanly again.';
      ELSIF v_status = 'stalled' THEN
        v_title := 'Scheduled job stalled';
        v_msg   := v_job.jobname || ' has stopped running. Last run: '
                   || COALESCE(v_job.last_run_at::text, 'never') || '.';
      ELSIF v_status = 'degraded' THEN
        v_title := 'Scheduled job unstable';
        v_msg   := v_job.jobname || ' last run passed but failed '
                   || v_job.failures_24h || ' time(s) in 24h.';
      ELSE
        v_title := 'Scheduled job failing';
        v_msg   := v_job.jobname || ' failed ' || v_job.failures_24h
                   || ' time(s) in 24h. ' || left(COALESCE(v_job.return_message, ''), 160);
      END IF;

      PERFORM public.notify_platform_admins('cron_health', v_title, v_msg);
      v_alerts := v_alerts + 1;
    END IF;

    INSERT INTO cron_health_state AS s
      (jobid, jobname, status, failures_24h, last_run_at, last_error, alerted_at, first_seen_at, last_checked_at)
    VALUES
      (v_job.jobid, v_job.jobname, v_status, v_job.failures_24h, v_job.last_run_at,
       left(v_job.return_message, 500),
       CASE WHEN v_should_alert THEN now() ELSE NULL END,
       COALESCE(v_prev.first_seen_at, now()), now())
    ON CONFLICT (jobid) DO UPDATE SET
      jobname = EXCLUDED.jobname, status = EXCLUDED.status,
      failures_24h = EXCLUDED.failures_24h, last_run_at = EXCLUDED.last_run_at,
      last_error = EXCLUDED.last_error,
      alerted_at = CASE WHEN v_should_alert THEN now() ELSE s.alerted_at END,
      last_checked_at = now();
  END LOOP;

  RETURN jsonb_build_object('checked', v_checked, 'unhealthy', v_unhealthy, 'alerts_sent', v_alerts);
END;
$$;


ALTER FUNCTION "public"."check_cron_health"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_overdue_matches"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_match record;
  v_deadline timestamptz;
BEGIN
  FOR v_match IN
    SELECT m.id, m.match_date, m.match_time, m.player_ids
    FROM matches m
    WHERE m.status IN ('scheduled', 'pending', 'confirmed', 'open')
      AND NOT EXISTS (SELECT 1 FROM match_results mr WHERE mr.match_id = m.id)
  LOOP
    v_deadline := (v_match.match_date::timestamp +
      COALESCE(v_match.match_time::time, '00:00:00'::time) +
      INTERVAL '24 hours');

    IF v_deadline < NOW() THEN
      UPDATE matches SET status = 'cancelled' WHERE id = v_match.id;

      INSERT INTO notifications (user_id, type, title, message, related_id, read)
      SELECT p.id, 'match_auto_cancelled', 'Match auto-cancelled',
             'No result entered within 24 hours of match time.',
             v_match.id, false
      FROM profiles p
      WHERE p.id = ANY(v_match.player_ids);
    END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."check_overdue_matches"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_self_conflict"("p_user_id" "uuid", "p_match_date" "date", "p_match_time" time without time zone, "p_exclude_match_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("conflicting_match_id" "uuid", "conflicting_time" time without time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  DECLARE
    v_window_start time;
    v_window_end   time;
  BEGIN
    IF p_match_time IS NULL THEN
      RETURN QUERY                                                                                              
      SELECT m.id, m.match_time::time
      FROM matches m                                                                                            
      WHERE m.match_date = p_match_date                     
        AND m.status NOT IN ('cancelled', 'completed')
        AND p_user_id = ANY(m.player_ids)                                                                       
        AND (p_exclude_match_id IS NULL OR m.id <> p_exclude_match_id);
      RETURN;                                                                                                   
    END IF;                                                 
                                                                                                                
    v_window_start := p_match_time - interval '90 minutes'; 
    v_window_end   := p_match_time + interval '30 minutes';
                                                                                                                
    RETURN QUERY
    SELECT m.id, m.match_time::time                                                                             
    FROM matches m                                          
    WHERE m.match_date = p_match_date
      AND m.status NOT IN ('cancelled', 'completed')
      AND p_user_id = ANY(m.player_ids)                                                                         
      AND (p_exclude_match_id IS NULL OR m.id <> p_exclude_match_id)
      AND (                                                                                                     
        m.match_time IS NULL                                
        OR (m.match_time::time >= v_window_start AND m.match_time::time <= v_window_end)                        
      );
  END;                                                                                                          
  $$;


ALTER FUNCTION "public"."check_self_conflict"("p_user_id" "uuid", "p_match_date" "date", "p_match_time" time without time zone, "p_exclude_match_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_match_guest_invite"("p_token" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_inv public.match_guest_invites%ROWTYPE;
  v_pids uuid[];
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('error', 'not_authenticated');
  END IF;

  SELECT * INTO v_inv FROM public.match_guest_invites WHERE invite_token = p_token FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'invalid_token'); END IF;
  IF v_inv.status = 'accepted' THEN
    RETURN jsonb_build_object('match_id', v_inv.match_id, 'already_claimed', true);
  END IF;
  IF v_inv.status = 'cancelled' THEN RETURN jsonb_build_object('error', 'cancelled'); END IF;
  IF v_inv.expires_at < now() THEN RETURN jsonb_build_object('error', 'expired'); END IF;

  SELECT coalesce(player_ids, '{}'::uuid[]) INTO v_pids FROM public.matches WHERE id = v_inv.match_id FOR UPDATE;

  IF v_uid = ANY(v_pids) THEN
    -- already a player in this match: just drop the placeholder slot
    v_pids := array_remove(v_pids, v_inv.slot_player_id);
  ELSE
    v_pids := array_replace(v_pids, v_inv.slot_player_id, v_uid);
  END IF;

  UPDATE public.matches SET player_ids = v_pids WHERE id = v_inv.match_id;
  UPDATE public.match_guest_invites
    SET status = 'accepted', claimed_by = v_uid, accepted_at = now()
    WHERE id = v_inv.id;

  RETURN jsonb_build_object('match_id', v_inv.match_id, 'ok', true);
END; $$;


ALTER FUNCTION "public"."claim_match_guest_invite"("p_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_open_match"("p_match_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  DECLARE
    v_user_id uuid := auth.uid();
    v_match record;
    v_user_elo integer;
    v_claimer_name text;
    v_new_player_ids uuid[];
    v_conflict record;
  BEGIN
    IF v_user_id IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;

    SELECT * INTO v_match FROM matches WHERE id = p_match_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Match not found'; END IF;
    IF NOT v_match.is_open THEN RAISE EXCEPTION 'Match is no longer open'; END IF;
    IF array_length(v_match.player_ids, 1) >= 4 THEN RAISE EXCEPTION 'Match is full'; END IF;
    IF v_user_id = ANY(COALESCE(v_match.player_ids, ARRAY[]::uuid[])) THEN
      RAISE EXCEPTION 'You are already in this match';
    END IF;

    SELECT internal_ranking INTO v_user_elo FROM profiles WHERE id = v_user_id;
    IF v_user_elo IS NULL THEN RAISE EXCEPTION 'No ELO on profile'; END IF;
    -- NULL bounds mean "no band" — a broadcast is open to anyone who can see
    -- it, and RLS has already decided who that is.
    IF v_match.open_elo_min IS NOT NULL AND v_user_elo < v_match.open_elo_min THEN
      RAISE EXCEPTION 'Your ELO is outside the match range';
    END IF;
    IF v_match.open_elo_max IS NOT NULL AND v_user_elo > v_match.open_elo_max THEN
      RAISE EXCEPTION 'Your ELO is outside the match range';
    END IF;

    SELECT * INTO v_conflict
    FROM check_self_conflict(v_user_id, v_match.match_date, v_match.match_time::time, p_match_id)
    LIMIT 1;
    IF FOUND THEN
      RAISE EXCEPTION 'You already have a match scheduled at %. Can''t accept another.',
        COALESCE(to_char(v_conflict.conflicting_time, 'HH24:MI'), 'that time');
    END IF;

    v_new_player_ids := COALESCE(v_match.player_ids, ARRAY[]::uuid[]) || v_user_id;

    UPDATE matches
    SET player_ids = v_new_player_ids,
        is_open = CASE WHEN array_length(v_new_player_ids, 1) >= 4 THEN false ELSE is_open END,
        open_elo_min = CASE WHEN array_length(v_new_player_ids, 1) >= 4 THEN NULL ELSE open_elo_min END,
        open_elo_max = CASE WHEN array_length(v_new_player_ids, 1) >= 4 THEN NULL ELSE open_elo_max END,
        -- Two players is a game arranged. Promote it out of 'open'.
        status = CASE WHEN array_length(v_new_player_ids, 1) >= 2 AND status = 'open'
                      THEN 'scheduled' ELSE status END,
        updated_at = now()
    WHERE id = p_match_id;

    UPDATE ringer_requests
    SET status = 'filled_by_other', responded_at = now()
    WHERE match_id = p_match_id AND status = 'pending';

    SELECT name INTO v_claimer_name FROM profiles WHERE id = v_user_id;
    v_claimer_name := COALESCE(v_claimer_name, 'A player');

    INSERT INTO notifications (user_id, type, title, message, related_id)
    SELECT unnest(v_match.player_ids), 'open_match_claimed',
      v_claimer_name || ' joined your match',
      v_claimer_name || ' has claimed the open spot.',
      p_match_id;

    INSERT INTO notifications (user_id, type, title, message, related_id)
    VALUES (v_user_id, 'open_match_confirmed', 'You''re in!',
      'You''ve claimed an open match. Check details.', p_match_id);

    RETURN jsonb_build_object('success', true);
  END;
$$;


ALTER FUNCTION "public"."claim_open_match"("p_match_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_venue"("p_padel_venue_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user uuid := auth.uid();
  v_anchor uuid;
  v_listing public.padel_venues%ROWTYPE;
  v_existing uuid;
begin
  if v_user is null then raise exception 'not_authenticated'; end if;
  select * into v_listing from public.padel_venues where venue_id = p_padel_venue_id;
  if not found then raise exception 'venue_not_found'; end if;
  if v_listing.venues_id is not null then
    v_anchor := v_listing.venues_id;
  else
    insert into public.venues (name, country, city, address, latitude, longitude,
                               booking_url, has_app_booking, booking_type)
    values (coalesce(v_listing.venue_name, 'Unnamed venue'),
            coalesce(v_listing.country, 'United Kingdom'),
            v_listing.city, v_listing.full_address,
            v_listing.latitude, v_listing.longitude,
            v_listing.booking_url, true, 'link')
    returning id into v_anchor;
    update public.padel_venues set venues_id = v_anchor where venue_id = p_padel_venue_id;
  end if;
  select venue_id into v_existing
    from public.venue_users where venue_id = v_anchor and user_id = v_user;
  if found then raise exception 'already_claimed'; end if;
  if exists (select 1 from public.venue_users
              where venue_id = v_anchor and role = 'owner'
                and status = 'active' and user_id <> v_user) then
    raise exception 'venue_already_owned';
  end if;
  insert into public.venue_users (venue_id, user_id, role, status)
  values (v_anchor, v_user, 'owner', 'pending');
  return v_anchor;
end;
$$;


ALTER FUNCTION "public"."claim_venue"("p_padel_venue_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_venue_transfer"("p_padel_venue_id" "uuid", "p_token" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_caller uuid := auth.uid();
  v_caller_email text;
  v_invite record;
begin
  if v_caller is null then raise exception 'not_authenticated'; end if;
  select email into v_caller_email from auth.users where id = v_caller;
  select * into v_invite
  from public.venue_claim_invites
  where padel_venue_id = p_padel_venue_id and token = p_token
    and used_at is null and expires_at > now()
  limit 1;
  if v_invite.id is null then
    return jsonb_build_object('success', false, 'error', 'invalid_or_expired');
  end if;
  if lower(v_caller_email) <> lower(v_invite.email) then
    return jsonb_build_object('success', false, 'error', 'email_mismatch');
  end if;
  delete from public.venue_users
   where venue_id = v_invite.venues_id and role = 'owner' and user_id <> v_caller;
  insert into public.venue_users (venue_id, user_id, role, status)
    values (v_invite.venues_id, v_caller, 'owner', 'active')
    on conflict (venue_id, user_id) do update set role = 'owner', status = 'active';
  update public.padel_venues set status = 'active', verified = true
    where venue_id = p_padel_venue_id;
  update public.venue_claim_invites set used_at = now() where id = v_invite.id;
  return jsonb_build_object('success', true);
end;
$$;


ALTER FUNCTION "public"."claim_venue_transfer"("p_padel_venue_id" "uuid", "p_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."classify_set_sql"("p_g1" integer, "p_g2" integer) RETURNS TABLE("is_completed" boolean, "is_void" boolean, "winner" integer)
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT
    comp,
    (NOT comp) AND (p_g1 + p_g2) < 6,
    CASE WHEN p_g1 > p_g2 THEN 1 WHEN p_g2 > p_g1 THEN 2 ELSE 0 END
  FROM (
    SELECT (GREATEST(p_g1, p_g2) >= 6 AND ABS(p_g1 - p_g2) >= 2)
        OR (GREATEST(p_g1, p_g2) = 7 AND LEAST(p_g1, p_g2) = 6) AS comp
  ) c;
$$;


ALTER FUNCTION "public"."classify_set_sql"("p_g1" integer, "p_g2" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cleanup_expired_investor_tokens"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  DELETE FROM investor_verification_tokens
  WHERE expires_at < now() OR (used = true AND created_at < now() - INTERVAL '7 days');
END;
$$;


ALTER FUNCTION "public"."cleanup_expired_investor_tokens"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_expired_polls"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_poll     record;
  v_admin    record;
  v_count    integer := 0;
  v_auto     boolean;
  v_secret   text;
  v_url      text := 'https://timbjfihsxqfrqrxwdny.supabase.co/functions/v1/poll-scheduler';
BEGIN
  SELECT decrypted_secret INTO v_secret
  FROM vault.decrypted_secrets
  WHERE name = 'poll_cron_secret';

  FOR v_poll IN
    SELECT p.id, p.title, p.group_id
    FROM polls p
    WHERE p.status = 'open'
      AND p.closes_at IS NOT NULL
      AND p.closes_at < now()
  LOOP
    UPDATE polls
    SET status = 'closed', updated_at = now()
    WHERE id = v_poll.id;

    SELECT COALESCE(auto_match_enabled, false) INTO v_auto
    FROM groups WHERE id = v_poll.group_id;

    IF v_auto AND v_secret IS NOT NULL THEN
      -- Auto-generate: call the edge function
      PERFORM net.http_post(
        url := v_url,
        headers := jsonb_build_object(
          'Content-Type', 'application/json',
          'x-cron-secret', v_secret
        ),
        body := jsonb_build_object('mode', 'auto', 'poll_id', v_poll.id)
      );
    ELSE
      -- Notify admins to generate manually
      FOR v_admin IN
        SELECT gm.user_id
        FROM group_members gm
        WHERE gm.group_id = v_poll.group_id
          AND gm.role = 'admin'
      LOOP
        INSERT INTO notifications (user_id, type, title, message, related_id, read)
        VALUES (
          v_admin.user_id,
          'poll',
          'Poll closed — matches needed',
          'Voting has closed on "' || v_poll.title || '". Open the poll to generate matches.',
          v_poll.id,
          false
        );
      END LOOP;
    END IF;

    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."close_expired_polls"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."compute_notification_nav_url"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  NEW.nav_url := CASE
    -- Your own share of a court booking: straight to the payment page.
    WHEN NEW.type = 'booking_payment_due'
      THEN '/pay/booking/' || COALESCE(NEW.related_id::text, '') || '/player/' || NEW.user_id::text

    WHEN NEW.type IN (
      'group_invite', 'group_join', 'group_join_request',
      'group_update', 'announcement',
      'ringer_offer', 'ringer_approved', 'ringer_declined'
    ) THEN '/community/groups/' || COALESCE(NEW.related_id::text, '')

    WHEN NEW.type IN (
      'match_created', 'match_result', 'match_suggested', 'match_scheduled',
      'result_verify', 'result_pending_verification', 'result_verified', 'result_disputed',
      'match_result_prompt', 'match_deadline_approaching', 'match_auto_cancelled',
      'match_invitation', 'match_reminder',
      'lift_requested', 'lift_accepted', 'lift_declined'
    ) THEN '/matches/' || COALESCE(NEW.related_id::text, '')

    WHEN NEW.type LIKE 'ringer_for_%' THEN '/matches/' || COALESCE(NEW.related_id::text, '')
    WHEN NEW.type LIKE 'open_match_%' THEN '/matches/' || COALESCE(NEW.related_id::text, '')
    WHEN NEW.type LIKE 'invitation_%' THEN '/matches/' || COALESCE(NEW.related_id::text, '')
    WHEN NEW.type LIKE 'invitee_%'    THEN '/matches/' || COALESCE(NEW.related_id::text, '')

    WHEN NEW.type IN ('league_invite', 'league_update')
      THEN '/compete/leagues/' || COALESCE(NEW.related_id::text, '')
    WHEN NEW.type LIKE 'league_%'
      THEN '/compete/leagues/' || COALESCE(NEW.related_id::text, '')

    WHEN NEW.type IN ('poll_created')
      THEN '/play/availability/' || COALESCE(NEW.related_id::text, '')
    WHEN NEW.type LIKE 'poll_%'
      THEN '/play/availability/' || COALESCE(NEW.related_id::text, '')

    WHEN NEW.type IN ('connection_request', 'connection_accepted')
      THEN '/community#connections'

    WHEN NEW.type = 'achievement' THEN '/you'
    WHEN NEW.type LIKE 'household_%' THEN '/you'

    WHEN NEW.type = 'court_booked'
      THEN '/matches/' || COALESCE(NEW.related_id::text, '')

    WHEN NEW.type LIKE '%match%'  THEN '/matches/' || COALESCE(NEW.related_id::text, '')
    WHEN NEW.type LIKE '%league%' THEN '/compete/leagues/' || COALESCE(NEW.related_id::text, '')
    WHEN NEW.type LIKE '%group%'  THEN '/community/groups/' || COALESCE(NEW.related_id::text, '')
    WHEN NEW.type LIKE '%poll%'   THEN '/play/availability/' || COALESCE(NEW.related_id::text, '')

    ELSE '/notifications'
  END;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."compute_notification_nav_url"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_invitee_for_match"("p_match_id" "uuid", "p_invitee_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_match record;
  v_is_player boolean := false;
  v_is_admin boolean := false;
  v_invitation_status text;
  v_new_player_ids uuid[];
  v_will_be_full boolean;
  v_day_time text;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  SELECT * INTO v_match FROM matches WHERE id = p_match_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Match not found'; END IF;

  v_is_player := v_user_id = ANY(COALESCE(v_match.player_ids, ARRAY[]::uuid[]));
  IF NOT v_is_player AND v_match.group_id IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1 FROM group_members
      WHERE group_id = v_match.group_id AND user_id = v_user_id AND role = 'admin'
    ) INTO v_is_admin;
  END IF;
  IF NOT v_is_player AND NOT v_is_admin THEN
    RAISE EXCEPTION 'Only match players or group admins can confirm invitees';
  END IF;

  SELECT status INTO v_invitation_status FROM match_invitations
  WHERE match_id = p_match_id AND invitee_id = p_invitee_id;
  IF v_invitation_status IS NULL THEN RAISE EXCEPTION 'No invitation found'; END IF;
  IF v_invitation_status <> 'accepted' THEN RAISE EXCEPTION 'Invitee has not accepted'; END IF;
  IF array_length(v_match.player_ids, 1) >= 4 THEN RAISE EXCEPTION 'Match is full'; END IF;

  v_new_player_ids := COALESCE(v_match.player_ids, ARRAY[]::uuid[]) || p_invitee_id;
  v_will_be_full := array_length(v_new_player_ids, 1) >= 4;

  UPDATE matches
  SET player_ids = v_new_player_ids,
      is_open = CASE WHEN v_will_be_full THEN false ELSE is_open END,
      open_elo_min = CASE WHEN v_will_be_full THEN NULL ELSE open_elo_min END,
      open_elo_max = CASE WHEN v_will_be_full THEN NULL ELSE open_elo_max END,
      status = CASE WHEN v_will_be_full THEN 'scheduled' ELSE status END,
      updated_at = now()
  WHERE id = p_match_id;

  IF v_will_be_full THEN
    UPDATE ringer_requests SET status = 'filled_by_other', responded_at = now()
      WHERE match_id = p_match_id AND status = 'pending';
    UPDATE match_invitations SET status = 'filled_by_other', responded_at = now()
      WHERE match_id = p_match_id AND status = 'pending' AND invitee_id <> p_invitee_id;
  END IF;

  -- Notify the invitee they're confirmed
  INSERT INTO notifications (user_id, type, title, message, related_id)
  VALUES (p_invitee_id, 'invitee_confirmed', 'You''re in!',
    'You''ve been confirmed for the match.', p_match_id);

  -- ── Lineup-changed notification to existing players (exclude the invitee) ──
  v_day_time := TO_CHAR(v_match.match_date, 'Dy DD Mon');
  IF v_match.match_time IS NOT NULL THEN
    v_day_time := v_day_time || ' · ' || LEFT(v_match.match_time::text, 5);
  END IF;

  IF array_length(v_match.player_ids, 1) > 0 THEN
    INSERT INTO notifications (user_id, type, title, message, related_id, read)
    SELECT
      unnest(v_match.player_ids),
      'match_lineup_changed',
      'Lineup changed',
      'Your ' || v_day_time || ' match lineup changed — tap to see.',
      p_match_id,
      false;
  END IF;

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."confirm_invitee_for_match"("p_match_id" "uuid", "p_invitee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_match_result"("p_match_result_id" "uuid", "p_voter_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_status          text;
  v_submitted_by    uuid;
  v_team1           uuid[];
  v_team2           uuid[];
  v_submitting_team uuid[];
  v_opposing_team   uuid[];
BEGIN
  SELECT verification_status, submitted_by, team1_players, team2_players
    INTO v_status, v_submitted_by, v_team1, v_team2
    FROM match_results
   WHERE id = p_match_result_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Match result not found';
  END IF;

  IF v_status = 'verified' THEN
    RETURN;
  END IF;

  IF v_status <> 'pending' THEN
    RAISE EXCEPTION 'Result is %, not pending', v_status;
  END IF;

  IF v_submitted_by = ANY(v_team1) THEN
    v_submitting_team := v_team1;
    v_opposing_team   := v_team2;
  ELSE
    v_submitting_team := v_team2;
    v_opposing_team   := v_team1;
  END IF;

  IF NOT (p_voter_id = ANY(v_opposing_team)) THEN
    RAISE EXCEPTION 'Only an opposing-team member can confirm this result';
  END IF;

  UPDATE match_results
     SET verification_status = 'verified',
         verified_at         = NOW()
   WHERE id = p_match_result_id;
END;
$$;


ALTER FUNCTION "public"."confirm_match_result"("p_match_result_id" "uuid", "p_voter_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_poll_schedule"("p_poll_id" "uuid", "p_schedule" "jsonb", "p_benched_ids" "uuid"[] DEFAULT '{}'::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_poll            record;
  v_match           jsonb;
  v_match_id        uuid;
  v_player_ids      uuid[];
  v_match_date      date;
  v_match_time      time;
  v_slot_id         text;
  v_team1           uuid[];
  v_team2           uuid[];
  v_window_start    time;
  v_window_end      time;
  v_conflicts       record;
  v_created_ids     uuid[] := '{}';
  v_scheduled_ids   uuid[];
  v_scheduled_ct    int := 0;
  v_benched_ct      int := 0;
  v_bad_id          uuid;
  v_overlap         uuid[];
BEGIN
  SELECT * INTO v_poll FROM polls WHERE id = p_poll_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Poll % not found', p_poll_id;
  END IF;
  IF v_poll.status = 'processed' THEN
    RAISE EXCEPTION 'Poll % is already processed', p_poll_id;
  END IF;

  FOR v_match IN SELECT * FROM jsonb_array_elements(p_schedule)
  LOOP
    v_player_ids := ARRAY(
      SELECT (j.value)::uuid
      FROM jsonb_array_elements_text(v_match->'player_ids') AS j(value)
    );
    v_match_date := (v_match->>'match_date')::date;
    v_match_time := (v_match->>'match_time')::time;
    v_slot_id    := v_match->>'slot_id';

    -- Team columns: nullable
    v_team1 := NULL;
    v_team2 := NULL;
    IF v_match->'team1_player_ids' IS NOT NULL AND jsonb_typeof(v_match->'team1_player_ids') = 'array' THEN
      v_team1 := ARRAY(SELECT (j.value)::uuid FROM jsonb_array_elements_text(v_match->'team1_player_ids') AS j(value));
    END IF;
    IF v_match->'team2_player_ids' IS NOT NULL AND jsonb_typeof(v_match->'team2_player_ids') = 'array' THEN
      v_team2 := ARRAY(SELECT (j.value)::uuid FROM jsonb_array_elements_text(v_match->'team2_player_ids') AS j(value));
    END IF;

    -- Window columns: nullable (range polls only)
    v_window_start := NULL;
    v_window_end   := NULL;
    IF v_match->>'window_start' IS NOT NULL THEN
      v_window_start := (v_match->>'window_start')::time;
    END IF;
    IF v_match->>'window_end' IS NOT NULL THEN
      v_window_end := (v_match->>'window_end')::time;
    END IF;

    FOR v_conflicts IN
      SELECT * FROM get_household_conflicts(v_player_ids, v_match_date, v_match_time)
      LIMIT 1
    LOOP
      RAISE EXCEPTION 'Household conflict detected for match on % at %: % conflicts with %',
        v_match_date, v_match_time,
        v_conflicts.user_id, v_conflicts.conflicting_household_member;
    END LOOP;

    INSERT INTO matches (
      poll_id, group_id, match_date, match_time, player_ids,
      team1_player_ids, team2_player_ids,
      window_start, window_end,
      poll_slot_id, status, match_type, context_type,
      created_manually, additional_options
    ) VALUES (
      p_poll_id, v_poll.group_id, v_match_date, v_match_time, v_player_ids,
      v_team1, v_team2,
      v_window_start, v_window_end,
      v_slot_id, COALESCE(v_match->>'status', 'scheduled'), 'competitive', 'poll',
      false, COALESCE(v_match->'additional_options', '{}'::jsonb)
    )
    RETURNING id INTO v_match_id;

    v_created_ids := v_created_ids || v_match_id;

    -- Auto-create match_drivers for players who answered "I can drive".
    -- offering_lifts = true only if they ALSO answered "I can offer a lift".
    -- Atomic with match creation. ON CONFLICT DO NOTHING for idempotency.
    INSERT INTO match_drivers (match_id, driver_id, seats_available, offering_lifts)
    SELECT v_match_id, pr.user_id, 3,
           COALESCE((pr.additional_responses->>'I can offer a lift')::boolean, false)
    FROM poll_responses pr
    WHERE pr.poll_id = p_poll_id
      AND pr.user_id = ANY(v_player_ids)
      AND pr.additional_responses->>'I can drive' = 'true'
    ON CONFLICT (match_id, driver_id) DO NOTHING;

  END LOOP;

  SELECT ARRAY(
    SELECT DISTINCT unnest(m.player_ids)
    FROM matches m
    WHERE m.id = ANY(v_created_ids)
  ) INTO v_scheduled_ids;

  SELECT bid INTO v_bad_id
  FROM unnest(p_benched_ids) AS bid
  WHERE NOT EXISTS (
    SELECT 1 FROM poll_responses pr
    WHERE pr.poll_id = p_poll_id AND pr.user_id = bid
  )
  LIMIT 1;

  IF v_bad_id IS NOT NULL THEN
    RAISE EXCEPTION 'Benched id % did not respond to poll %', v_bad_id, p_poll_id;
  END IF;

  SELECT ARRAY(
    SELECT unnest(v_scheduled_ids) INTERSECT SELECT unnest(p_benched_ids)
  ) INTO v_overlap;

  IF array_length(v_overlap, 1) > 0 THEN
    RAISE EXCEPTION 'Player(s) % appear in BOTH scheduled and benched', v_overlap;
  END IF;

  INSERT INTO poll_player_outcomes (poll_id, group_id, user_id, outcome, match_id)
  SELECT DISTINCT ON (unnested.pid)
    p_poll_id, v_poll.group_id, unnested.pid, 'scheduled', m.id
  FROM matches m,
       LATERAL unnest(m.player_ids) AS unnested(pid)
  WHERE m.id = ANY(v_created_ids)
  ORDER BY unnested.pid, m.match_date, m.match_time;

  GET DIAGNOSTICS v_scheduled_ct = ROW_COUNT;

  INSERT INTO poll_player_outcomes (poll_id, group_id, user_id, outcome)
  SELECT p_poll_id, v_poll.group_id, bid, 'benched'
  FROM unnest(p_benched_ids) AS bid;

  GET DIAGNOSTICS v_benched_ct = ROW_COUNT;

  UPDATE polls SET status = 'processed' WHERE id = p_poll_id;

  RETURN jsonb_build_object(
    'matches_created', array_length(v_created_ids, 1),
    'match_ids',       to_jsonb(v_created_ids),
    'scheduled_count', v_scheduled_ct,
    'benched_count',   v_benched_ct
  );
END;
$$;


ALTER FUNCTION "public"."confirm_poll_schedule"("p_poll_id" "uuid", "p_schedule" "jsonb", "p_benched_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_ringer_for_match"("p_match_id" "uuid", "p_ringer_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_match record;
  v_is_admin boolean := false;
  v_is_player boolean := false;
  v_request_status text;
  v_new_player_ids uuid[];
  v_day_time text;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT * INTO v_match FROM matches WHERE id = p_match_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Match not found';
  END IF;

  v_is_player := v_user_id = ANY(COALESCE(v_match.player_ids, ARRAY[]::uuid[]));

  IF NOT v_is_player AND v_match.group_id IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1 FROM group_members
      WHERE group_id = v_match.group_id
        AND user_id = v_user_id
        AND role = 'admin'
    ) INTO v_is_admin;
  END IF;

  IF NOT v_is_player AND NOT v_is_admin THEN
    RAISE EXCEPTION 'Only match players or group admins can confirm ringers';
  END IF;

  SELECT status INTO v_request_status
  FROM ringer_requests
  WHERE match_id = p_match_id AND ringer_id = p_ringer_id;

  IF v_request_status IS NULL THEN
    RAISE EXCEPTION 'No request found for this ringer';
  END IF;
  IF v_request_status <> 'accepted' THEN
    RAISE EXCEPTION 'Ringer has not accepted';
  END IF;

  IF array_length(v_match.player_ids, 1) >= 4 THEN
    RAISE EXCEPTION 'Match is already full';
  END IF;

  v_new_player_ids := COALESCE(v_match.player_ids, ARRAY[]::uuid[]) || p_ringer_id;

  UPDATE matches
  SET player_ids = v_new_player_ids,
      status = CASE WHEN array_length(v_new_player_ids, 1) >= 4 THEN 'scheduled' ELSE status END,
      updated_at = now()
  WHERE id = p_match_id;

  UPDATE ringer_requests
  SET status = 'filled_by_other', responded_at = now()
  WHERE match_id = p_match_id
    AND ringer_id <> p_ringer_id
    AND status = 'pending';

  -- Notify the ringer they're confirmed
  INSERT INTO notifications (user_id, type, title, message, related_id)
  VALUES (
    p_ringer_id,
    'ringer_confirmed',
    'You''re in!',
    'You''ve been confirmed for the match. Check details.',
    p_match_id
  );

  -- ── Lineup-changed notification to existing players (exclude the ringer) ──
  v_day_time := TO_CHAR(v_match.match_date, 'Dy DD Mon');
  IF v_match.match_time IS NOT NULL THEN
    v_day_time := v_day_time || ' · ' || LEFT(v_match.match_time::text, 5);
  END IF;

  IF array_length(v_match.player_ids, 1) > 0 THEN
    INSERT INTO notifications (user_id, type, title, message, related_id, read)
    SELECT
      unnest(v_match.player_ids),
      'match_lineup_changed',
      'Lineup changed',
      'Your ' || v_day_time || ' match lineup changed — tap to see.',
      p_match_id,
      false;
  END IF;

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."confirm_ringer_for_match"("p_match_id" "uuid", "p_ringer_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."count_open_match_audience"("p_lat" double precision, "p_lng" double precision, "p_elo_min" integer, "p_elo_max" integer, "p_exclude_player_ids" "uuid"[], "p_radius_miles" double precision DEFAULT 10) RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$                                                                         
    SELECT COUNT(*)::integer
    FROM profiles p                                                             
    WHERE p.internal_ranking BETWEEN p_elo_min AND p_elo_max
      AND p.latitude IS NOT NULL
      AND p.longitude IS NOT NULL                                               
      AND NOT (p.id = ANY(p_exclude_player_ids))
      AND haversine_miles(p_lat, p_lng, p.latitude, p.longitude) <=             
  p_radius_miles;                                                               
  $$;


ALTER FUNCTION "public"."count_open_match_audience"("p_lat" double precision, "p_lng" double precision, "p_elo_min" integer, "p_elo_max" integer, "p_exclude_player_ids" "uuid"[], "p_radius_miles" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."court_utilisation"("p_venue_id" "uuid", "p_from" "date", "p_to" "date") RETURNS TABLE("court_id" "uuid", "court_name" "text", "dow" integer, "hour" integer, "booked_minutes" integer, "avail_minutes" integer, "occupancy_pct" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH
  venue_courts AS (
    SELECT
      c.id AS court_id,
      c.court_name,
      COALESCE(
        CASE WHEN c.is_indoor THEN cas.indoor_open_time ELSE cas.outdoor_open_time END,
        cas.open_time, '07:00'::time
      ) AS open_t,
      COALESCE(
        CASE WHEN c.is_indoor THEN cas.indoor_close_time ELSE cas.outdoor_close_time END,
        cas.close_time, '23:00'::time
      ) AS close_t
    FROM public.courts c
    LEFT JOIN public.court_availability_settings cas ON cas.venue_id = c.venue_id
    WHERE c.venue_id = p_venue_id
      AND c.status = 'active'
  ),
  time_grid AS (
    SELECT vc.court_id, vc.court_name, d.dow, h.hour
    FROM venue_courts vc
    CROSS JOIN generate_series(0, 6) AS d(dow)
    CROSS JOIN LATERAL generate_series(
      EXTRACT(HOUR FROM vc.open_t)::int,
      (CASE WHEN vc.close_t = time '00:00' THEN 24 ELSE EXTRACT(HOUR FROM vc.close_t)::int END) - 1
    ) AS h(hour)
  ),
  dow_counts AS (
    SELECT EXTRACT(DOW FROM d)::int AS dow, COUNT(*)::int AS cnt
    FROM generate_series(p_from, p_to, '1 day'::interval) AS d
    GROUP BY 1
  ),
  avail AS (
    SELECT tg.court_id, tg.court_name, tg.dow, tg.hour,
           COALESCE(dc.cnt, 0) * 60 AS avail_minutes
    FROM time_grid tg
    LEFT JOIN dow_counts dc ON dc.dow = tg.dow
  ),
  booked AS (
    SELECT
      b.court_id,
      EXTRACT(DOW FROM b.start_at)::int AS dow,
      h.hour,
      SUM(
        GREATEST(0,
          EXTRACT(EPOCH FROM (
            LEAST(b.end_at, date_trunc('hour', b.start_at) + ((h.hour - EXTRACT(HOUR FROM b.start_at)::int + 1) || ' hours')::interval)
            - GREATEST(b.start_at, date_trunc('hour', b.start_at) + ((h.hour - EXTRACT(HOUR FROM b.start_at)::int) || ' hours')::interval)
          )) / 60
        )
      )::int AS booked_minutes
    FROM public.bookings b
    CROSS JOIN LATERAL generate_series(
      EXTRACT(HOUR FROM b.start_at)::int,
      EXTRACT(HOUR FROM b.end_at - interval '1 second')::int
    ) AS h(hour)
    WHERE b.venue_id = p_venue_id
      AND b.start_at::date >= p_from
      AND b.start_at::date <= p_to
      AND b.reservation_state = 'active'
      AND b.purpose IS DISTINCT FROM 'blocked'
    GROUP BY b.court_id, EXTRACT(DOW FROM b.start_at)::int, h.hour
  )
  SELECT
    a.court_id,
    a.court_name,
    a.dow,
    a.hour,
    COALESCE(bk.booked_minutes, 0)::int,
    a.avail_minutes::int,
    CASE WHEN a.avail_minutes > 0
      THEN ROUND(COALESCE(bk.booked_minutes, 0)::numeric / a.avail_minutes * 100, 1)
      ELSE 0
    END
  FROM avail a
  LEFT JOIN booked bk
    ON bk.court_id = a.court_id
    AND bk.dow     = a.dow
    AND bk.hour    = a.hour
  ORDER BY a.court_name, a.dow, a.hour;
END;
$$;


