CREATE OR REPLACE FUNCTION "public"."create_match_chat_channel"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.status = 'scheduled' AND
     (OLD IS NULL OR OLD.status IS DISTINCT FROM 'scheduled') THEN

    -- Only create a group-scoped chat channel when the match has a group
    IF NEW.group_id IS NOT NULL THEN
      INSERT INTO chat_channels (
        type, group_id, match_id, name, participants
      )
      VALUES (
        'match',
        NEW.group_id,
        NEW.id,
        'Match: ' || to_char(NEW.match_date, 'Mon DD')
          || ' at ' || to_char(NEW.match_time, 'HH24:MI'),
        NEW.player_ids
      )
      ON CONFLICT DO NOTHING;
    END IF;

  END IF;
  RETURN NEW;
END;
$$;


