CREATE OR REPLACE FUNCTION "public"."create_match_guest_invite"("p_match_id" "uuid", "p_guest_name" "text", "p_contact" "text" DEFAULT NULL::"text", "p_replace_player_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_token text := replace(gen_random_uuid()::text, '-', '');
  v_slot  uuid := gen_random_uuid();
  v_pids  uuid[];
  v_id    uuid;
BEGIN
  IF coalesce(btrim(p_guest_name), '') = '' THEN
    RAISE EXCEPTION 'Guest name is required';
  END IF;

  -- participant, creator, or group admin may invite (mirrors delete_match_cascade)
  IF NOT EXISTS (
    SELECT 1 FROM public.matches m
    LEFT JOIN public.groups g ON g.id = m.group_id
    LEFT JOIN public.group_members gm ON gm.group_id = g.id
      AND gm.user_id = auth.uid() AND gm.role = 'admin' AND gm.status = 'approved'
    WHERE m.id = p_match_id
      AND (auth.uid() = ANY(m.player_ids)
           OR m.created_by = auth.uid()
           OR g.admin_id = auth.uid()
           OR gm.user_id IS NOT NULL)
  ) THEN
    RAISE EXCEPTION 'Not authorized to invite to this match';
  END IF;

  SELECT coalesce(player_ids, '{}'::uuid[]) INTO v_pids FROM public.matches WHERE id = p_match_id FOR UPDATE;

  IF p_replace_player_id IS NOT NULL AND p_replace_player_id = ANY(v_pids) THEN
    v_pids := array_replace(v_pids, p_replace_player_id, v_slot);
    UPDATE public.match_guest_invites SET status = 'cancelled'
      WHERE slot_player_id = p_replace_player_id AND status = 'pending';
  ELSE
    v_pids := v_pids || v_slot;
  END IF;

  INSERT INTO public.match_guest_invites (match_id, guest_name, contact, invite_token, slot_player_id, invited_by)
  VALUES (p_match_id, btrim(p_guest_name), nullif(btrim(coalesce(p_contact,'')), ''), v_token, v_slot, auth.uid())
  RETURNING id INTO v_id;

  UPDATE public.matches
    SET player_ids = v_pids,
        status = CASE WHEN coalesce(array_length(v_pids, 1), 0) >= 4 THEN 'scheduled' ELSE status END
    WHERE id = p_match_id;

  RETURN jsonb_build_object('invite_id', v_id, 'token', v_token, 'slot', v_slot::text);
END; $$;


ALTER FUNCTION "public"."create_match_guest_invite"("p_match_id" "uuid", "p_guest_name" "text", "p_contact" "text", "p_replace_player_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_owned_venue"("p" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_venues_id uuid;
  v_pv_id uuid;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  if coalesce(nullif(btrim(p->>'venue_name'), ''), '') = '' then raise exception 'venue_name_required'; end if;

  -- Predict the UNIQUE (venue_name, city) collision and fail cleanly so the
  -- client can steer the owner to CLAIM the existing venue instead.
  if exists (
    select 1 from public.padel_venues
    where venue_name = btrim(p->>'venue_name')
      and city = coalesce(nullif(btrim(p->>'city'), ''), '')
  ) then
    raise exception 'venue_exists';
  end if;

  insert into public.venues (name, country, city, address, latitude, longitude, has_app_booking, booking_type)
  values (
    btrim(p->>'venue_name'),
    coalesce(nullif(btrim(p->>'country'), ''), 'Unknown'),
    nullif(btrim(p->>'city'), ''),
    nullif(btrim(p->>'full_address'), ''),
    nullif(p->>'latitude', '')::numeric,
    nullif(p->>'longitude', '')::numeric,
    true,
    'link'
  )
  returning id into v_venues_id;

  insert into public.padel_venues (
    venues_id, venue_name, email, full_address, city, postcode, country, country_code,
    latitude, longitude, booking_url, website, status, verified, ppa_bookable, currency,
    number_of_courts, booking_advance_nonmember_days, booking_advance_member_days
  ) values (
    v_venues_id,
    btrim(p->>'venue_name'),
    nullif(btrim(p->>'email'), ''),
    coalesce(nullif(btrim(p->>'full_address'), ''), ''),
    coalesce(nullif(btrim(p->>'city'), ''), ''),
    nullif(btrim(p->>'postcode'), ''),
    coalesce(nullif(btrim(p->>'country'), ''), 'Unknown'),
    coalesce(nullif(btrim(p->>'country_code'), ''), 'XX'),
    nullif(p->>'latitude', '')::numeric,
    nullif(p->>'longitude', '')::numeric,
    coalesce(nullif(btrim(p->>'booking_url'), ''), ''),
    nullif(btrim(p->>'website'), ''),
    'active', false, false,
    coalesce(nullif(btrim(p->>'currency'), ''), 'GBP'),
    0, 14, 14
  )
  returning venue_id into v_pv_id;

  insert into public.venue_users (venue_id, user_id, role, status)
  values (v_venues_id, v_uid, 'owner', 'active');

  return jsonb_build_object('venues_id', v_venues_id, 'padel_venue_id', v_pv_id);
end $$;


ALTER FUNCTION "public"."create_owned_venue"("p" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_standard_contract"("p_venue_id" "uuid", "p_plan_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid         uuid := auth.uid();
  v_plan        public.standard_plans;
  v_cc          text;
  v_price       record;
  v_listed      public.country_plan_prices;
  v_currency    text;
  v_monthly     integer;
  v_contract_id uuid;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;

  if not exists (
    select 1 from public.venue_users vu
     where vu.venue_id = p_venue_id and vu.user_id = v_uid
       and vu.role = 'owner' and vu.status = 'active'
  ) then raise exception 'not_venue_owner'; end if;

  if exists (select 1 from public.venue_contracts
              where venue_id = p_venue_id and status = 'active')
  then raise exception 'active_contract_exists'; end if;

  select * into v_plan from public.standard_plans where key = p_plan_key;
  if not found then raise exception 'invalid_plan'; end if;

  select pv.country_code into v_cc
    from public.padel_venues pv
   where pv.venues_id = p_venue_id
   limit 1;

  select * into v_price from public.resolve_country_pricing(v_cc);
  select * into v_listed
    from public.country_plan_prices
   where country_code = v_cc and plan_key = p_plan_key;

  if v_plan.court_hour_multiple = 0 then
    v_monthly  := 0;
    v_currency := coalesce(v_listed.currency,
                           (select currency from public.country_plan_prices
                             where country_code = v_cc limit 1),
                           v_price.currency);
  else
    if v_listed.country_code is null then
      raise exception 'pricing_unavailable_in_country';
    end if;
    v_monthly  := v_listed.monthly_price_minor;
    v_currency := v_listed.currency;
  end if;

  insert into public.venue_contracts (
    venue_id, status,
    currency, plan_tier, commission_rate_bps,
    monthly_price_pence, monthly_credit_pence,
    auto_renew, notice_period_days, special_terms,
    start_date, signed_by, signed_at,
    pricing_country_code, pricing_band_key, reference_court_hour_minor, court_hour_multiple
  ) values (
    p_venue_id, 'active',
    v_currency, p_plan_key, v_plan.commission_rate_bps,
    v_monthly, 0,
    v_plan.auto_renew, v_plan.notice_period_days, v_plan.special_terms,
    current_date, v_uid, now(),
    v_cc, v_price.band_key, v_price.reference_court_hour_minor, v_plan.court_hour_multiple
  ) returning id into v_contract_id;

  update public.venues set
    commission_rate_bps = v_plan.commission_rate_bps,
    plan_tier           = p_plan_key,
    monthly_price_pence = v_monthly,
    currency            = v_currency
  where id = p_venue_id;

  return jsonb_build_object(
    'contract_id', v_contract_id,
    'plan', p_plan_key,
    'currency', v_currency,
    'monthly_price_minor', v_monthly,
    'pricing_country', v_cc
  );
end $$;


ALTER FUNCTION "public"."create_standard_contract"("p_venue_id" "uuid", "p_plan_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cron_health_heartbeat"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_total int; v_unhealthy int; v_names text;
BEGIN
  SELECT count(*), count(*) FILTER (WHERE status <> 'ok'),
         string_agg(jobname, ', ') FILTER (WHERE status <> 'ok')
    INTO v_total, v_unhealthy, v_names FROM cron_health_state;

  PERFORM public.notify_platform_admins(
    'cron_health',
    CASE WHEN v_unhealthy = 0 THEN 'Weekly check: all scheduled jobs healthy'
         ELSE 'Weekly check: ' || v_unhealthy || ' job(s) unhealthy' END,
    CASE WHEN v_unhealthy = 0 THEN v_total || ' jobs monitored, all green.'
         ELSE v_total || ' jobs monitored. Unhealthy: ' || v_names END);
END;
$$;


ALTER FUNCTION "public"."cron_health_heartbeat"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_match_cascade"("p_match_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM matches m
    LEFT JOIN groups g ON g.id = m.group_id
    LEFT JOIN group_members gm ON gm.group_id = g.id
      AND gm.user_id = auth.uid() AND gm.role = 'admin' AND gm.status = 'approved'
    WHERE m.id = p_match_id AND (g.admin_id = auth.uid() OR gm.user_id IS NOT NULL)
  ) THEN
    RAISE EXCEPTION 'Not authorized to delete this match';
  END IF;

  UPDATE profiles p
  SET internal_ranking = GREATEST(0, LEAST(3000, p.internal_ranking - agg.total_change)),
      matches_played   = GREATEST(0, p.matches_played - agg.cnt),
      is_provisional   = GREATEST(0, p.matches_played - agg.cnt) < 10
  FROM (
    SELECT rh.user_id, COALESCE(SUM(rh.rating_change),0)::int AS total_change, COUNT(*)::int AS cnt
    FROM rating_history rh
    JOIN match_results mr ON mr.id = rh.match_result_id
    WHERE mr.match_id = p_match_id
    GROUP BY rh.user_id
  ) agg
  WHERE p.id = agg.user_id;

  DELETE FROM rating_history WHERE match_result_id IN (SELECT id FROM match_results WHERE match_id = p_match_id);
  DELETE FROM ranking_changes WHERE match_id = p_match_id;
  DELETE FROM match_result_votes WHERE match_result_id IN (SELECT id FROM match_results WHERE match_id = p_match_id);
  DELETE FROM match_peer_votes WHERE match_id = p_match_id;
  DELETE FROM match_results WHERE match_id = p_match_id;
  DELETE FROM travel_requests WHERE match_id = p_match_id;
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name='match_comments') THEN
    EXECUTE 'DELETE FROM match_comments WHERE match_id = $1' USING p_match_id;
  END IF;
  DELETE FROM notifications WHERE related_id = p_match_id::text;
  DELETE FROM matches WHERE id = p_match_id;
END;
$_$;


ALTER FUNCTION "public"."delete_match_cascade"("p_match_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."delete_match_cascade"("p_match_id" "uuid") IS 'Cascade delete a match';



CREATE OR REPLACE FUNCTION "public"."delete_user"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_profile_exists boolean;
  v_group_id uuid;
  v_new_admin uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated — auth.uid() is NULL';
  END IF;

  SELECT EXISTS (SELECT 1 FROM profiles WHERE id = v_uid) INTO v_profile_exists;
  IF NOT v_profile_exists THEN
    DELETE FROM auth.users WHERE id = v_uid;
    RETURN jsonb_build_object('deleted', true, 'user_id', v_uid, 'note', 'profile_not_found');
  END IF;

  BEGIN DELETE FROM event_attendees WHERE user_id = v_uid; EXCEPTION WHEN undefined_table OR undefined_column THEN NULL; END;
  BEGIN DELETE FROM league_members WHERE user_id = v_uid; EXCEPTION WHEN undefined_table OR undefined_column THEN NULL; END;
  BEGIN DELETE FROM league_invitations WHERE invited_user_id = v_uid; EXCEPTION WHEN undefined_table OR undefined_column THEN NULL; END;
  BEGIN DELETE FROM match_result_votes WHERE voter_id = v_uid; EXCEPTION WHEN undefined_table OR undefined_column THEN NULL; END;
  BEGIN DELETE FROM league_teams WHERE player1_id = v_uid OR player2_id = v_uid; EXCEPTION WHEN undefined_table OR undefined_column THEN NULL; END;
  BEGIN DELETE FROM pairs_rankings WHERE player1_id = v_uid OR player2_id = v_uid; EXCEPTION WHEN undefined_table OR undefined_column THEN NULL; END;
  BEGIN DELETE FROM user_badges WHERE user_id = v_uid; EXCEPTION WHEN undefined_table OR undefined_column THEN NULL; END;
  BEGIN DELETE FROM ranking_changes WHERE player_id = v_uid; EXCEPTION WHEN undefined_table OR undefined_column THEN NULL; END;
  BEGIN DELETE FROM league_standings WHERE user_id = v_uid; EXCEPTION WHEN undefined_table OR undefined_column THEN NULL; END;
  BEGIN DELETE FROM group_members WHERE user_id = v_uid; EXCEPTION WHEN undefined_table OR undefined_column THEN NULL; END;
  BEGIN DELETE FROM notifications WHERE user_id = v_uid; EXCEPTION WHEN undefined_table OR undefined_column THEN NULL; END;
  BEGIN DELETE FROM poll_responses WHERE user_id = v_uid; EXCEPTION WHEN undefined_table OR undefined_column THEN NULL; END;

  BEGIN UPDATE court_block_outs SET created_by = NULL WHERE created_by = v_uid; EXCEPTION WHEN undefined_table OR undefined_column THEN NULL; END;
  BEGIN UPDATE bookings SET cancelled_by = NULL WHERE cancelled_by = v_uid; EXCEPTION WHEN undefined_table OR undefined_column THEN NULL; END;
  BEGIN UPDATE group_members SET banned_by = NULL WHERE banned_by = v_uid; EXCEPTION WHEN undefined_table OR undefined_column THEN NULL; END;
  BEGIN UPDATE league_adjustments SET created_by = NULL WHERE created_by = v_uid; EXCEPTION WHEN undefined_table OR undefined_column THEN NULL; END;
  BEGIN UPDATE league_invitations SET invited_by = NULL WHERE invited_by = v_uid; EXCEPTION WHEN undefined_table OR undefined_column THEN NULL; END;
  BEGIN UPDATE league_jerseys SET previous_holder = NULL WHERE previous_holder = v_uid; EXCEPTION WHEN undefined_table OR undefined_column THEN NULL; END;
  BEGIN UPDATE league_ranking_adjustments SET adjusted_by = NULL WHERE adjusted_by = v_uid; EXCEPTION WHEN undefined_table OR undefined_column THEN NULL; END;
  BEGIN UPDATE match_invitations SET invited_by = NULL WHERE invited_by = v_uid; EXCEPTION WHEN undefined_table OR undefined_column THEN NULL; END;
  BEGIN UPDATE match_results SET disputed_by = NULL WHERE disputed_by = v_uid; EXCEPTION WHEN undefined_table OR undefined_column THEN NULL; END;
  BEGIN UPDATE match_results SET verified_by = NULL WHERE verified_by = v_uid; EXCEPTION WHEN undefined_table OR undefined_column THEN NULL; END;
  BEGIN UPDATE match_results SET submitted_by = NULL WHERE submitted_by = v_uid; EXCEPTION WHEN undefined_table OR undefined_column THEN NULL; END;
  BEGIN UPDATE matches SET opened_by = NULL WHERE opened_by = v_uid; EXCEPTION WHEN undefined_table OR undefined_column THEN NULL; END;
  BEGIN UPDATE matches SET voided_by = NULL WHERE voided_by = v_uid; EXCEPTION WHEN undefined_table OR undefined_column THEN NULL; END;
  BEGIN UPDATE matches SET created_by = NULL WHERE created_by = v_uid; EXCEPTION WHEN undefined_table OR undefined_column THEN NULL; END;
  BEGIN UPDATE matches SET booked_by = NULL WHERE booked_by = v_uid; EXCEPTION WHEN undefined_table OR undefined_column THEN NULL; END;
  BEGIN UPDATE ringer_requests SET requested_by = NULL WHERE requested_by = v_uid; EXCEPTION WHEN undefined_table OR undefined_column THEN NULL; END;

  BEGIN UPDATE profiles SET worst_partner_id = NULL WHERE worst_partner_id = v_uid; EXCEPTION WHEN undefined_column THEN NULL; END;
  BEGIN UPDATE profiles SET household_partner_id = NULL WHERE household_partner_id = v_uid; EXCEPTION WHEN undefined_column THEN NULL; END;
  BEGIN UPDATE profiles SET best_partner_id = NULL WHERE best_partner_id = v_uid; EXCEPTION WHEN undefined_column THEN NULL; END;

  BEGIN UPDATE matches SET player_ids = array_remove(player_ids, v_uid) WHERE v_uid = ANY(player_ids); EXCEPTION WHEN undefined_column THEN NULL; END;
  BEGIN UPDATE matches SET confirmed_players = array_remove(confirmed_players, v_uid) WHERE v_uid = ANY(confirmed_players); EXCEPTION WHEN undefined_column THEN NULL; END;

  BEGIN
    UPDATE bookings SET booked_by = NULL WHERE booked_by = v_uid;
    UPDATE bookings SET player_ids = array_remove(player_ids, v_uid) WHERE v_uid = ANY(player_ids);
  EXCEPTION WHEN undefined_table OR undefined_column THEN NULL;
  END;

  BEGIN
    FOR v_group_id IN SELECT id FROM groups WHERE admin_id = v_uid LOOP
      SELECT user_id INTO v_new_admin
      FROM group_members
      WHERE group_id = v_group_id AND user_id != v_uid AND status = 'approved'
      ORDER BY created_at ASC LIMIT 1;
      IF v_new_admin IS NOT NULL THEN
        UPDATE group_members SET role = 'admin'::group_role WHERE group_id = v_group_id AND user_id = v_new_admin;
        UPDATE groups SET admin_id = v_new_admin WHERE id = v_group_id;
      ELSE
        DELETE FROM groups WHERE id = v_group_id;
      END IF;
    END LOOP;
  EXCEPTION WHEN undefined_table THEN NULL; WHEN undefined_column THEN NULL;
  END;

  BEGIN UPDATE leagues SET created_by = NULL WHERE created_by = v_uid; EXCEPTION WHEN undefined_column THEN NULL; END;
  BEGIN UPDATE events SET created_by = NULL WHERE created_by = v_uid; EXCEPTION WHEN undefined_column THEN NULL; END;
  BEGIN UPDATE polls SET created_by = NULL WHERE created_by = v_uid; EXCEPTION WHEN undefined_column THEN NULL; END;

  DELETE FROM profiles WHERE id = v_uid;
  DELETE FROM auth.users WHERE id = v_uid;

  RETURN jsonb_build_object('deleted', true, 'user_id', v_uid);
END;
$$;


ALTER FUNCTION "public"."delete_user"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."delete_user"() IS 'Permanently deletes the calling user''s account and all associated data. Required for Apple App Store Guideline 5.1.1(v).';



CREATE OR REPLACE FUNCTION "public"."discover_counts"("p_lat" double precision DEFAULT NULL::double precision, "p_lng" double precision DEFAULT NULL::double precision, "p_radius_miles" double precision DEFAULT 25) RETURNS TABLE("venues" integer, "players" integer, "coaching" integer, "groups" integer, "leagues" integer, "events" integer, "open_games" integer, "radius_miles" double precision, "lat" double precision, "lng" double precision)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  with me as (
    select
      coalesce(p_lat, pr.latitude::double precision)  as lat,
      coalesce(p_lng, pr.longitude::double precision) as lng,
      greatest(0, least(coalesce(p_radius_miles, 25), 500)) as r
    from (select 1) one
    left join public.profiles pr on pr.id = auth.uid()
  )
  select
    (select count(*)::integer from public.discover_list('venues',   p_lat, p_lng, p_radius_miles, null, 0)),
    (select count(*)::integer from public.discover_list('players',  p_lat, p_lng, p_radius_miles, null, 0)),
    (select count(*)::integer from public.discover_list('coaching', p_lat, p_lng, p_radius_miles, null, 0)),
    (select count(*)::integer from public.discover_list('groups',   p_lat, p_lng, p_radius_miles, null, 0)),
    (select count(*)::integer from public.discover_list('leagues',  p_lat, p_lng, p_radius_miles, null, 0)),
    (select count(*)::integer from public.discover_list('events',   p_lat, p_lng, p_radius_miles, null, 0)),
    -- open_games has no tile and no page; it drives the hero's empty state only.
    (select count(*)::integer
       from public.matches m
       join public.padel_venues pv on pv.venue_id = m.padel_venue_id, me
      where m.is_open = true
        and m.status not in ('cancelled','completed')
        and m.match_date is not null
        and (m.match_date + coalesce(m.match_time, m.window_start, time '00:00')) >= now() at time zone 'UTC'
        and me.lat is not null
        and public.haversine_miles(me.lat, me.lng, pv.latitude, pv.longitude) <= me.r),
    (select r from me), (select lat from me), (select lng from me)
$$;


ALTER FUNCTION "public"."discover_counts"("p_lat" double precision, "p_lng" double precision, "p_radius_miles" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."discover_feed"("p_lat" double precision DEFAULT NULL::double precision, "p_lng" double precision DEFAULT NULL::double precision, "p_radius_miles" double precision DEFAULT 25, "p_days" integer DEFAULT 28, "p_limit" integer DEFAULT 50) RETURNS TABLE("kind" "text", "id" "uuid", "title" "text", "subtitle" "text", "starts_at" timestamp with time zone, "venue_id" "uuid", "venue_name" "text", "latitude" double precision, "longitude" double precision, "distance_miles" double precision, "price_pence" integer, "currency" "text", "spots_left" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
WITH me AS (
  SELECT
    COALESCE(p_lat, pr.latitude::double precision)  AS lat,
    COALESCE(p_lng, pr.longitude::double precision) AS lng
  FROM (SELECT 1) one
  LEFT JOIN public.profiles pr ON pr.id = auth.uid()
),
horizon AS (
  SELECT now() AS from_ts,
         now() + make_interval(days => greatest(1, least(coalesce(p_days, 28), 365))) AS to_ts
),
items AS (
  SELECT
    'open_match'::text AS kind,
    m.id,
    COALESCE(m.booked_venue_name, 'Open match') AS title,
    CASE WHEN m.open_elo_min IS NOT NULL OR m.open_elo_max IS NOT NULL
         THEN 'Level ' || COALESCE(m.open_elo_min::text, 'any') || '-' || COALESCE(m.open_elo_max::text, 'any')
         ELSE 'Open to anyone' END AS subtitle,
    ((m.match_date + COALESCE(m.match_time, m.window_start, time '00:00')) AT TIME ZONE 'UTC') AS starts_at,
    m.padel_venue_id AS venue_id,
    m.booked_venue_name AS venue_name,
    pv.latitude::double precision,
    pv.longitude::double precision,
    NULL::integer AS price_pence,
    NULL::text    AS currency,
    GREATEST(0, 4 - COALESCE(array_length(m.player_ids, 1), 0)) AS spots_left
  FROM public.matches m
  LEFT JOIN public.padel_venues pv ON pv.venue_id = m.padel_venue_id
  WHERE m.is_open = true
    AND m.status NOT IN ('cancelled', 'completed')
    AND m.match_date IS NOT NULL

  UNION ALL

  SELECT
    'event',
    e.id,
    e.title,
    COALESCE(e.event_type, 'Event'),
    e.start_time,
    e.padel_venue_id,
    COALESCE(pv.venue_name, e.location),
    COALESCE(e.latitude, pv.latitude)::double precision,
    COALESCE(e.longitude, pv.longitude)::double precision,
    NULLIF(e.entry_fee_pence, 0),
    e.currency,
    CASE WHEN e.max_capacity IS NULL THEN NULL
         ELSE GREATEST(0, e.max_capacity
              - (SELECT count(*)::integer FROM public.event_attendees a WHERE a.event_id = e.id)) END
  FROM public.events e
  LEFT JOIN public.padel_venues pv ON pv.venue_id = e.padel_venue_id
  WHERE e.visibility IN ('public', 'connections')
    AND e.status = 'published'

  UNION ALL

  SELECT
    'venue_event',
    occ.id,
    ve.name,
    COALESCE(ve.type, 'Session'),
    occ.starts_at,
    pv.venue_id,
    v.name,
    v.latitude::double precision,
    v.longitude::double precision,
    ve.price_per_player,
    NULL::text,
    CASE WHEN ve.capacity IS NULL THEN NULL
         ELSE GREATEST(0, ve.capacity - COALESCE(occ.spots_taken, 0)) END
  FROM public.venue_event_occurrences occ
  JOIN public.venue_events ve ON ve.id = occ.event_id
  JOIN public.venues v        ON v.id = ve.venue_id
  LEFT JOIN public.padel_venues pv ON pv.venues_id = v.id
  WHERE COALESCE(occ.status, 'scheduled') <> 'cancelled'

  UNION ALL

  SELECT
    'league',
    l.id,
    l.name,
    COALESCE(l.format, l.match_type, 'League'),
    COALESCE(l.season_start::timestamptz, l.tournament_start::timestamptz),
    l.padel_venue_id,
    COALESCE(pv.venue_name, l.city),
    COALESCE(l.latitude, pv.latitude)::double precision,
    COALESCE(l.longitude, pv.longitude)::double precision,
    NULLIF(l.entry_fee_pence, 0),
    l.currency,
    CASE WHEN l.max_participants IS NULL THEN NULL
         ELSE GREATEST(0, l.max_participants
              - (SELECT count(*)::integer FROM public.league_members lm WHERE lm.league_id = l.id)) END
  FROM public.leagues l
  LEFT JOIN public.padel_venues pv ON pv.venue_id = l.padel_venue_id
  WHERE l.visibility = 'open'
    AND COALESCE(l.is_open_registration, false) = true
    AND l.status IN ('active', 'upcoming', 'open')

  UNION ALL

  SELECT
    'coaching',
    cs.id,
    COALESCE(cs.title, 'Coaching'),
    COALESCE(cs.session_type, 'Session'),
    cs.start_at,
    pv.venue_id,
    v.name,
    v.latitude::double precision,
    v.longitude::double precision,
    cs.price_pence,
    cs.currency,
    cs.capacity
  FROM public.coaching_sessions cs
  JOIN public.venues v ON v.id = cs.venue_id
  LEFT JOIN public.padel_venues pv ON pv.venues_id = v.id
  WHERE COALESCE(cs.status, 'scheduled') NOT IN ('cancelled', 'completed')
),
measured AS (
  SELECT i.*,
         CASE WHEN me.lat IS NULL OR i.latitude IS NULL THEN NULL
              ELSE public.haversine_miles(me.lat, me.lng, i.latitude, i.longitude) END AS distance_miles
  FROM items i CROSS JOIN me
)
SELECT
  x.kind, x.id, x.title, x.subtitle, x.starts_at,
  x.venue_id, x.venue_name, x.latitude, x.longitude, x.distance_miles,
  x.price_pence, x.currency, x.spots_left
FROM measured x, horizon h
WHERE x.starts_at >= h.from_ts
  AND x.starts_at <  h.to_ts
  AND (x.distance_miles IS NULL OR x.distance_miles <= greatest(p_radius_miles, 0))
ORDER BY (x.starts_at AT TIME ZONE 'UTC')::date,
         x.distance_miles ASC NULLS LAST,
         x.starts_at
LIMIT greatest(1, least(coalesce(p_limit, 50), 200));
$$;


ALTER FUNCTION "public"."discover_feed"("p_lat" double precision, "p_lng" double precision, "p_radius_miles" double precision, "p_days" integer, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."discover_list"("p_kind" "text", "p_lat" double precision DEFAULT NULL::double precision, "p_lng" double precision DEFAULT NULL::double precision, "p_radius_miles" double precision DEFAULT 25, "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "title" "text", "subtitle" "text", "distance_miles" double precision, "meta" "jsonb")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  with me as (
    select
      coalesce(p_lat, pr.latitude::double precision)  as lat,
      coalesce(p_lng, pr.longitude::double precision) as lng,
      greatest(0, least(coalesce(p_radius_miles, 25), 500)) as r,
      auth.uid() as uid
    from (select 1) one
    left join public.profiles pr on pr.id = auth.uid()
  ),
  rows as (
    select pv.venue_id as id, pv.venue_name as title, nullif(pv.city,'') as subtitle,
           public.haversine_miles(me.lat, me.lng, pv.latitude, pv.longitude) as distance_miles,
           jsonb_build_object(
             'courts', nullif(greatest(coalesce(pv.number_of_courts,0),
                        coalesce(pv.indoor_courts,0)+coalesce(pv.outdoor_courts,0)+coalesce(pv.covered_courts,0)), 0),
             'booking_url', nullif(pv.booking_url,''),
             'booking_platform', nullif(pv.booking_platform,''),
             'ppa_bookable', pv.ppa_bookable,
             'coaching', coalesce(pv.coaching_available,false)
           ) as meta
      from public.padel_venues pv, me
     where p_kind = 'venues'
       and pv.status = 'active' and pv.merged_into is null
       and pv.venue_type = 'club'
       and pv.latitude is not null and me.lat is not null
       and public.haversine_miles(me.lat, me.lng, pv.latitude, pv.longitude) <= me.r

    union all
    select pv.venue_id, pv.venue_name, nullif(pv.city,''),
           public.haversine_miles(me.lat, me.lng, pv.latitude, pv.longitude),
           jsonb_build_object('venue_type', pv.venue_type,
                              'booking_url', nullif(pv.booking_url,''),
                              'booking_platform', nullif(pv.booking_platform,''))
      from public.padel_venues pv, me
     where p_kind = 'coaching'
       and pv.status = 'active' and pv.merged_into is null
       and coalesce(pv.coaching_available, false)
       and pv.latitude is not null and me.lat is not null
       and public.haversine_miles(me.lat, me.lng, pv.latitude, pv.longitude) <= me.r

    union all
    select p.id, p.name, nullif(p.city,''),
           public.haversine_miles(me.lat, me.lng, p.latitude::double precision, p.longitude::double precision),
           jsonb_build_object('avatar_url', p.avatar_url, 'rating', p.internal_ranking)
      from public.profiles p, me
     where p_kind = 'players'
       and p.latitude is not null and me.lat is not null
       and p.id is distinct from me.uid
       and public.haversine_miles(me.lat, me.lng, p.latitude::double precision, p.longitude::double precision) <= me.r

    union all
    select g.id, g.name, nullif(g.city,''),
           public.haversine_miles(me.lat, me.lng, g.latitude, g.longitude),
           jsonb_build_object(
             'visibility', g.visibility, 'join_mode', g.join_mode,
             'allow_ringers', coalesce(g.allow_ringers, false),
             'auto_approve', coalesce(g.auto_approve, false),
             'banner_url', nullif(g.banner_url,''),
             'member_count', (select count(*) from public.group_members gm
                               where gm.group_id = g.id and gm.status = 'approved'),
             'my_status', (select gm.status from public.group_members gm
                            where gm.group_id = g.id and gm.user_id = me.uid)
           )
      from public.groups g, me
     where p_kind = 'groups'
       and g.latitude is not null and me.lat is not null
       and public.haversine_miles(me.lat, me.lng, g.latitude, g.longitude) <= me.r

    union all
    select l.id, l.name, coalesce(l.format, l.match_type),
           public.haversine_miles(me.lat, me.lng,
             coalesce(l.latitude, pv.latitude)::double precision,
             coalesce(l.longitude, pv.longitude)::double precision),
           jsonb_build_object('entry_fee_pence', nullif(l.entry_fee_pence,0),
                              'currency', l.currency, 'status', l.status)
      from public.leagues l
      left join public.padel_venues pv on pv.venue_id = l.padel_venue_id, me
     where p_kind = 'leagues'
       and l.visibility = 'open'
       and coalesce(l.is_open_registration, false) = true
       and l.status in ('active','upcoming','open')
       and me.lat is not null
       and coalesce(l.latitude, pv.latitude) is not null
       and public.haversine_miles(me.lat, me.lng,
             coalesce(l.latitude, pv.latitude)::double precision,
             coalesce(l.longitude, pv.longitude)::double precision) <= me.r

    union all
    -- EVENTS, kind 1: group events and public events.
    select e.id, e.title, coalesce(pv.venue_name, e.location),
           public.haversine_miles(me.lat, me.lng,
             coalesce(e.latitude, pv.latitude)::double precision,
             coalesce(e.longitude, pv.longitude)::double precision),
           jsonb_build_object('source', 'event', 'route', '/discover/events/' || e.id::text,
                              'start_time', e.start_time,
                              'entry_fee_pence', nullif(e.entry_fee_pence,0),
                              'currency', e.currency,
                              'external_link', nullif(e.external_link,''))
      from public.events e
      left join public.padel_venues pv on pv.venue_id = e.padel_venue_id, me
     where p_kind = 'events'
       and e.visibility in ('public','connections')
       and e.status = 'published'
       and e.start_time >= now()
       and me.lat is not null
       and coalesce(e.latitude, pv.latitude) is not null
       and public.haversine_miles(me.lat, me.lng,
             coalesce(e.latitude, pv.latitude)::double precision,
             coalesce(e.longitude, pv.longitude)::double precision) <= me.r

    union all
    -- EVENTS, kind 2: sessions a venue runs. The id is the OCCURRENCE id,
    -- because /play/events/:occurrenceId routes on that.
    select occ.id, ve.name, v.name,
           public.haversine_miles(me.lat, me.lng, v.latitude::double precision, v.longitude::double precision),
           jsonb_build_object('source', 'venue_event',
                              'route', '/play/events/' || occ.id::text,
                              'start_time', occ.starts_at,
                              'entry_fee_pence', ve.price_per_player,
                              'spots_left', case when ve.capacity is null then null
                                   else greatest(0, ve.capacity - coalesce(occ.spots_taken,0)) end,
                              'padel_venue_id', pv.venue_id)
      from public.venue_event_occurrences occ
      join public.venue_events ve on ve.id = occ.event_id
      join public.venues v        on v.id  = ve.venue_id
      left join public.padel_venues pv on pv.venues_id = v.id, me
     where p_kind = 'events'
       and coalesce(occ.status,'scheduled') <> 'cancelled'
       and occ.starts_at >= now()
       and me.lat is not null
       and v.latitude is not null
       and public.haversine_miles(me.lat, me.lng, v.latitude::double precision, v.longitude::double precision) <= me.r
  )
  select id, title, subtitle, distance_miles, meta
    from rows
   order by distance_miles asc nulls last, title
   offset greatest(coalesce(p_offset, 0), 0)
   limit case when p_limit is null then null else greatest(p_limit, 1) end
$$;


ALTER FUNCTION "public"."discover_list"("p_kind" "text", "p_lat" double precision, "p_lng" double precision, "p_radius_miles" double precision, "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dispatch_match_result_to_elo"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_secret text;
BEGIN
  SELECT decrypted_secret INTO v_secret
  FROM vault.decrypted_secrets WHERE name = 'elo_webhook_secret';

  IF v_secret IS NULL THEN
    RAISE WARNING '[dispatch_match_result_to_elo] vault secret elo_webhook_secret missing; ELO will not process for %', NEW.id;
  END IF;

  PERFORM net.http_post(
    url     := 'https://timbjfihsxqfrqrxwdny.supabase.co/functions/v1/process-elo',
    headers := jsonb_build_object(
                 'Content-Type',     'application/json',
                 'x-webhook-secret', v_secret
               ),
    body    := jsonb_build_object(
                 'type',       TG_OP,
                 'table',      TG_TABLE_NAME,
                 'schema',     TG_TABLE_SCHEMA,
                 'record',     to_jsonb(NEW),
                 'old_record', CASE WHEN TG_OP = 'UPDATE' THEN to_jsonb(OLD) ELSE NULL END
               ),
    timeout_milliseconds := 5000
  );

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."dispatch_match_result_to_elo"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dispatch_notification_to_onesignal"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
