CREATE OR REPLACE FUNCTION "public"."enforce_ppa_bookable_requires_stripe"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  if NEW.ppa_bookable is true then
    -- Gate 1: Stripe Connect with charges enabled
    if not exists (
      select 1 from public.venue_stripe_accounts vsa
       where vsa.venue_id = NEW.venues_id and vsa.charges_enabled = true
    ) then
      NEW.ppa_bookable := false;
    end if;

    -- Gate 2: (active + accepted contract) OR grandfathered
    if NEW.ppa_bookable is true then
      if not exists (
        select 1 from public.venue_contracts c
         where c.venue_id = NEW.venues_id
           and c.status = 'active'
           and c.accepted_at is not null
      ) and not exists (
        select 1 from public.venues v
         where v.id = NEW.venues_id
           and v.grandfathered_ppa_bookable = true
      ) then
        NEW.ppa_bookable := false;
      end if;
    end if;
  end if;
  return NEW;
end;
$$;


ALTER FUNCTION "public"."enforce_ppa_bookable_requires_stripe"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."flag_venues_for_review"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_flagged integer;
begin
  with scored as (
    select v.venue_id,
           case
             when v.venue_name !~* '(padel|pádel)'
              and v.venue_name ~* '\y(swim|kayak|canoe|paddleboard|paddle board|surf school|rowing|pickleball|pickle ball)\y'
               then 'name suggests a different sport'
             when v.venue_name ~* '\y(shop|webshop|store|tienda|negozio|loja|winkel|butik|outlet)\y'
               then 'name suggests a shop, not a venue'
             when v.venue_name ~* '\y(academy|academia|academie|akademi|escuela|escola|school|schule|scuola|clinic|clinica|campamento)\y'
               then 'name suggests an academy or school — may be a coach, not a venue'
             else null
           end as reason
      from public.padel_venues v
     where v.status = 'active'
       and v.venue_type = 'club'
       and coalesce(v.classified_by, '') not like 'admin:%'
       and coalesce(v.number_of_courts, 0) = 0
       and coalesce(v.indoor_courts,    0) = 0
       and coalesce(v.outdoor_courts,   0) = 0
       and coalesce(v.covered_courts,   0) = 0
  )
  update public.padel_venues t
     set needs_review  = true,
         review_reason = s.reason
    from scored s
   where t.venue_id = s.venue_id
     and s.reason is not null
     and (t.needs_review is distinct from true or t.review_reason is distinct from s.reason);

  get diagnostics v_flagged = row_count;

  update public.padel_venues
     set needs_review  = true,
         review_reason = coalesce(nullif(review_reason, ''), '') ||
                         case when coalesce(review_reason, '') = '' then '' else '; ' end ||
                         'postcode and postal_code disagree'
   where status = 'active'
     and coalesce(classified_by, '') not like 'admin:%'
     and postcode is not null
     and postal_code is not null
     and upper(replace(postcode, ' ', '')) <> upper(replace(postal_code, ' ', ''))
     and coalesce(review_reason, '') not like '%postcode and postal_code disagree%';

  return jsonb_build_object(
    'success', true,
    'classification_rows_flagged', v_flagged,
    'queue_size', (select count(*) from public.padel_venues where needs_review and status = 'active')
  );
end;
$$;


ALTER FUNCTION "public"."flag_venues_for_review"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."flag_venues_for_review"() IS 'Re-runnable review-queue flagging. Flags only; never changes venue_type, and never re-flags a row an admin has ruled on (classified_by like ''admin:%'').';



CREATE OR REPLACE FUNCTION "public"."format_money"("p_minor" integer, "p_currency" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $_$
  select case upper(p_currency)
    when 'EUR' then '€'  || to_char(p_minor/100.0, 'FM999G999G990D00')
    when 'GBP' then '£'  || to_char(p_minor/100.0, 'FM999G999G990D00')
    when 'USD' then '$'  || to_char(p_minor/100.0, 'FM999G999G990D00')
    when 'BRL' then 'R$' || to_char(p_minor/100.0, 'FM999G999G990D00')
    when 'SEK' then to_char(p_minor/100.0, 'FM999G999G990D00') || ' kr'
    when 'DKK' then to_char(p_minor/100.0, 'FM999G999G990D00') || ' kr'
    when 'NOK' then to_char(p_minor/100.0, 'FM999G999G990D00') || ' kr'
    else upper(p_currency) || ' ' || to_char(p_minor/100.0, 'FM999G999G990D00')
  end;
$_$;


ALTER FUNCTION "public"."format_money"("p_minor" integer, "p_currency" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_claimable_venue"("p_venue_id" "uuid") RETURNS TABLE("venue_id" "uuid", "venues_id" "uuid", "venue_name" "text", "city" "text", "full_address" "text", "postcode" "text", "website" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select v.venue_id, v.venues_id, v.venue_name, v.city, v.full_address, v.postcode, v.website
  from public.padel_venues v
  where v.venue_id = p_venue_id
    and v.status in ('active', 'pending_review')
  limit 1;
$$;


ALTER FUNCTION "public"."get_claimable_venue"("p_venue_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_household_conflicts"("_user_ids" "uuid"[], "_match_date" "date", "_match_time" time without time zone) RETURNS TABLE("user_id" "uuid", "household_partner_id" "uuid", "conflicting_match_id" "uuid", "conflicting_time" time without time zone, "conflicting_household_member" "uuid", "description" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  DECLARE
    v_window_start time;
    v_window_end   time;                                                                                        
  BEGIN
    v_window_start := _match_time - interval '90 minutes';                                                      
    v_window_end   := _match_time + interval '30 minutes';                                                      
   
    RETURN QUERY                                                                                                
    SELECT                                                  
      p.id                           AS user_id,
      p.household_partner_id         AS household_partner_id,                                                   
      m.id                           AS conflicting_match_id,
      m.match_time::time             AS conflicting_time,                                                       
      p.household_partner_id         AS conflicting_household_member,                                           
      'Your household partner has a match at ' || COALESCE(to_char(m.match_time::time, 'HH24:MI'), '?') AS      
  description                                                                                                   
    FROM unnest(_user_ids) AS uid(id)                                                                           
    JOIN profiles p ON p.id = uid.id                                                                            
    JOIN matches m                                                                                              
      ON m.match_date = _match_date
      AND m.status NOT IN ('cancelled', 'completed')                                                            
      AND p.household_partner_id = ANY(m.player_ids)                                                            
      AND m.match_time IS NOT NULL                                                                              
      AND m.match_time::time >= v_window_start                                                                  
      AND m.match_time::time <= v_window_end                                                                    
    WHERE p.household_partner_id IS NOT NULL;                                                                   
  END;
  $$;


ALTER FUNCTION "public"."get_household_conflicts"("_user_ids" "uuid"[], "_match_date" "date", "_match_time" time without time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_league_climbers"("p_league_id" "uuid") RETURNS TABLE("user_id" "uuid", "elo_gained" integer)
    LANGUAGE "sql" STABLE
    AS $$
  SELECT rh.user_id,
         SUM(rh.rating_change)::integer AS elo_gained
  FROM rating_history rh
  JOIN match_results mr ON mr.id = rh.match_result_id
  JOIN matches m ON m.id = mr.match_id
  JOIN leagues l ON l.id = m.league_id
  WHERE m.league_id = p_league_id
    AND mr.verification_status = 'verified'
    AND NOT COALESCE(mr.is_friendly, false)
    AND (l.season_start IS NULL
         OR COALESCE(mr.verified_at, mr.created_at)::date >= l.season_start)
  GROUP BY rh.user_id
  ORDER BY SUM(rh.rating_change) DESC;
$$;


ALTER FUNCTION "public"."get_league_climbers"("p_league_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_league_upsets"("p_league_id" "uuid") RETURNS TABLE("user_id" "uuid", "upset_wins" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH sets_expanded AS (
    SELECT
      mr.id AS mrid,
      mr.team1_players,
      mr.team2_players,
      COALESCE((s.val->>'team1')::int, (s.val->>'team1_score')::int, 0) AS g1,
      COALESCE((s.val->>'team2')::int, (s.val->>'team2_score')::int, 0) AS g2
    FROM match_results mr
    JOIN matches m ON m.id = mr.match_id
    CROSS JOIN LATERAL jsonb_array_elements(mr.sets_data) AS s(val)
    WHERE m.league_id = p_league_id
      AND mr.verification_status = 'verified'
      AND NOT COALESCE(mr.is_friendly, false)
  ),
  classified AS (
    SELECT se.*, c.is_void
    FROM sets_expanded se
    CROSS JOIN LATERAL classify_set_sql(se.g1, se.g2) c
  ),
  gaps AS (
    SELECT
      cl.mrid,
      CASE WHEN cl.g1 > cl.g2 THEN cl.team1_players ELSE cl.team2_players END AS winners,
      CASE WHEN cl.g1 > cl.g2
        THEN (SELECT COALESCE(SUM(rh.rating_before),0) FROM rating_history rh
              WHERE rh.match_result_id = cl.mrid AND rh.user_id = ANY(cl.team2_players))
           - (SELECT COALESCE(SUM(rh.rating_before),0) FROM rating_history rh
              WHERE rh.match_result_id = cl.mrid AND rh.user_id = ANY(cl.team1_players))
        ELSE (SELECT COALESCE(SUM(rh.rating_before),0) FROM rating_history rh
              WHERE rh.match_result_id = cl.mrid AND rh.user_id = ANY(cl.team1_players))
           - (SELECT COALESCE(SUM(rh.rating_before),0) FROM rating_history rh
              WHERE rh.match_result_id = cl.mrid AND rh.user_id = ANY(cl.team2_players))
      END AS elo_gap
    FROM classified cl
    WHERE NOT cl.is_void
      AND cl.g1 <> cl.g2
  )
  SELECT uid AS user_id, COUNT(*)::integer AS upset_wins
  FROM gaps g
  CROSS JOIN LATERAL unnest(g.winners) AS uid
  WHERE g.elo_gap >= 150
  GROUP BY uid
  ORDER BY COUNT(*) DESC;
$$;


ALTER FUNCTION "public"."get_league_upsets"("p_league_id" "uuid") OWNER TO "postgres";

