SET default_table_access_method = "heap";


CREATE TABLE IF NOT EXISTS "public"."leagues" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "name" "text" NOT NULL,
    "description" "text",
    "created_by" "uuid",
    "match_type" "text" DEFAULT 'individual'::"text",
    "visibility" "text" DEFAULT 'invite_only'::"text",
    "city" "text",
    "country" "text",
    "open_join_approval" boolean DEFAULT true,
    "elo_min" numeric,
    "elo_max" numeric,
    "season_start" "date",
    "season_end" "date",
    "status" "text" DEFAULT 'draft'::"text",
    "gamification_enabled" boolean DEFAULT true,
    "achievements_enabled" boolean DEFAULT true,
    "linked_group_ids" "uuid"[],
    "created_at" timestamp with time zone DEFAULT "now"(),
    "scoring_format" "text" DEFAULT 'standard'::"text",
    "prizes" "text",
    "tournament_start" timestamp with time zone,
    "tournament_end" timestamp with time zone,
    "courts_available" integer DEFAULT 1,
    "match_duration_mins" integer DEFAULT 90,
    "break_duration_mins" integer DEFAULT 10,
    "format" "text" DEFAULT 'round_robin'::"text",
    "max_participants" integer DEFAULT 20,
    "min_elo" integer,
    "max_elo" integer,
    "auto_generate_fixtures" boolean DEFAULT false,
    "banner_url" "text",
    "source_type" "text" DEFAULT 'player'::"text",
    "source_venue_id" "uuid",
    "is_official" boolean DEFAULT false,
    "is_open_registration" boolean DEFAULT false,
    "entry_fee_pence" integer DEFAULT 0,
    "max_rounds" integer,
    "min_sets_per_fixture" integer DEFAULT 2 NOT NULL,
    "prize_scheme" "jsonb",
    "currency" "text",
    "padel_venue_id" "uuid",
    "latitude" numeric,
    "longitude" numeric,
    CONSTRAINT "leagues_format_check" CHECK ((("format" = ANY (ARRAY['round_robin'::"text", 'knockout'::"text", 'americano'::"text", 'mexicano'::"text", 'king_of_hill'::"text", 'compass_draw'::"text", 'box_league'::"text", 'flex_league'::"text"])) OR ("format" IS NULL))),
    CONSTRAINT "leagues_latlng_both_or_neither" CHECK ((("latitude" IS NULL) = ("longitude" IS NULL))),
    CONSTRAINT "leagues_match_type_check" CHECK ((("match_type" = ANY (ARRAY['competitive'::"text", 'friendly'::"text", 'casual'::"text", 'practice'::"text", 'social'::"text", 'pairs'::"text", 'individual'::"text", 'tournament'::"text", 'mexicano'::"text", 'round_robin'::"text", 'knockout'::"text", 'americano'::"text"])) OR ("match_type" IS NULL))),
    CONSTRAINT "leagues_scoring_format_check" CHECK ((("scoring_format" = ANY (ARRAY['standard'::"text", 'short_sets'::"text", 'one_set'::"text", 'custom'::"text"])) OR ("scoring_format" IS NULL))),
    CONSTRAINT "leagues_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'active'::"text", 'completed'::"text", 'archived'::"text"])))
);


