CREATE OR REPLACE FUNCTION "public"."get_match_invite_preview"("p_token" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v jsonb;
BEGIN
  SELECT jsonb_build_object(
    'guest_name', gi.guest_name,
    'status', gi.status,
    'expired', (gi.expires_at < now()),
    'match_id', m.id,
    'match_date', m.match_date,
    'match_time', m.match_time,
    'venue', m.booked_venue_name,
    'inviter_name', p.name
  ) INTO v
  FROM public.match_guest_invites gi
  JOIN public.matches m ON m.id = gi.match_id
  LEFT JOIN public.profiles p ON p.id = gi.invited_by
  WHERE gi.invite_token = p_token;

  RETURN coalesce(v, jsonb_build_object('error', 'invalid_token'));
END; $$;


ALTER FUNCTION "public"."get_match_invite_preview"("p_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_rider_address_for_driver"("p_match_id" "uuid", "p_rider_id" "uuid") RETURNS TABLE("postal_code" "text", "city" "text", "latitude" numeric, "longitude" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM travel_requests
    WHERE match_id     = p_match_id
      AND requester_id = p_rider_id
      AND driver_id    = v_caller
      AND status       = 'accepted'
  ) THEN
    RAISE EXCEPTION 'Not authorised — you are not the confirmed driver for this rider';
  END IF;

  RETURN QUERY
  SELECT p.postal_code, p.city, p.latitude, p.longitude
  FROM profiles p
  WHERE p.id = p_rider_id;
END;
$$;


ALTER FUNCTION "public"."get_rider_address_for_driver"("p_match_id" "uuid", "p_rider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_venue_activity"("p_venue_id" "uuid", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "kind" "text", "channel" "text", "subject" "text", "body" "text", "metadata" "jsonb", "actor_email" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not exists (select 1 from public.platform_admins where user_id = auth.uid())
  then raise exception 'not_authorized'; end if;

  return query
  select a.id, a.kind, a.channel, a.subject, a.body, a.metadata,
         p.email as actor_email, a.created_at
    from public.venue_activity_log a
    join public.profiles p on p.id = a.actor_id
   where a.venue_id = p_venue_id
   order by a.created_at desc
   limit p_limit offset p_offset;
end $$;


ALTER FUNCTION "public"."get_venue_activity"("p_venue_id" "uuid", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_verified_peer_vote_counts"("p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("user_id" "uuid", "vote_category" "text", "vote_count" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    pv.voted_for_id AS user_id,
    pv.vote_category,
    COUNT(*) AS vote_count
  FROM match_peer_votes pv
  JOIN match_results mr ON mr.match_id = pv.match_id
  WHERE mr.verification_status = 'verified'
    AND (p_user_id IS NULL OR pv.voted_for_id = p_user_id)
  GROUP BY pv.voted_for_id, pv.vote_category;
$$;


ALTER FUNCTION "public"."get_verified_peer_vote_counts"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_weekly_league_vote_standings"("p_league_id" "uuid", "p_week_start" "date" DEFAULT NULL::"date") RETURNS TABLE("user_id" "uuid", "vote_count" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    pv.voted_for_id AS user_id,
    COUNT(*) AS vote_count
  FROM match_peer_votes pv
  JOIN match_results mr ON mr.match_id = pv.match_id
  JOIN matches m         ON m.id = pv.match_id
  WHERE mr.verification_status = 'verified'
    AND m.league_id = p_league_id
    AND pv.created_at >= COALESCE(p_week_start, date_trunc('week', CURRENT_DATE)::date)
    AND pv.created_at <  COALESCE(p_week_start, date_trunc('week', CURRENT_DATE)::date) + INTERVAL '7 days'
  GROUP BY pv.voted_for_id
  ORDER BY vote_count DESC;
$$;


