    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM groups WHERE id = _group_id AND admin_id = _user_id
    UNION
    SELECT 1 FROM group_members 
    WHERE group_id = _group_id 
    AND user_id = _user_id 
    AND role = 'admin' 
    AND status = 'approved'
  );
$$;


