ALTER FUNCTION "public"."is_venue_staff"("p_venue_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."join_group_by_invite"("_invite_code" "text", "_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_group_id uuid;
  v_existing_member boolean;
BEGIN
  -- Find the group by invite code
  SELECT id INTO v_group_id
  FROM groups
  WHERE invite_code = _invite_code;

  IF v_group_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Invalid invite code'
    );
  END IF;

  -- Check if already a member
  SELECT EXISTS(
    SELECT 1 FROM group_members 
    WHERE group_id = v_group_id AND user_id = _user_id
  ) INTO v_existing_member;

  IF v_existing_member THEN
    RETURN jsonb_build_object(
      'success', true,
      'already_member', true,
      'group_id', v_group_id
    );
  END IF;

  -- Add user to group (auto-approved for invite links)
  INSERT INTO group_members (group_id, user_id, status, role)
  VALUES (v_group_id, _user_id, 'approved', 'member');

  RETURN jsonb_build_object(
    'success', true,
    'already_member', false,
    'group_id', v_group_id
  );
END;
$$;


ALTER FUNCTION "public"."join_group_by_invite"("_invite_code" "text", "_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."join_league"("p_league_id" "uuid", "p_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF v_caller <> p_user_id THEN
    IF NOT EXISTS (
      SELECT 1 FROM leagues WHERE id = p_league_id AND created_by = v_caller
    ) AND NOT EXISTS (
      SELECT 1 FROM league_members
      WHERE league_id = p_league_id AND user_id = v_caller AND role = 'admin'
    ) THEN
      RAISE EXCEPTION 'Only the player themselves or a league admin can add members';
    END IF;
  END IF;

  IF EXISTS (
    SELECT 1 FROM league_members
    WHERE league_id = p_league_id AND user_id = p_user_id
  ) THEN
    RETURN;
  END IF;

  INSERT INTO league_members (league_id, user_id, role, status)
  VALUES (p_league_id, p_user_id, 'member', 'active');

  INSERT INTO league_standings (league_id, user_id, wins, losses, draws, matches_played, ranking_points, category)
  VALUES (p_league_id, p_user_id, 0, 0, 0, 0, 0, 'overall');
END;
$$;


ALTER FUNCTION "public"."join_league"("p_league_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."join_league_bulk"("p_league_id" "uuid", "p_user_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_added  int := 0;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM leagues WHERE id = p_league_id AND created_by = v_caller
  ) AND NOT EXISTS (
    SELECT 1 FROM league_members
    WHERE league_id = p_league_id AND user_id = v_caller AND role = 'admin'
  ) THEN
    RAISE EXCEPTION 'Only a league admin can bulk-add members';
  END IF;

  INSERT INTO league_members (league_id, user_id, role, status)
  SELECT p_league_id, uid, 'member', 'active'
  FROM unnest(p_user_ids) AS uid
  WHERE NOT EXISTS (
    SELECT 1 FROM league_members lm
    WHERE lm.league_id = p_league_id AND lm.user_id = uid
  );

  GET DIAGNOSTICS v_added = ROW_COUNT;

  INSERT INTO league_standings (league_id, user_id, wins, losses, draws, matches_played, ranking_points, category)
  SELECT p_league_id, uid, 0, 0, 0, 0, 0, 'overall'
  FROM unnest(p_user_ids) AS uid
  WHERE EXISTS (
    SELECT 1 FROM league_members lm
    WHERE lm.league_id = p_league_id AND lm.user_id = uid
  )
  AND NOT EXISTS (
    SELECT 1 FROM league_standings ls
    WHERE ls.league_id = p_league_id AND ls.user_id = uid
  );

  RETURN jsonb_build_object('added', v_added);
END;
$$;


ALTER FUNCTION "public"."join_league_bulk"("p_league_id" "uuid", "p_user_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."join_venue_event"("p_occurrence_id" "uuid", "p_order_item_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_updated INT;
  v_price   numeric;
BEGIN
  -- Auth guard: anon must not reach this.
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
  END IF;

  -- Guard: already joined?
  IF EXISTS (
    SELECT 1 FROM venue_event_participants
    WHERE occurrence_id = p_occurrence_id
      AND user_id = v_user_id
      AND status = 'joined'
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Already joined');
  END IF;

  -- Price gate: if the event costs money, a SPECIFIC paid order_item must exist.
  SELECT ev.price_per_player INTO v_price
  FROM venue_event_occurrences occ
  JOIN venue_events ev ON ev.id = occ.event_id
  WHERE occ.id = p_occurrence_id;

  IF v_price IS NOT NULL AND v_price > 0 THEN
    IF p_order_item_id IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error', 'payment_required');
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM order_items
      WHERE id = p_order_item_id
        AND user_id = v_user_id
        AND occurrence_id = p_occurrence_id
        AND status = 'paid'
    ) THEN
      RETURN jsonb_build_object('success', false, 'error', 'payment_required');
    END IF;
  END IF;

  -- Atomic capacity check + increment (unchanged).
  UPDATE venue_event_occurrences occ
  SET spots_taken = occ.spots_taken + 1
  FROM venue_events ev
  WHERE occ.id = p_occurrence_id
    AND ev.id = occ.event_id
    AND occ.status = 'scheduled'
    AND (ev.capacity IS NULL OR occ.spots_taken < ev.capacity);

  GET DIAGNOSTICS v_updated = ROW_COUNT;

  IF v_updated = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Event is full or not available');
  END IF;

  -- Insert (or re-activate a previously cancelled row).
  -- Bind the order item so every paid seat records which payment bought it.
  INSERT INTO venue_event_participants (occurrence_id, user_id, status, order_item_id)
  VALUES (p_occurrence_id, v_user_id, 'joined', p_order_item_id)
  ON CONFLICT (occurrence_id, user_id)
  DO UPDATE SET status = 'joined', order_item_id = EXCLUDED.order_item_id;

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."join_venue_event"("p_occurrence_id" "uuid", "p_order_item_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."league_points_for_result"("p_result" "text") RETURNS integer
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT CASE p_result
    WHEN 'win'  THEN 3
    WHEN 'draw' THEN 1
    WHEN 'loss' THEN 0
    ELSE NULL
  END;
$$;


