    FROM profiles
    WHERE id = NEW.connected_user_id;

    -- Notify the original sender
    INSERT INTO notifications (user_id, type, title, message, related_id)
    VALUES (
      NEW.user_id,
      'connection_accepted',
      'Connection Accepted',
      v_accepter_name || ' accepted your connection request',
      NEW.id
    );
  END IF;

  RETURN NEW;
END;
$$;


