CREATE OR REPLACE FUNCTION "public"."notify_connections_of_broadcast"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_name  text;
  v_when  text;
  v_day   text;
begin
  if new.is_open is not true
     or new.open_audience <> 'connections'
     or coalesce(array_length(new.player_ids, 1), 0) <> 1 then
    return new;
  end if;

  if exists (
    select 1 from matches m
    where m.created_by = new.created_by
      and m.id <> new.id
      and m.is_open
      and m.open_audience = 'connections'
      and m.opened_at > now() - interval '6 hours'
  ) then
    return new;
  end if;

  select coalesce(name, 'A player') into v_name from profiles where id = new.created_by;

  v_day := case
    when new.match_date = current_date then 'today'
    when new.match_date = current_date + 1 then 'tomorrow'
    else trim(to_char(new.match_date, 'Day'))
  end;

  v_when := case
    when new.window_start = '08:00' and new.window_end = '22:00' then v_day
    when new.window_start >= '17:00' then v_day || ' evening'
    when new.window_start >= '12:00' then v_day || ' afternoon'
    when new.window_start is not null then v_day || ' morning'
    else v_day
  end;

  insert into notifications (user_id, type, title, message, related_id)
  select
    case when pc.user_id = new.created_by then pc.connected_user_id else pc.user_id end,
    'open_match_broadcast',
    v_name || ' is free ' || v_when,
    coalesce(nullif(trim(new.notes), '') || ' — tap to join.', 'Tap to join if you fancy a game.'),
    new.id
  from player_connections pc
  where pc.status = 'accepted'
    and (pc.user_id = new.created_by or pc.connected_user_id = new.created_by)
    and case when pc.user_id = new.created_by then pc.connected_user_id else pc.user_id end
        <> new.created_by;

  return new;
end;
$$;


ALTER FUNCTION "public"."notify_connections_of_broadcast"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_group_addition"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_group_name TEXT;
  v_admin_name TEXT;
BEGIN
  -- Only notify for approved members
  IF NEW.status = 'approved' AND (OLD IS NULL OR OLD.status != 'approved') THEN
    -- Get group and admin info
    SELECT g.name, p.name 
    INTO v_group_name, v_admin_name
    FROM groups g
    JOIN profiles p ON p.id = g.admin_id
    WHERE g.id = NEW.group_id;

    -- Create notification
    INSERT INTO notifications (user_id, type, title, message, related_id)
    VALUES (
      NEW.user_id,
      'group_added',
      'Added to Group',
      'You have been added to ' || v_group_name,
      NEW.group_id
    );
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."notify_group_addition"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_group_join_request"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_admin_id   UUID;
  v_group_name TEXT;
  v_player_name TEXT;
BEGIN
  -- Only fire for pending requests (new join requests, not direct adds)
  IF NEW.status != 'pending' THEN
    RETURN NEW;
  END IF;

  -- Get group name and admin id
  SELECT g.name, g.admin_id
  INTO v_group_name, v_admin_id
  FROM groups g
  WHERE g.id = NEW.group_id;

  -- Get requesting player's name
  SELECT COALESCE(name, 'Someone') INTO v_player_name
  FROM profiles
  WHERE id = NEW.user_id;

  -- Don't notify admin if they are the one joining (self-admin case)
  IF v_admin_id IS NULL OR v_admin_id = NEW.user_id THEN
    RETURN NEW;
  END IF;

  -- Insert notification for admin
  INSERT INTO notifications (user_id, type, title, message, related_id, read)
  VALUES (
    v_admin_id,
    'join_request',
    'New Join Request',
    v_player_name || ' wants to join ' || COALESCE(v_group_name, 'your group'),
    NEW.group_id,
    false
  );

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."notify_group_join_request"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_household_accepted"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_accepter_name TEXT;
BEGIN
  IF NEW.status = 'accepted' AND OLD.status = 'pending' THEN
    -- Get accepter's name
    SELECT name INTO v_accepter_name
    FROM profiles
    WHERE id = NEW.household_member_id;

    -- Notify the original inviter
    INSERT INTO notifications (user_id, type, title, message, related_id)
    VALUES (
      NEW.user_id,
      'household_accepted',
      'Household Invitation Accepted',
      v_accepter_name || ' accepted your household invitation',
      NEW.id
    );

    -- Create reciprocal household relationship
    INSERT INTO households (user_id, household_member_id, status)
    VALUES (NEW.household_member_id, NEW.user_id, 'accepted')
    ON CONFLICT DO NOTHING;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."notify_household_accepted"() OWNER TO "postgres";


