BEGIN
  -- Get inviter's name
  SELECT name INTO v_inviter_name
  FROM profiles
  WHERE id = NEW.user_id;

  -- Create notification for the invited person
  INSERT INTO notifications (user_id, type, title, message, related_id)
  VALUES (
    NEW.household_member_id,
    'household_invitation',
    'Household Invitation',
    v_inviter_name || ' wants to add you to their household',
    NEW.id
  );

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."notify_household_invitation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_match_comment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_player_id UUID;
  v_commenter_name TEXT;
  v_match_date DATE;
  v_player_ids UUID[];
BEGIN
  -- Get commenter name and match details
  SELECT p.name INTO v_commenter_name
  FROM profiles p
  WHERE p.id = NEW.user_id;

  SELECT m.match_date, m.player_ids INTO v_match_date, v_player_ids
  FROM matches m
  WHERE m.id = NEW.match_id;

  -- Notify all other players in the match (not the commenter)
  FOREACH v_player_id IN ARRAY v_player_ids
  LOOP
    -- Skip the commenter
    IF v_player_id != NEW.user_id THEN
      INSERT INTO notifications (user_id, type, title, message, related_id)
      VALUES (
        v_player_id,
        'match_comment',
        'New Comment',
        v_commenter_name || ' commented on your match from ' || TO_CHAR(v_match_date, 'DD/MM/YYYY'),
        NEW.match_id
      );
    END IF;
  END LOOP;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."notify_match_comment"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_match_scheduled"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_player_id          UUID;
  v_group_name         TEXT;
  v_player_names       TEXT[];
  v_player_name        TEXT;
  v_players_str        TEXT;
  v_venue_str          TEXT;
  v_day_str            TEXT;
  v_notification_body  TEXT;
  v_other_players_str  TEXT;
  v_existing_count     INTEGER;
BEGIN
  -- Only fire on INSERT
  IF TG_OP != 'INSERT' THEN
    RETURN NEW;
  END IF;

  -- Get group name
  SELECT name INTO v_group_name
  FROM groups
  WHERE id = NEW.group_id;

  -- Build day-of-week + date string  e.g. "Mon 30 Mar"
  v_day_str := TO_CHAR(NEW.match_date, 'Dy DD Mon');

  -- Venue suffix — only if a venue is booked
  IF NEW.booked_venue_name IS NOT NULL AND NEW.booked_venue_name != '' THEN
    v_venue_str := ' 📍 ' || NEW.booked_venue_name;
  ELSE
    v_venue_str := '';
  END IF;

  -- Collect all player names
  v_player_names := ARRAY[]::TEXT[];
  FOR v_player_id IN SELECT unnest(NEW.player_ids) LOOP
    SELECT COALESCE(name, 'Unknown') INTO v_player_name
    FROM profiles WHERE id = v_player_id;
    v_player_names := v_player_names || v_player_name;
  END LOOP;
  v_players_str := array_to_string(v_player_names, ', ');

  -- Notify each player in the match
  FOREACH v_player_id IN ARRAY NEW.player_ids
  LOOP
    v_notification_body :=
      COALESCE(v_group_name, 'Your group') || ' match on ' ||
      v_day_str || ' at ' ||
      TO_CHAR(NEW.match_time, 'HH24:MI') ||
      v_venue_str ||
      ' with ' || v_players_str;

    -- Deduplicate
    SELECT COUNT(*) INTO v_existing_count
    FROM notifications
    WHERE user_id = v_player_id
      AND type = 'match_scheduled'
      AND related_id = NEW.id;

    IF v_existing_count = 0 THEN
      INSERT INTO notifications (user_id, type, title, message, related_id)
      VALUES (
        v_player_id,
        'match_scheduled',
        'Match Scheduled',
        v_notification_body,
        NEW.id
      );
    END IF;
  END LOOP;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."notify_match_scheduled"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_new_poll"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_member_id UUID;
  v_group_name TEXT;
BEGIN
  -- Get group name
  SELECT name INTO v_group_name
  FROM groups
  WHERE id = NEW.group_id;

  -- Notify all approved group members except the creator
  FOR v_member_id IN 
    SELECT gm.user_id 
    FROM group_members gm
    WHERE gm.group_id = NEW.group_id 
    AND gm.status = 'approved'
    AND gm.user_id != (SELECT user_id FROM auth.users WHERE id = auth.uid() LIMIT 1)
  LOOP
    INSERT INTO notifications (user_id, type, title, message, related_id)
    VALUES (
      v_member_id,
      'poll_created',
      'New Poll',
      'A new poll "' || NEW.title || '" has been created in ' || v_group_name,
      NEW.id
    );
  END LOOP;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."notify_new_poll"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_platform_admins"("p_type" "text", "p_title" "text", "p_message" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_emails text[];
  v_secret text;
BEGIN
  v_emails := public.platform_admin_emails();

  IF array_length(v_emails, 1) IS NULL THEN
    RAISE WARNING '[notify_platform_admins] no admin email addresses for: %', p_title;
    RETURN 0;
  END IF;

  SELECT decrypted_secret INTO v_secret
  FROM vault.decrypted_secrets WHERE name = 'ops_alert_secret';

  IF v_secret IS NULL THEN
    RAISE WARNING '[notify_platform_admins] vault secret ops_alert_secret missing; alert not sent: %', p_title;
    RETURN 0;
  END IF;

  PERFORM net.http_post(
    url     := 'https://timbjfihsxqfrqrxwdny.supabase.co/functions/v1/ops-alert',
    headers := jsonb_build_object(
                 'Content-Type',     'application/json',
                 'x-webhook-secret', v_secret),
    body    := jsonb_build_object(
                 'subject',    p_title,
                 'body',       p_message,
                 'recipients', to_jsonb(v_emails)),
    timeout_milliseconds := 5000
  );

  RETURN array_length(v_emails, 1);
END;
$$;


ALTER FUNCTION "public"."notify_platform_admins"("p_type" "text", "p_title" "text", "p_message" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."notify_platform_admins"("p_type" "text", "p_title" "text", "p_message" "text") IS 'Sends an operational alert to platform admins by EMAIL via the ops-alert Edge Function. Never writes to public.notifications — ops alerts must not be able to reach the player push channel.';



CREATE OR REPLACE FUNCTION "public"."platform_admin_emails"() RETURNS "text"[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT COALESCE(ARRAY_AGG(u.email ORDER BY u.email), '{}'::text[])
  FROM platform_admins pa
  JOIN auth.users u ON u.id = pa.user_id
  WHERE u.email IS NOT NULL;
$$;


ALTER FUNCTION "public"."platform_admin_emails"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."postcode_outcode"("p_postcode" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case
           when coalesce(btrim(p_postcode), '') = '' then null
           when position(' ' in btrim(upper(p_postcode))) > 0
             then split_part(btrim(upper(p_postcode)), ' ', 1)
           else btrim(upper(p_postcode))
         end;
$$;


ALTER FUNCTION "public"."postcode_outcode"("p_postcode" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."postcode_outcode"("p_postcode" "text") IS 'Outward code of a postcode ("BS1 3XT" -> "BS1"); the whole value when it holds no space.';



CREATE OR REPLACE FUNCTION "public"."preview_standard_pricing"("p_venue_id" "uuid") RETURNS TABLE("plan_key" "text", "name" "text", "currency" "text", "monthly_price_minor" integer, "commission_rate_bps" integer, "is_available" boolean, "pricing_country_code" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_cc  text;
  v_cur text;
begin
  select pv.country_code into v_cc
    from public.padel_venues pv
   where pv.venues_id = p_venue_id
   limit 1;

  -- The country's own currency if it has approved prices; otherwise the resolver's,
  -- so a Core-only venue in an unpriced country still displays coherently.
  select cpp.currency into v_cur
    from public.country_plan_prices cpp
   where cpp.country_code = v_cc
   limit 1;
  if v_cur is null then
    select rp.currency into v_cur from public.resolve_country_pricing(v_cc) rp;
  end if;

  return query
    select sp.key,
           sp.name,
           coalesce(cpp.currency, v_cur),
           case when sp.court_hour_multiple = 0 then 0 else cpp.monthly_price_minor end,
           sp.commission_rate_bps,
           (sp.court_hour_multiple = 0) or (cpp.country_code is not null),
           v_cc
      from public.standard_plans sp
      left join public.country_plan_prices cpp
        on cpp.country_code = v_cc and cpp.plan_key = sp.key
     order by sp.court_hour_multiple;
end $$;


ALTER FUNCTION "public"."preview_standard_pricing"("p_venue_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."promote_to_group_admin"("p_group_id" "uuid", "p_new_admin_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Caller must currently be an admin (founder via groups.admin_id OR role='admin')
  IF NOT EXISTS (
    SELECT 1 FROM groups WHERE id = p_group_id AND admin_id = v_caller
  ) AND NOT EXISTS (
    SELECT 1 FROM group_members
    WHERE group_id = p_group_id AND user_id = v_caller AND role = 'admin'
  ) THEN
    RAISE EXCEPTION 'Only a group admin can promote members';
  END IF;

  -- Target must be a member
  IF NOT EXISTS (
    SELECT 1 FROM group_members
    WHERE group_id = p_group_id AND user_id = p_new_admin_id
  ) THEN
    RAISE EXCEPTION 'Player is not a member of this group';
  END IF;

  -- Promotion grants admin POWERS via role only.
  -- groups.admin_id is the founder/creator and must NOT change.
  UPDATE group_members
  SET role = 'admin'
  WHERE group_id = p_group_id AND user_id = p_new_admin_id;
END;
$$;


ALTER FUNCTION "public"."promote_to_group_admin"("p_group_id" "uuid", "p_new_admin_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."push_match_to_open"("p_match_id" "uuid", "p_elo_min" integer, "p_elo_max" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$                                                                                                                 
  DECLARE                                                   
    v_user_id uuid := auth.uid();
    v_match record;
    v_is_player boolean := false;
    v_is_admin boolean := false;
    v_expiry timestamptz;                                                                                               
  BEGIN
    IF v_user_id IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;                                              
                                                            
    SELECT * INTO v_match FROM matches WHERE id = p_match_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Match not found'; END IF;
                                                                                                                        
    IF array_length(v_match.player_ids, 1) >= 4 THEN
      RAISE EXCEPTION 'Match is already full';                                                                          
    END IF;                                                 

    v_is_player := v_user_id = ANY(COALESCE(v_match.player_ids, ARRAY[]::uuid[]));                                      
    IF NOT v_is_player AND v_match.group_id IS NOT NULL THEN
      SELECT EXISTS (                                                                                                   
        SELECT 1 FROM group_members                         
        WHERE group_id = v_match.group_id AND user_id = v_user_id AND role = 'admin'                                    
      ) INTO v_is_admin;
    END IF;                                                                                                             
                                                            
    IF NOT v_is_player AND NOT v_is_admin THEN                                                                          
      RAISE EXCEPTION 'Only match players or group admins can open a match';
    END IF;                                                                                                             
                                                            
    v_expiry := (v_match.match_date::timestamp + COALESCE(v_match.match_time, '00:00')::time) - INTERVAL '2 hours';     
    IF v_expiry <= now() THEN
      RAISE EXCEPTION 'Too late to open this match';                                                                    
    END IF;                                                 

    IF p_elo_min < 600 OR p_elo_max > 2500 OR p_elo_min >= p_elo_max THEN                                               
      RAISE EXCEPTION 'Invalid ELO range';
    END IF;                                                                                                             
                                                            
    UPDATE matches
    SET is_open = true, open_elo_min = p_elo_min, open_elo_max = p_elo_max,
        opened_by = v_user_id, opened_at = now(), updated_at = now()                                                    
    WHERE id = p_match_id;
                                                                                                                        
    RETURN jsonb_build_object('success', true);                                                                         
  END;
  $$;


ALTER FUNCTION "public"."push_match_to_open"("p_match_id" "uuid", "p_elo_min" integer, "p_elo_max" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rebuild_league_standings"("p_league_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_mr record; v_set jsonb; v_g1 int; v_g2 int;
  v_completed boolean; v_is_void boolean; v_is_draw boolean;
  v_t1_players uuid[]; v_t2_players uuid[]; v_winners uuid[]; v_losers uuid[];
  v_sets_count int; v_sets_applied int := 0; v_matches_processed int := 0;
BEGIN
  UPDATE league_standings
  SET wins=0, losses=0, draws=0, matches_played=0, ranking_points=0
  WHERE league_id = p_league_id;

  FOR v_mr IN
    SELECT mr.id, mr.team1_players, mr.team2_players, mr.sets_data
    FROM match_results mr JOIN matches m ON m.id = mr.match_id
    WHERE m.league_id = p_league_id AND mr.verification_status = 'verified'
    ORDER BY COALESCE(mr.verified_at, mr.created_at) ASC, mr.id ASC
  LOOP
    v_t1_players := v_mr.team1_players;
    v_t2_players := v_mr.team2_players;
    IF v_mr.sets_data IS NULL OR jsonb_typeof(v_mr.sets_data::jsonb) <> 'array' THEN
      v_matches_processed := v_matches_processed + 1; CONTINUE;
    END IF;
    v_sets_count := jsonb_array_length(v_mr.sets_data::jsonb);
    FOR i IN 0 .. v_sets_count - 1 LOOP
      v_set := v_mr.sets_data::jsonb -> i;
      v_g1 := COALESCE((v_set->>'team1')::int, (v_set->>'team1_score')::int, 0);
      v_g2 := COALESCE((v_set->>'team2')::int, (v_set->>'team2_score')::int, 0);

      SELECT c.is_completed, c.is_void INTO v_completed, v_is_void
      FROM classify_set_sql(v_g1, v_g2) c;

      IF v_is_void THEN CONTINUE; END IF;

      IF v_completed THEN
        v_is_draw := false;
        IF v_g1 > v_g2 THEN v_winners := v_t1_players; v_losers := v_t2_players;
        ELSE v_winners := v_t2_players; v_losers := v_t1_players; END IF;
      ELSE
        IF v_g1 = v_g2 THEN v_is_draw := true;
        ELSE v_is_draw := false;
          IF v_g1 > v_g2 THEN v_winners := v_t1_players; v_losers := v_t2_players;
          ELSE v_winners := v_t2_players; v_losers := v_t1_players; END IF;
        END IF;
      END IF;
      IF v_is_draw THEN
        UPDATE league_standings SET draws=draws+1, matches_played=matches_played+1, ranking_points=ranking_points+league_points_for_result('draw')
        WHERE league_id = p_league_id AND user_id = ANY(v_t1_players || v_t2_players);
      ELSE
        UPDATE league_standings SET wins=wins+1, matches_played=matches_played+1, ranking_points=ranking_points+league_points_for_result('win')
        WHERE league_id = p_league_id AND user_id = ANY(v_winners);
        UPDATE league_standings SET losses=losses+1, matches_played=matches_played+1
        WHERE league_id = p_league_id AND user_id = ANY(v_losers);
      END IF;
      v_sets_applied := v_sets_applied + 1;
    END LOOP;
    v_matches_processed := v_matches_processed + 1;
  END LOOP;

  RETURN jsonb_build_object('league_id', p_league_id, 'matches_processed', v_matches_processed, 'sets_applied', v_sets_applied);
END;
$$;


ALTER FUNCTION "public"."rebuild_league_standings"("p_league_id" "uuid") OWNER TO "postgres";


