CREATE OR REPLACE FUNCTION "public"."redeem_voucher"("p_venue_id" "uuid", "p_code" "text", "p_amount_pence" integer, "p_user_id" "uuid" DEFAULT NULL::"uuid", "p_booking_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_check jsonb;
  v_voucher_id uuid;
  v_discount int;
begin
  v_check := public.validate_voucher(p_venue_id, p_code, p_amount_pence, p_user_id);
  if not (v_check->>'valid')::boolean then
    return v_check;
  end if;
  v_voucher_id := (v_check->>'voucher_id')::uuid;
  v_discount := (v_check->>'discount_pence')::int;

  -- Lock the row to avoid over-redemption under concurrency.
  perform 1 from public.vouchers where id = v_voucher_id for update;

  insert into public.voucher_redemptions (voucher_id, venue_id, user_id, booking_id, amount_pence)
    values (v_voucher_id, p_venue_id, p_user_id, p_booking_id, v_discount);
  update public.vouchers set times_redeemed = times_redeemed + 1 where id = v_voucher_id;

  return jsonb_build_object('valid', true, 'voucher_id', v_voucher_id, 'discount_pence', v_discount, 'message', 'Redeemed.');
end;
$$;


ALTER FUNCTION "public"."redeem_voucher"("p_venue_id" "uuid", "p_code" "text", "p_amount_pence" integer, "p_user_id" "uuid", "p_booking_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_teammate"("p_venue_id" "uuid", "p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_owner_count int;
begin
  if not public._is_active_owner(p_venue_id) then
    return jsonb_build_object('status','not_authorised');
  end if;
  select count(*) into v_owner_count from public.venue_users
    where venue_id = p_venue_id and role = 'owner' and status = 'active';
  if v_owner_count <= 1
     and exists (select 1 from public.venue_users
                 where venue_id = p_venue_id and user_id = p_user_id
                   and role = 'owner' and status = 'active') then
    return jsonb_build_object('status','last_owner');
  end if;
  update public.venue_users set status = 'revoked'
    where venue_id = p_venue_id and user_id = p_user_id;
  return jsonb_build_object('status','removed');
end;
$$;


ALTER FUNCTION "public"."remove_teammate"("p_venue_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_household_link"("p_partner_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller       uuid := auth.uid();
  v_caller_name  text;
  v_caller_partner uuid;
  v_target_partner uuid;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF v_caller = p_partner_id THEN
    RAISE EXCEPTION 'Cannot link to yourself';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = p_partner_id) THEN
    RAISE EXCEPTION 'Player not found';
  END IF;

  -- Check neither party already has a partner
  SELECT household_partner_id INTO v_caller_partner FROM profiles WHERE id = v_caller;
  IF v_caller_partner IS NOT NULL THEN
    RAISE EXCEPTION 'You already have a household partner — unlink first';
  END IF;

  SELECT household_partner_id INTO v_target_partner FROM profiles WHERE id = p_partner_id;
  IF v_target_partner IS NOT NULL THEN
    RAISE EXCEPTION 'This player already has a household partner';
  END IF;

  -- Check no pending request already exists (either direction)
  IF EXISTS (
    SELECT 1 FROM household_link_requests
    WHERE status = 'pending'
      AND ((requester_id = v_caller AND target_id = p_partner_id)
        OR (requester_id = p_partner_id AND target_id = v_caller))
  ) THEN
    RAISE EXCEPTION 'A pending request already exists between you and this player';
  END IF;

  -- Create the request
  INSERT INTO household_link_requests (requester_id, target_id, status)
  VALUES (v_caller, p_partner_id, 'pending')
  ON CONFLICT (requester_id, target_id) DO UPDATE
    SET status = 'pending', responded_at = NULL, created_at = now();

  -- Notify the target
  SELECT name INTO v_caller_name FROM profiles WHERE id = v_caller;
  INSERT INTO notifications (user_id, type, title, message, related_id, read)
  VALUES (
    p_partner_id,
    'household_link_request',
    'Household link request',
    COALESCE(v_caller_name, 'A player') || ' wants to link as household partners.',
    v_caller,
    false
  );
END;
$$;


ALTER FUNCTION "public"."request_household_link"("p_partner_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reset_contract_acceptance_on_material_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if OLD.accepted_at is not null and NEW.status = 'active' then
    if (
      NEW.commission_rate_bps  is distinct from OLD.commission_rate_bps  or
      NEW.monthly_price_pence  is distinct from OLD.monthly_price_pence  or
      NEW.monthly_credit_pence is distinct from OLD.monthly_credit_pence or
      NEW.plan_tier            is distinct from OLD.plan_tier            or
      NEW.currency             is distinct from OLD.currency             or
      NEW.start_date           is distinct from OLD.start_date           or
      NEW.end_date             is distinct from OLD.end_date
    ) then
      NEW.accepted_at := null;
      NEW.accepted_by := null;

      update public.venues set grandfathered_ppa_bookable = true
       where id = NEW.venue_id
         and grandfathered_ppa_bookable = false
         and exists (
           select 1 from public.padel_venues pv
            where pv.venues_id = NEW.venue_id and pv.ppa_bookable = true
         );
    end if;
  end if;
  return NEW;
end;
$$;


ALTER FUNCTION "public"."reset_contract_acceptance_on_material_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reset_league_season"("p_league_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  -- authorize: caller must be the league creator or an admin member
  if not exists (
        select 1 from leagues
        where id = p_league_id and created_by = auth.uid()
      )
     and not exists (
        select 1 from league_members
        where league_id = p_league_id and user_id = auth.uid() and role = 'admin'
      )
  then
    raise exception 'not authorized to reset this league season';
  end if;

  update league_standings
  set season_elo     = 1230,
      matches_played = 0,
      wins           = 0,
      losses         = 0,
      draws          = 0,
      ranking_points = 0,
      updated_at     = now()
  where league_id = p_league_id;

  update league_members
  set season_points = 0,
      wins          = 0,
      losses        = 0,
      draws         = 0
  where league_id = p_league_id;
end;
$$;


ALTER FUNCTION "public"."reset_league_season"("p_league_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_country_pricing"("p_country_code" "text") RETURNS TABLE("currency" "text", "reference_court_hour_minor" integer, "min_fee_minor" integer, "band_key" "text", "confidence" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  return query
    select cp.currency, cp.reference_court_hour_minor, cp.min_fee_minor, cp.band_key, cp.confidence
    from public.country_pricing cp
    where cp.country_code = p_country_code;
  if found then return; end if;

  return query
    select b.default_currency, b.reference_court_hour_minor, b.min_fee_minor, b.band_key, 'placeholder'::text
    from public.pricing_bands b
    where b.band_key = 'global_default';
end $$;


ALTER FUNCTION "public"."resolve_country_pricing"("p_country_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_court_price"("p_venue_id" "uuid", "p_court_id" "uuid" DEFAULT NULL::"uuid", "p_date" "date" DEFAULT CURRENT_DATE, "p_start_time" time without time zone DEFAULT NULL::time without time zone, "p_duration_minutes" integer DEFAULT 60, "p_play_type" "text" DEFAULT NULL::"text", "p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_dow             int;
  v_end_time        time;
  v_rule            record;
  v_price_pence     int;
  v_fallback        int;
  v_fallback_cur    text;
  v_member_discount int := 0;
  v_orig            int;
  -- Dynamic pricing
  v_dyn_enabled   boolean;
  v_dyn_threshold int;
  v_dyn_surcharge int;
  v_dyn_mult      numeric := 1.0;
  v_open          time;
  v_close         time;
  v_avail_min     int;
  v_booked_min    int;
begin
  -- 0. Member pricing hook
  if p_user_id is not null then
    select coalesce(max(discount_pct), 0) into v_member_discount
    from public.memberships
    where venue_id = p_venue_id and profile_id = p_user_id and status = 'active'
      and (expires_at is null or expires_at > now());
  end if;

  -- 0b. Dynamic (occupancy) surcharge multiplier — only when enabled AND a specific court is priced.
  select dynamic_pricing_enabled, dynamic_pricing_threshold_pct, dynamic_pricing_surcharge_pct
    into v_dyn_enabled, v_dyn_threshold, v_dyn_surcharge
  from public.padel_venues where venues_id = p_venue_id;

  if coalesce(v_dyn_enabled, false) and p_court_id is not null then
    select open_time, close_time into v_open, v_close
    from public.court_availability_settings where venue_id = p_venue_id limit 1;
    v_open  := coalesce(v_open,  '07:00'::time);
    v_close := coalesce(v_close, '23:00'::time);
    v_avail_min := greatest(0, (extract(epoch from (v_close - v_open)) / 60)::int);
    if v_close <= v_open then v_avail_min := (24*60) - (extract(epoch from (v_open - v_close))/60)::int; end if;

    select coalesce(sum(duration_minutes), 0)::int into v_booked_min
    from public.bookings
    where venue_id = p_venue_id and court_id = p_court_id
      and start_at::date = p_date and reservation_state = 'active'
      and purpose is distinct from 'blocked';

    if coalesce(v_avail_min, 0) > 0
       and (v_booked_min::numeric / v_avail_min) * 100 >= coalesce(v_dyn_threshold, 70) then
      v_dyn_mult := 1 + coalesce(v_dyn_surcharge, 0) / 100.0;
    end if;
  end if;

  v_dow := extract(dow from p_date)::int;
  if p_start_time is not null then
    v_end_time := p_start_time + (p_duration_minutes || ' minutes')::interval;
  else
    v_end_time := null;
  end if;

  -- 1. Find the best matching rule
  select r.id as rule_id, r.price_pence as rule_price_pence, r.price_basis, r.currency, r.priority,
    ( (r.court_id is not null)::int + (r.days_of_week is not null)::int + (r.start_time is not null)::int
    + (r.duration_minutes is not null)::int + (r.play_type is not null)::int ) as specificity
  into v_rule
  from public.pricing_rules r
  where r.venue_id = p_venue_id and r.active
    and (r.court_id is null or r.court_id = p_court_id)
    and (r.days_of_week is null or v_dow = any(r.days_of_week))
    and (r.start_time is null or (p_start_time is not null and p_start_time >= r.start_time and v_end_time <= r.end_time))
    and (r.duration_minutes is null or r.duration_minutes = p_duration_minutes)
    and (r.play_type is null or r.play_type = p_play_type)
  order by specificity desc, r.priority desc, r.created_at desc
  limit 1;

  -- 2. Price from matched rule
  if v_rule.rule_id is not null then
    if v_rule.price_basis = 'per_slot' then
      v_price_pence := v_rule.rule_price_pence;
    else
      v_price_pence := round(v_rule.rule_price_pence * p_duration_minutes / 60.0)::int;
    end if;
    v_price_pence := round(v_price_pence * v_dyn_mult)::int;   -- dynamic surcharge
    v_orig := v_price_pence;
    if v_member_discount > 0 then
      v_price_pence := round(v_price_pence * (100 - v_member_discount) / 100.0)::int;
    end if;
    return jsonb_build_object(
      'status','resolved','price_pence',v_price_pence,'currency',v_rule.currency,'rule_id',v_rule.rule_id,
      'basis',v_rule.price_basis,'member_discount_pct',v_member_discount,'original_price_pence',v_orig,
      'dynamic_surcharge_pct', case when v_dyn_mult > 1 then v_dyn_surcharge else 0 end,
      'breakdown', jsonb_build_object('rule_price_pence',v_rule.rule_price_pence,'basis',v_rule.price_basis,
        'duration_minutes',p_duration_minutes,'specificity',v_rule.specificity,'priority',v_rule.priority,
        'member_discount_pct',v_member_discount,'dynamic_surcharge_pct', case when v_dyn_mult > 1 then v_dyn_surcharge else 0 end));
  end if;

  -- 3. Fallback: padel_venues.price_per_hour
  select pv.price_per_hour, pv.currency into v_fallback, v_fallback_cur
  from public.padel_venues pv
  where pv.venues_id = p_venue_id and pv.price_per_hour is not null and pv.price_per_hour > 0
  limit 1;

  if v_fallback is not null then
    v_price_pence := round(v_fallback * p_duration_minutes / 60.0)::int;
    v_price_pence := round(v_price_pence * v_dyn_mult)::int;   -- dynamic surcharge
    v_orig := v_price_pence;
    if v_member_discount > 0 then
      v_price_pence := round(v_price_pence * (100 - v_member_discount) / 100.0)::int;
    end if;
    return jsonb_build_object(
      'status','fallback','price_pence',v_price_pence,'currency',coalesce(v_fallback_cur,'GBP'),'rule_id',null,
      'basis','per_hour','member_discount_pct',v_member_discount,'original_price_pence',v_orig,
      'dynamic_surcharge_pct', case when v_dyn_mult > 1 then v_dyn_surcharge else 0 end,
      'breakdown', jsonb_build_object('source','padel_venues.price_per_hour','base_price_pence',v_fallback,
        'duration_minutes',p_duration_minutes,'member_discount_pct',v_member_discount,
        'dynamic_surcharge_pct', case when v_dyn_mult > 1 then v_dyn_surcharge else 0 end));
  end if;

  -- 4. Not configured
  return jsonb_build_object('status','not_configured','price_pence',null,'currency',null,'rule_id',null,
    'basis',null,'member_discount_pct',0,
    'breakdown', jsonb_build_object('message','No pricing rule found and no padel_venues.price_per_hour set for this venue.'));
end;
$$;


ALTER FUNCTION "public"."resolve_court_price"("p_venue_id" "uuid", "p_court_id" "uuid", "p_date" "date", "p_start_time" time without time zone, "p_duration_minutes" integer, "p_play_type" "text", "p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_court_price"("p_venue_id" "uuid", "p_court_id" "uuid", "p_date" "date", "p_start_time" time without time zone, "p_duration_minutes" integer, "p_play_type" "text", "p_user_id" "uuid") IS 'Resolves the price for a court booking. Single source of truth.
   Returns jsonb { status, price_pence, currency, rule_id, basis, breakdown }.
   SECURITY DEFINER — reads pricing_rules (which players cannot access directly).';



CREATE OR REPLACE FUNCTION "public"."resolve_place"("p_query" "text") RETURNS TABLE("lat" double precision, "lng" double precision, "label" "text", "match_kind" "text", "match_count" integer)
    LANGUAGE "plpgsql" STABLE
    AS $$
declare
  v_raw   text := btrim(coalesce(p_query, ''));
  v_up    text := upper(btrim(coalesce(p_query, '')));
  v_alnum text := regexp_replace(upper(coalesce(p_query, '')), '[^A-Z0-9]', '', 'g');
begin
  if length(v_alnum) < 2 then
    return;
  end if;

  return query
  with matched as (
    select v.venue_id,
           v.latitude::double precision  as la,
           v.longitude::double precision as lo,
           v.city,
           v.postcode,
           v.postal_code,
           least(
             case when length(v_alnum) >= 5
                       and v_alnum in (
                         regexp_replace(upper(coalesce(v.postcode, '')), '[^A-Z0-9]', '', 'g'),
                         regexp_replace(upper(coalesce(v.postal_code, '')), '[^A-Z0-9]', '', 'g')
                       )
                  then 1 else 99 end,
             case when v_up in (
                         public.postcode_outcode(v.postcode),
                         public.postcode_outcode(v.postal_code)
                       )
                  then 2 else 99 end,
             case when upper(btrim(coalesce(v.city, ''))) = v_up then 3 else 99 end,
             case when public.postcode_outcode(v.postcode) like v_up || '%'
                    or public.postcode_outcode(v.postal_code) like v_up || '%'
                  then 4 else 99 end,
             case when upper(btrim(coalesce(v.city, ''))) like v_up || '%' then 5 else 99 end,
             case when upper(coalesce(v.full_address, '')) like '%' || v_up || '%' then 6 else 99 end
           ) as tier
      from public.padel_venues v
     where v.status = 'active'
       and v.latitude is not null
       and v.longitude is not null
  ),
  best as (
    select min(tier) as tier from matched where tier < 99
  ),
  hits as (
    select m.*
      from matched m
      join best b on m.tier = b.tier
  ),
  seed as (
    select la, lo from hits order by la, lo, venue_id limit 1
  ),
  clustered as (
    select h.*
      from hits h, seed s
     where public.haversine_miles(s.la, s.lo, h.la, h.lo) <= 50
  )
  select avg(c.la)::double precision,
         avg(c.lo)::double precision,
         case (select tier from best)
           when 1 then coalesce(max(c.postcode), v_raw)
           when 2 then v_up
           when 4 then v_up
           else coalesce(max(c.city), v_raw)
         end,
         case (select tier from best)
           when 1 then 'postcode'
           when 2 then 'outcode'
           when 3 then 'city'
           when 4 then 'outcode_prefix'
           when 5 then 'city_prefix'
           else 'address'
         end,
         count(*)::integer
    from clustered c
   having count(*) > 0;
end;
$$;


ALTER FUNCTION "public"."resolve_place"("p_query" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_place"("p_query" "text") IS 'Typed place ("BS1", "Bristol") -> a coordinate, from our own venue rows. No third-party geocoder.';



CREATE OR REPLACE FUNCTION "public"."respond_household_link"("p_request_id" "uuid", "p_accept" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller          uuid := auth.uid();
  v_req             record;
  v_caller_partner  uuid;
  v_req_partner     uuid;
  v_caller_name     text;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT * INTO v_req FROM household_link_requests
  WHERE id = p_request_id FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Request not found';
  END IF;
  IF v_req.target_id <> v_caller THEN
    RAISE EXCEPTION 'Only the invited partner can respond';
  END IF;
  IF v_req.status <> 'pending' THEN
    RAISE EXCEPTION 'Request already responded to';
  END IF;

  IF NOT p_accept THEN
    UPDATE household_link_requests
    SET status = 'declined', responded_at = now()
    WHERE id = p_request_id;

    -- Notify requester of decline
    SELECT name INTO v_caller_name FROM profiles WHERE id = v_caller;
    INSERT INTO notifications (user_id, type, title, message, related_id, read)
    VALUES (
      v_req.requester_id,
      'household_link_declined',
      'Household request declined',
      COALESCE(v_caller_name, 'A player') || ' declined your household link request.',
      v_caller,
      false
    );
    RETURN;
  END IF;

  -- Accept: re-validate neither party has since gained a partner
  SELECT household_partner_id INTO v_caller_partner FROM profiles WHERE id = v_caller;
  IF v_caller_partner IS NOT NULL THEN
    UPDATE household_link_requests SET status = 'declined', responded_at = now() WHERE id = p_request_id;
    RAISE EXCEPTION 'You already have a household partner — unlink first';
  END IF;

  SELECT household_partner_id INTO v_req_partner FROM profiles WHERE id = v_req.requester_id;
  IF v_req_partner IS NOT NULL THEN
    UPDATE household_link_requests SET status = 'declined', responded_at = now() WHERE id = p_request_id;
    RAISE EXCEPTION 'The requester already has a household partner';
  END IF;

  -- Link both profiles
  UPDATE profiles SET household_partner_id = v_req.requester_id WHERE id = v_caller;
  UPDATE profiles SET household_partner_id = v_caller WHERE id = v_req.requester_id;

  UPDATE household_link_requests
  SET status = 'accepted', responded_at = now()
  WHERE id = p_request_id;

  -- Expire any other pending requests involving either party
  UPDATE household_link_requests
  SET status = 'declined', responded_at = now()
  WHERE status = 'pending'
    AND id <> p_request_id
    AND (requester_id IN (v_caller, v_req.requester_id)
      OR target_id IN (v_caller, v_req.requester_id));

  -- Notify requester of acceptance
  SELECT name INTO v_caller_name FROM profiles WHERE id = v_caller;
  INSERT INTO notifications (user_id, type, title, message, related_id, read)
  VALUES (
    v_req.requester_id,
    'household_link_accepted',
    'Household partner linked!',
    COALESCE(v_caller_name, 'A player') || ' accepted your household link request.',
    v_caller,
    false
  );
END;
$$;


ALTER FUNCTION "public"."respond_household_link"("p_request_id" "uuid", "p_accept" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."respond_match_invitation"("p_match_id" "uuid", "p_accept" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  DECLARE                                                                                                       
    v_user_id uuid := auth.uid();                           
    v_invitation record;
    v_match record;
    v_invitee_name text;
    v_new_player_ids uuid[];                                                                                    
    v_will_be_full boolean;
    v_conflict record;                                                                                          
  BEGIN                                                     
    IF v_user_id IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
    SELECT * INTO v_invitation FROM match_invitations                                                           
    WHERE match_id = p_match_id AND invitee_id = v_user_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'No invitation found'; END IF;                                            
    IF v_invitation.status <> 'pending' THEN RAISE EXCEPTION 'Invitation already responded to'; END IF;
    IF v_invitation.expires_at <= now() THEN                                                                    
      UPDATE match_invitations SET status = 'expired' WHERE id = v_invitation.id;                               
      RAISE EXCEPTION 'Invitation has expired';                                                                 
    END IF;                                                                                                     
                                                            
    SELECT * INTO v_match FROM matches WHERE id = p_match_id FOR UPDATE;                                        
    SELECT name INTO v_invitee_name FROM profiles WHERE id = v_user_id;
    v_invitee_name := COALESCE(v_invitee_name, 'A player');                                                     
   
    -- Self-conflict check BEFORE updating invitation status (non-broadcast accept only)                        
    IF p_accept AND NOT v_invitation.is_broadcast THEN      
      IF v_user_id = ANY(COALESCE(v_match.player_ids, ARRAY[]::uuid[])) THEN                                    
        RETURN jsonb_build_object('success', true, 'accepted', true, 'auto_filled', false);                     
      END IF;                                                                                                   
      IF array_length(v_match.player_ids, 1) >= 4 THEN RAISE EXCEPTION 'Match is full'; END IF;                 
                                                                                                                
      SELECT * INTO v_conflict                              
      FROM check_self_conflict(v_user_id, v_match.match_date, v_match.match_time::time, p_match_id)             
      LIMIT 1;                                                                                                  
      IF FOUND THEN
        -- Invitation stays pending — no state change, just reject                                              
        RAISE EXCEPTION 'You already have a match scheduled at %. Can''t accept another.',                      
          COALESCE(to_char(v_conflict.conflicting_time, 'HH24:MI'), 'that time');
      END IF;                                                                                                   
    END IF;                                                 
                                                                                                                
    -- Only update invitation status after conflict check passes                                                
    UPDATE match_invitations
    SET status = CASE WHEN p_accept THEN 'accepted' ELSE 'declined' END, responded_at = now()                   
    WHERE id = v_invitation.id;                                                                                 
   
    IF p_accept AND NOT v_invitation.is_broadcast THEN                                                          
                                                            
      v_new_player_ids := COALESCE(v_match.player_ids, ARRAY[]::uuid[]) || v_user_id;                           
      v_will_be_full := array_length(v_new_player_ids, 1) >= 4;
                                                                                                                
      UPDATE matches                                        
      SET player_ids = v_new_player_ids,                                                                        
          is_open = CASE WHEN v_will_be_full THEN false ELSE is_open END,
          open_elo_min = CASE WHEN v_will_be_full THEN NULL ELSE open_elo_min END,
          open_elo_max = CASE WHEN v_will_be_full THEN NULL ELSE open_elo_max END,                              
          status = CASE WHEN v_will_be_full THEN 'scheduled' ELSE status END,
          updated_at = now()                                                                                    
      WHERE id = p_match_id;                                
                                                                                                                
      IF v_will_be_full THEN                                
        UPDATE ringer_requests SET status = 'filled_by_other', responded_at = now()
          WHERE match_id = p_match_id AND status = 'pending';                                                   
        UPDATE match_invitations SET status = 'filled_by_other', responded_at = now()
          WHERE match_id = p_match_id AND status = 'pending' AND invitee_id <> v_user_id;                       
      END IF;                                                                                                   
                                                                                                                
      INSERT INTO notifications (user_id, type, title, message, related_id)                                     
      SELECT unnest(v_match.player_ids), 'invitee_joined',  
        v_invitee_name || ' joined your match',                                                                 
        v_invitee_name || ' has accepted the invitation and joined.', p_match_id;
                                                                                                                
      RETURN jsonb_build_object('success', true, 'accepted', true, 'auto_filled', true);
    END IF;                                                                                                     
                                                            
    IF p_accept AND v_invitation.is_broadcast THEN                                                              
      INSERT INTO notifications (user_id, type, title, message, related_id)
      VALUES (v_invitation.invited_by, 'invitation_accepted',                                                   
        v_invitee_name || ' is available',                                                                      
        v_invitee_name || ' accepted your match invitation. Tap to confirm them.',
        p_match_id);                                                                                            
      RETURN jsonb_build_object('success', true, 'accepted', true, 'auto_filled', false);
    END IF;                                                                                                     
                                                            
    INSERT INTO notifications (user_id, type, title, message, related_id)                                       
    VALUES (v_invitation.invited_by, 'invitation_declined', 
      v_invitee_name || ' can''t play',                                                                         
      v_invitee_name || ' isn''t available.', p_match_id);
                                                                                                                
    RETURN jsonb_build_object('success', true, 'accepted', false, 'auto_filled', false);
  END;                                                                                                          
  $$;


ALTER FUNCTION "public"."respond_match_invitation"("p_match_id" "uuid", "p_accept" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."respond_ringer_request"("p_match_id" "uuid", "p_accept" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_request record;
  v_ringer_name text;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  SELECT * INTO v_request FROM ringer_requests WHERE match_id = p_match_id AND ringer_id = v_user_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'No request found'; END IF;
  IF v_request.status <> 'pending' THEN RAISE EXCEPTION 'Request already responded to'; END IF;
  IF v_request.expires_at <= now() THEN
    UPDATE ringer_requests SET status = 'expired' WHERE id = v_request.id;
    RAISE EXCEPTION 'Request has expired';
  END IF;
  UPDATE ringer_requests
  SET status = CASE WHEN p_accept THEN 'accepted' ELSE 'declined' END,
      responded_at = now()
  WHERE id = v_request.id;
  SELECT name INTO v_ringer_name FROM profiles WHERE id = v_user_id;
  v_ringer_name := COALESCE(v_ringer_name, 'A ringer');
  INSERT INTO notifications (user_id, type, title, message, related_id)
  VALUES (v_request.requested_by,
    CASE WHEN p_accept THEN 'ringer_accepted' ELSE 'ringer_declined' END,
    CASE WHEN p_accept THEN v_ringer_name || ' is available' ELSE v_ringer_name || ' can''t play' END,
    CASE WHEN p_accept
      THEN v_ringer_name || ' has accepted your ringer request. Tap to confirm them for the match.'
      ELSE v_ringer_name || ' isn''t available. Try another ringer.'
    END,
    p_match_id);
  RETURN jsonb_build_object('success', true, 'accepted', p_accept);
END;
$$;


ALTER FUNCTION "public"."respond_ringer_request"("p_match_id" "uuid", "p_accept" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."revert_open_match"("p_match_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_match record;
  v_is_player boolean := false;
  v_is_admin boolean := false;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;

  SELECT * INTO v_match FROM matches WHERE id = p_match_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Match not found'; END IF;
  IF NOT v_match.is_open THEN RAISE EXCEPTION 'Match is not open'; END IF;

  v_is_player := v_user_id = ANY(COALESCE(v_match.player_ids, ARRAY[]::uuid[]));
  IF NOT v_is_player AND v_match.group_id IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1 FROM group_members
      WHERE group_id = v_match.group_id AND user_id = v_user_id AND role = 'admin'
    ) INTO v_is_admin;
  END IF;

  IF NOT v_is_player AND NOT v_is_admin THEN
    RAISE EXCEPTION 'Only match players or group admins can revert';
  END IF;

  UPDATE matches
  SET is_open = false, open_elo_min = NULL, open_elo_max = NULL,
      opened_by = NULL, opened_at = NULL, updated_at = now()
  WHERE id = p_match_id;

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."revert_open_match"("p_match_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_venue_onboarding"("p_venue_id" "uuid", "p_offers_coaching" boolean, "p_current_provider" "text", "p_needs" "text"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  if not exists (
    select 1 from public.venue_users vu
    where vu.venue_id = p_venue_id and vu.user_id = v_uid and vu.status = 'active'
  ) then
    raise exception 'not_authorised';
  end if;

  insert into public.venue_onboarding (venue_id, offers_coaching, current_provider, needs, updated_at)
  values (
    p_venue_id,
    p_offers_coaching,
    nullif(btrim(coalesce(p_current_provider, '')), ''),
    coalesce(p_needs, '{}'),
    now()
  )
  on conflict (venue_id) do update set
    offers_coaching  = excluded.offers_coaching,
    current_provider = excluded.current_provider,
    needs            = excluded.needs,
    updated_at       = now();
end
$$;


ALTER FUNCTION "public"."save_venue_onboarding"("p_venue_id" "uuid", "p_offers_coaching" boolean, "p_current_provider" "text", "p_needs" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_claimable_venues"("p_query" "text") RETURNS TABLE("venue_id" "uuid", "venues_id" "uuid", "venue_name" "text", "city" "text", "country" "text", "full_address" "text", "postcode" "text", "website" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select v.venue_id, v.venues_id, v.venue_name, v.city,
         v.country,
         v.full_address, v.postcode, v.website
  from public.padel_venues v
  where v.status = 'active'
    and char_length(btrim(coalesce(p_query, ''))) >= 2
    and (
      v.venue_name  ilike '%' || p_query || '%'
      or v.city         ilike '%' || p_query || '%'
      or v.postcode     ilike '%' || p_query || '%'
      or v.full_address ilike '%' || p_query || '%'
    )
  order by v.venue_name
  limit 10;
$$;


ALTER FUNCTION "public"."search_claimable_venues"("p_query" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."self_report_booking"("p_match_id" "uuid", "p_venue_id" "uuid", "p_venue_name" "text", "p_court_number" integer DEFAULT NULL::integer, "p_booking_reference" "text" DEFAULT NULL::"text", "p_total_cost_pence" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_match record;
  v_per_player_pence integer;
  v_player_count integer;
  v_user_name text;
  v_padel_venue_id uuid;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT * INTO v_match FROM matches WHERE id = p_match_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Match not found';
  END IF;

  IF NOT (v_user_id = ANY(COALESCE(v_match.player_ids, ARRAY[]::uuid[]))) THEN
    RAISE EXCEPTION 'You must be a player in this match to report a booking';
  END IF;

  IF v_match.booking_status = 'booked' THEN
    RAISE EXCEPTION 'This match is already booked';
  END IF;

  -- Resolve the venue to one directory row, accepting either id space.
  IF p_venue_id IS NOT NULL THEN
    SELECT pv.venue_id INTO v_padel_venue_id
    FROM padel_venues pv WHERE pv.venue_id = p_venue_id;

    IF v_padel_venue_id IS NULL THEN
      SELECT pv.venue_id INTO v_padel_venue_id
      FROM padel_venues pv WHERE pv.venues_id = p_venue_id;
    END IF;

    IF v_padel_venue_id IS NULL THEN
      RAISE EXCEPTION 'unknown_venue';
    END IF;
  END IF;

  v_player_count := COALESCE(array_length(v_match.player_ids, 1), 4);
  IF p_total_cost_pence IS NOT NULL AND v_player_count > 0 THEN
    v_per_player_pence := p_total_cost_pence / v_player_count;
  ELSE
    v_per_player_pence := NULL;
  END IF;

  UPDATE matches SET
    booked_venue_name   = p_venue_name,
    padel_venue_id      = v_padel_venue_id,
    booked_court_number = p_court_number,
    booking_reference   = p_booking_reference,
    booked_at           = now(),
    booked_by           = v_user_id,
    booking_status      = 'booked',
    updated_at          = now()
  WHERE id = p_match_id;

  SELECT name INTO v_user_name FROM profiles WHERE id = v_user_id;
  v_user_name := COALESCE(v_user_name, 'A player');

  INSERT INTO notifications (user_id, type, title, message, related_id)
  SELECT
    unnest(array_remove(v_match.player_ids, v_user_id)),
    'court_booked',
    'Court booked',
    v_user_name || ' has booked a court at ' || p_venue_name ||
      CASE WHEN p_booking_reference IS NOT NULL
           THEN ' (ref: ' || p_booking_reference || ')'
           ELSE '' END,
    p_match_id;

  RETURN jsonb_build_object(
    'success', true,
    'per_player_pence', v_per_player_pence,
    'total_pence', p_total_cost_pence
  );
END;
$$;


ALTER FUNCTION "public"."self_report_booking"("p_match_id" "uuid", "p_venue_id" "uuid", "p_venue_name" "text", "p_court_number" integer, "p_booking_reference" "text", "p_total_cost_pence" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_deadline_approaching_alerts"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_match record;
  v_match_time timestamptz;
  v_user_ids uuid[];
BEGIN
  FOR v_match IN
    SELECT m.id, m.match_date, m.match_time, m.player_ids
    FROM matches m
    WHERE m.status IN ('scheduled', 'confirmed', 'pending', 'open')
      AND m.push_deadline_sent IS NOT TRUE
      AND NOT EXISTS (SELECT 1 FROM match_results mr WHERE mr.match_id = m.id)
  LOOP
    v_match_time := (v_match.match_date::timestamp +
      COALESCE(v_match.match_time::time, '00:00:00'::time));

    IF v_match_time + INTERVAL '23 hours' < NOW()
       AND v_match_time + INTERVAL '24 hours' > NOW() THEN

      SELECT ARRAY(
        SELECT p.id FROM profiles p WHERE p.id = ANY(v_match.player_ids)
      ) INTO v_user_ids;

      IF array_length(v_user_ids, 1) > 0 THEN
        INSERT INTO notifications (user_id, type, title, message, related_id, read)
        SELECT unnest(v_user_ids), 'match_deadline_approaching',
               'Result entry closes in 1 hour',
               'Tap to record your result before it auto-cancels.',
               v_match.id, false;
      END IF;

      UPDATE matches SET push_deadline_sent = true WHERE id = v_match.id;
    END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."send_deadline_approaching_alerts"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_match_invitation_notification"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  match_record RECORD;
  inviter_record RECORD;
BEGIN
  -- Get match details
  SELECT * INTO match_record
  FROM matches
  WHERE id = NEW.match_id;
  
  -- Get inviter details
  SELECT name INTO inviter_record
  FROM profiles
  WHERE id = NEW.invited_by;
  
  -- Send notification
  INSERT INTO notifications (
    user_id,
    type,
    title,
    message,
    related_id
  )
  VALUES (
    NEW.player_id,
    'match_invitation',
    'Match Invitation',
    format('%s invited you to play on %s at %s',
      inviter_record.name,
      to_char(match_record.match_date, 'Mon DD'),
      match_record.match_time
    ),
    NEW.match_id
  );
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."send_match_invitation_notification"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_match_invitations"("p_match_id" "uuid", "p_invitee_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_match record;
  v_is_player boolean := false;
  v_is_admin boolean := false;
  v_expires_at timestamptz;
  v_requester_name text;
  v_sent_count integer := 0;
  v_is_broadcast boolean;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  SELECT * INTO v_match FROM matches WHERE id = p_match_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Match not found'; END IF;
  IF array_length(p_invitee_ids, 1) IS NULL THEN RAISE EXCEPTION 'No invitees'; END IF;

  v_is_broadcast := array_length(p_invitee_ids, 1) > 1;
  v_is_player := v_user_id = ANY(COALESCE(v_match.player_ids, ARRAY[]::uuid[]));
  IF NOT v_is_player AND v_match.group_id IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1 FROM group_members
      WHERE group_id = v_match.group_id AND user_id = v_user_id AND role = 'admin'
    ) INTO v_is_admin;
  END IF;
  IF NOT v_is_player AND NOT v_is_admin THEN
    RAISE EXCEPTION 'Only match players or group admins can invite';
  END IF;

  v_expires_at := (v_match.match_date::timestamp + COALESCE(v_match.match_time, '00:00')::time) - INTERVAL '24 hours';
  IF v_expires_at <= now() THEN RAISE EXCEPTION 'Too late to send invitations'; END IF;

  IF EXISTS (
    SELECT 1 FROM unnest(p_invitee_ids) AS iid
    WHERE iid = ANY(COALESCE(v_match.player_ids, ARRAY[]::uuid[]))
  ) THEN
    RAISE EXCEPTION 'One or more invitees are already in the match';
  END IF;

  SELECT name INTO v_requester_name FROM profiles WHERE id = v_user_id;
  v_requester_name := COALESCE(v_requester_name, 'A player');

  INSERT INTO match_invitations (match_id, invitee_id, invited_by, is_broadcast, expires_at)
  SELECT p_match_id, unnest(p_invitee_ids), v_user_id, v_is_broadcast, v_expires_at
  ON CONFLICT (match_id, invitee_id) DO NOTHING;
  GET DIAGNOSTICS v_sent_count = ROW_COUNT;

  INSERT INTO notifications (user_id, type, title, message, related_id)
  SELECT unnest(p_invitee_ids), 'match_invitation', 'Match invitation',
    v_requester_name || ' invited you to play in a match. Tap to see details.',
    p_match_id;

  RETURN jsonb_build_object('success', true, 'sent', v_sent_count, 'is_broadcast', v_is_broadcast, 'expires_at', v_expires_at);
END;
$$;


ALTER FUNCTION "public"."send_match_invitations"("p_match_id" "uuid", "p_invitee_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_match_reminders"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_match record;
  v_match_time timestamptz;
  v_user_ids uuid[];
  v_messages text[] := ARRAY[
    'It''s Bandeja time in 1 hour 🎾',
    'Not long now — get ready 🎾',
    'Padel therapy session with Dr Court booked in 1 hour 💊',
    'Get ready to show your mates how bad you are at padel again — 1 hour to go 😅',
    '🚨 PADEL TIME! Get off your backside. 60 minutes to find your racket and your dignity. Don''t be late.',
    '🕒 1 HOUR WARNING: if you''re late, you''re buying the post-match beers. Move it! 🍻',
    '⚠️ Your couch privileges have expired. Padel in 1 hour. Grab your gear! 🎒🎾',
    'In exactly 1 hour you''ll remember how bad your cardio actually is. See you on court! 🏃💨',
    '🔮 Prediction: in 60 mins you''ll smash one into the glass and blame the wind. Wear your trainers! 👟',
    '📱 Your 1-hour warning to start practising your excuses for that missed smash 🎾',
    '💊 Your hourly dose of hitting a yellow ball against a wall starts in 60 minutes 🧠',
    '🏆 1 hour until we step on court and play like absolute pros (in our own minds) 🌟'
  ];
  v_msg text;
BEGIN
  FOR v_match IN
    SELECT m.id, m.match_date, m.match_time, m.player_ids
    FROM matches m
    WHERE m.status IN ('scheduled', 'confirmed')
      AND m.push_reminder_sent IS NOT TRUE
      AND array_length(m.player_ids, 1) > 0
  LOOP
    v_match_time := (v_match.match_date::timestamp
      + COALESCE(v_match.match_time::time, '00:00:00'::time)) AT TIME ZONE 'Europe/London';

    IF NOW() >= v_match_time - INTERVAL '60 minutes'
       AND NOW() < v_match_time THEN

      SELECT ARRAY(
        SELECT p.id FROM profiles p WHERE p.id = ANY(v_match.player_ids)
      ) INTO v_user_ids;

      IF array_length(v_user_ids, 1) > 0 THEN
        v_msg := v_messages[1 + floor(random() * array_length(v_messages, 1))::int];

        INSERT INTO notifications (user_id, type, title, message, related_id, read)
        SELECT unnest(v_user_ids), 'match_reminder',
               '🎾 Padel time!',
               v_msg,
               v_match.id, false;
      END IF;

      UPDATE matches SET push_reminder_sent = true WHERE id = v_match.id;
    END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."send_match_reminders"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_match_result_prompts"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_match         record;
  v_match_time    timestamptz;
  v_user_ids      uuid[];
  v_duration_mins int;
BEGIN
  FOR v_match IN
    SELECT m.id,
           m.match_date,
           m.match_time,
           m.player_ids,
           COALESCE(m.duration_minutes, b.duration_minutes, 90) AS duration_minutes
    FROM matches m
    LEFT JOIN bookings b ON b.match_id = m.id
    WHERE m.status IN ('scheduled', 'confirmed')
      AND m.push_result_prompt_sent IS NOT TRUE
      AND NOT EXISTS (SELECT 1 FROM match_results mr WHERE mr.match_id = m.id)
  LOOP
    v_match_time := (v_match.match_date::timestamp
      + COALESCE(v_match.match_time::time, '00:00:00'::time)) AT TIME ZONE 'Europe/London';

    v_duration_mins := v_match.duration_minutes;

    IF v_match_time + (v_duration_mins || ' minutes')::interval + INTERVAL '15 minutes' < NOW()
       AND v_match_time + INTERVAL '24 hours' > NOW() THEN

      v_user_ids := public.notifiable_players(v_match.player_ids);

      IF array_length(v_user_ids, 1) > 0 THEN
        INSERT INTO notifications (user_id, type, title, message, related_id, read)
        SELECT unnest(v_user_ids), 'match_result_prompt',
               'How did your match go?',
               'Tap to enter your result.',
               v_match.id, false;
      END IF;

      UPDATE matches SET push_result_prompt_sent = true WHERE id = v_match.id;
    END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."send_match_result_prompts"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_ringer_requests"("p_match_id" "uuid", "p_ringer_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_match record;
  v_is_admin boolean := false;
  v_is_player boolean := false;
  v_expires_at timestamptz;
  v_requester_name text;
  v_sent_count integer := 0;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  SELECT * INTO v_match FROM matches WHERE id = p_match_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Match not found'; END IF;
  v_is_player := v_user_id = ANY(COALESCE(v_match.player_ids, ARRAY[]::uuid[]));
  IF NOT v_is_player AND v_match.group_id IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1 FROM group_members
      WHERE group_id = v_match.group_id AND user_id = v_user_id AND role = 'admin'
    ) INTO v_is_admin;
  END IF;
  IF NOT v_is_player AND NOT v_is_admin THEN
    RAISE EXCEPTION 'Only match players or group admins can send ringer requests';
  END IF;
  v_expires_at := (v_match.match_date::timestamp + COALESCE(v_match.match_time, '00:00')::time) - INTERVAL '24 hours';
  IF v_expires_at <= now() THEN RAISE EXCEPTION 'Too late to send ringer requests for this match'; END IF;
  SELECT name INTO v_requester_name FROM profiles WHERE id = v_user_id;
  v_requester_name := COALESCE(v_requester_name, 'A player');
  INSERT INTO ringer_requests (match_id, ringer_id, requested_by, expires_at)
  SELECT p_match_id, unnest(p_ringer_ids), v_user_id, v_expires_at
  ON CONFLICT (match_id, ringer_id) DO NOTHING;
  GET DIAGNOSTICS v_sent_count = ROW_COUNT;
  INSERT INTO notifications (user_id, type, title, message, related_id)
  SELECT unnest(p_ringer_ids), 'ringer_request', 'Can you play?',
    v_requester_name || ' is asking if you can fill in for a match. Tap to see details.',
    p_match_id;
  RETURN jsonb_build_object('success', true, 'sent', v_sent_count, 'expires_at', v_expires_at);
END;
$$;


ALTER FUNCTION "public"."send_ringer_requests"("p_match_id" "uuid", "p_ringer_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_jersey_reason_value"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.reason ~ '\d' THEN
    NEW.reason_value := NULLIF(regexp_replace(NEW.reason, '\D', '', 'g'), '')::integer;
  ELSE
    NEW.reason_value := NULL;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."set_jersey_reason_value"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_teammate_role"("p_venue_id" "uuid", "p_user_id" "uuid", "p_role" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_owner_count int;
begin
  if not public._is_active_owner(p_venue_id) then
    return jsonb_build_object('status','not_authorised');
  end if;
  if p_role not in ('owner','manager','staff','coach') then
    return jsonb_build_object('status','bad_role');
  end if;
  select count(*) into v_owner_count from public.venue_users
    where venue_id = p_venue_id and role = 'owner' and status = 'active';
  if p_role <> 'owner' and v_owner_count <= 1
     and exists (select 1 from public.venue_users
                 where venue_id = p_venue_id and user_id = p_user_id
                   and role = 'owner' and status = 'active') then
    return jsonb_build_object('status','last_owner');
  end if;
  update public.venue_users set role = p_role
    where venue_id = p_venue_id and user_id = p_user_id and status = 'active';
  return jsonb_build_object('status','updated');
end;
$$;


ALTER FUNCTION "public"."set_teammate_role"("p_venue_id" "uuid", "p_user_id" "uuid", "p_role" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_venue_commission"("p_venue_id" "uuid", "p_rate_bps" integer DEFAULT NULL::integer, "p_tier" "text" DEFAULT NULL::"text", "p_founding" boolean DEFAULT NULL::boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_row public.venues;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  if not exists (select 1 from public.platform_admins where user_id = v_uid) then
    raise exception 'not_authorised';
  end if;
  if p_rate_bps is not null and (p_rate_bps < 0 or p_rate_bps > 1000) then
    raise exception 'rate_out_of_range';
  end if;
  if p_tier is not null and p_tier not in ('core','plus','pro') then
    raise exception 'invalid_tier';
  end if;
  update public.venues set
    commission_rate_bps = coalesce(p_rate_bps, commission_rate_bps),
    plan_tier           = coalesce(p_tier, plan_tier),
    is_founding_venue   = coalesce(p_founding, is_founding_venue)
  where id = p_venue_id
  returning * into v_row;
  if not found then raise exception 'venue_not_found'; end if;
  return jsonb_build_object(
    'venue_id', v_row.id,
    'commission_rate_bps', v_row.commission_rate_bps,
    'plan_tier', v_row.plan_tier,
    'is_founding_venue', v_row.is_founding_venue
  );
end
$$;


ALTER FUNCTION "public"."set_venue_commission"("p_venue_id" "uuid", "p_rate_bps" integer, "p_tier" "text", "p_founding" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_venue_deal"("p_venue_id" "uuid", "p_rate_bps" integer DEFAULT NULL::integer, "p_tier" "text" DEFAULT NULL::"text", "p_founding" boolean DEFAULT NULL::boolean, "p_free_until" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_monthly_price_pence" integer DEFAULT NULL::integer, "p_deal_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_uid uuid := auth.uid(); v_row public.venues;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  if not exists (select 1 from public.platform_admins where user_id = v_uid) then raise exception 'not_authorised'; end if;
  if p_rate_bps is not null and (p_rate_bps < 0 or p_rate_bps > 1000) then raise exception 'rate_out_of_range'; end if;
  if p_tier is not null and p_tier not in ('core','plus','pro') then raise exception 'invalid_tier'; end if;
  update public.venues set
    commission_rate_bps     = coalesce(p_rate_bps, commission_rate_bps),
    plan_tier               = coalesce(p_tier, plan_tier),
    is_founding_venue       = coalesce(p_founding, is_founding_venue),
    subscription_free_until = p_free_until,
    monthly_price_pence     = p_monthly_price_pence,
    deal_notes              = p_deal_notes
  where id = p_venue_id returning * into v_row;
  if not found then raise exception 'venue_not_found'; end if;
  return jsonb_build_object(
    'venue_id', v_row.id, 'commission_rate_bps', v_row.commission_rate_bps,
    'plan_tier', v_row.plan_tier, 'is_founding_venue', v_row.is_founding_venue,
    'subscription_free_until', v_row.subscription_free_until, 'monthly_price_pence', v_row.monthly_price_pence);
end $$;


ALTER FUNCTION "public"."set_venue_deal"("p_venue_id" "uuid", "p_rate_bps" integer, "p_tier" "text", "p_founding" boolean, "p_free_until" timestamp with time zone, "p_monthly_price_pence" integer, "p_deal_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sorted_player_key"("ids" "uuid"[]) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE STRICT PARALLEL SAFE
    AS $$
  SELECT array_to_string(
           (SELECT array_agg(u ORDER BY u) FROM unnest(ids) AS u),
           ','
         );
$$;


ALTER FUNCTION "public"."sorted_player_key"("ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."switch_teams"("p_match_id" "uuid", "p_team1" "uuid"[], "p_team2" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_match record;
  v_is_admin boolean := false;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT * INTO v_match FROM matches WHERE id = p_match_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Match not found';
  END IF;

  IF NOT (v_user_id = ANY(COALESCE(v_match.player_ids, ARRAY[]::uuid[]))) THEN
    IF v_match.group_id IS NOT NULL THEN
      SELECT EXISTS (
        SELECT 1 FROM group_members
        WHERE group_id = v_match.group_id
          AND user_id = v_user_id
          AND role = 'admin'
      ) INTO v_is_admin;
    END IF;
    IF NOT v_is_admin THEN
      RAISE EXCEPTION 'You do not have permission to switch teams on this match';
    END IF;
  END IF;

  IF COALESCE(array_length(p_team1, 1), 0) <> 2 OR COALESCE(array_length(p_team2, 1), 0) <> 2 THEN
    RAISE EXCEPTION 'Each team must have exactly 2 players';
  END IF;

  UPDATE matches SET
    team1_player_ids = p_team1,
    team2_player_ids = p_team2,
    updated_at = now()
  WHERE id = p_match_id;

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."switch_teams"("p_match_id" "uuid", "p_team1" "uuid"[], "p_team2" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_booking_axes"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_in_app boolean;
BEGIN
  -- Only derive from status when status is the driver: INSERT, or an UPDATE that
  -- actually changed status. This lets future axes-native writers set the axes
  -- directly without this trigger reverting them.
  IF TG_OP = 'UPDATE' AND NEW.status IS NOT DISTINCT FROM OLD.status THEN
    RETURN NEW;
  END IF;

  -- reservation_state: does this booking occupy the slot? (availability reads this)
  NEW.reservation_state := CASE
    WHEN NEW.status IN ('cancelled','released') THEN 'cancelled'
    WHEN NEW.status IN ('completed','no_show')  THEN 'completed'
    ELSE 'active'
  END;

  -- in-app if explicitly tagged, or (pre-migration) a Stripe PI is present.
  v_in_app := (NEW.source = 'in_app')
              OR (NEW.source IS NULL AND NEW.booker_stripe_pi_id IS NOT NULL);

  IF NOT v_in_app THEN
    NEW.payment_state := NULL;
  ELSE
    NEW.payment_state := CASE
      WHEN NEW.status IN ('held','payment_pending')  THEN 'held'
      WHEN NEW.status IN ('confirmed','completed')    THEN 'paid'
      WHEN NEW.status = 'released'                     THEN 'released'
      WHEN NEW.status = 'cancelled' THEN (
        CASE
          WHEN EXISTS (SELECT 1 FROM booking_payments bp
                       WHERE bp.booking_id = NEW.id AND bp.status = 'refunded') THEN 'refunded'
          WHEN EXISTS (SELECT 1 FROM booking_payments bp
                       WHERE bp.booking_id = NEW.id AND bp.status = 'paid')     THEN 'paid'
          ELSE NULL
        END
      )
      ELSE NULL
    END;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_booking_axes"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_venue_court_counts"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_anchor uuid := coalesce(NEW.venue_id, OLD.venue_id);
begin
  update public.padel_venues pv
  set indoor_courts    = sub.ind,
      outdoor_courts   = sub.outd,
      number_of_courts = sub.tot
  from (
    select
      count(*) filter (where status = 'active' and is_indoor is true)  as ind,
      count(*) filter (where status = 'active' and is_indoor is false) as outd,
      count(*) filter (where status = 'active')                        as tot
    from public.courts
    where venue_id = v_anchor
  ) sub
  where pv.venues_id = v_anchor;
  return null;
end;
$$;


ALTER FUNCTION "public"."sync_venue_court_counts"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_venue_rating_aggregates"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_venue_id uuid;
  v_avg numeric;
  v_count integer;
begin
  v_venue_id := coalesce(NEW.venue_id, OLD.venue_id);
  select round(avg(rating)::numeric, 2), count(*)
    into v_avg, v_count
    from public.venue_ratings
   where venue_id = v_venue_id;
  update public.padel_venues
     set rating = case when v_count > 0 then v_avg else null end,
         review_count = case when v_count > 0 then v_count else 0 end
   where venue_id = v_venue_id;
  return null;
end;
$$;


ALTER FUNCTION "public"."sync_venue_rating_aggregates"() OWNER TO "postgres";


