CREATE OR REPLACE FUNCTION "public"."trigger_peer_vote_badges_on_verify"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_player_ids uuid[];
BEGIN
  IF NEW.verification_status = 'verified'
     AND (OLD.verification_status IS NULL OR OLD.verification_status <> 'verified')
  THEN
    BEGIN
      v_player_ids := COALESCE(NEW.team1_players, '{}') || COALESCE(NEW.team2_players, '{}');
      IF array_length(v_player_ids, 1) > 0 THEN
        PERFORM award_peer_vote_badges(v_player_ids);
      END IF;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING '[peer-vote-badges] failed for match_result %: %', NEW.id, SQLERRM;
    END;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trigger_peer_vote_badges_on_verify"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unlink_household_partner"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller   uuid := auth.uid();
  v_partner  uuid;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT household_partner_id INTO v_partner
  FROM profiles WHERE id = v_caller;

  UPDATE profiles SET household_partner_id = NULL WHERE id = v_caller;

  IF v_partner IS NOT NULL THEN
    UPDATE profiles SET household_partner_id = NULL WHERE id = v_partner;
  END IF;
END;
$$;


ALTER FUNCTION "public"."unlink_household_partner"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_leaderboard_from_match"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  match_record RECORD;
  team1_won BOOLEAN;
  v_player_id UUID;
  v_group_id UUID;
BEGIN
  SELECT m.*, m.group_id INTO match_record
  FROM matches m
  WHERE m.id = NEW.match_id;
  
  v_group_id := match_record.group_id;
  
  IF NEW.verification_status != 'verified' THEN
    RETURN NEW;
  END IF;
  
  team1_won := NEW.team1_score > NEW.team2_score;
  
  FOREACH v_player_id IN ARRAY NEW.team1_players
  LOOP
    INSERT INTO leaderboard_entries (
      group_id, player_id, partner_id, is_pair,
      wins, losses, total_matches, points_for, points_against, win_rate
    )
    VALUES (
      v_group_id, v_player_id, NULL, false,
      CASE WHEN team1_won THEN 1 ELSE 0 END,
      CASE WHEN team1_won THEN 0 ELSE 1 END,
      1, NEW.team1_score, NEW.team2_score,
      CASE WHEN team1_won THEN 100.00 ELSE 0.00 END
    )
    ON CONFLICT (group_id, player_id, is_pair) WHERE partner_id IS NULL
    DO UPDATE SET
      wins = leaderboard_entries.wins + CASE WHEN team1_won THEN 1 ELSE 0 END,
      losses = leaderboard_entries.losses + CASE WHEN team1_won THEN 0 ELSE 1 END,
      total_matches = leaderboard_entries.total_matches + 1,
      points_for = leaderboard_entries.points_for + NEW.team1_score,
      points_against = leaderboard_entries.points_against + NEW.team2_score,
      win_rate = ROUND((leaderboard_entries.wins + CASE WHEN team1_won THEN 1 ELSE 0 END)::DECIMAL / (leaderboard_entries.total_matches + 1) * 100, 2),
      updated_at = NOW();
  END LOOP;
  
  FOREACH v_player_id IN ARRAY NEW.team2_players
  LOOP
    INSERT INTO leaderboard_entries (
      group_id, player_id, partner_id, is_pair,
      wins, losses, total_matches, points_for, points_against, win_rate
    )
    VALUES (
      v_group_id, v_player_id, NULL, false,
      CASE WHEN NOT team1_won THEN 1 ELSE 0 END,
      CASE WHEN NOT team1_won THEN 0 ELSE 1 END,
      1, NEW.team2_score, NEW.team1_score,
      CASE WHEN NOT team1_won THEN 100.00 ELSE 0.00 END
    )
    ON CONFLICT (group_id, player_id, is_pair) WHERE partner_id IS NULL
    DO UPDATE SET
      wins = leaderboard_entries.wins + CASE WHEN NOT team1_won THEN 1 ELSE 0 END,
      losses = leaderboard_entries.losses + CASE WHEN NOT team1_won THEN 0 ELSE 1 END,
      total_matches = leaderboard_entries.total_matches + 1,
      points_for = leaderboard_entries.points_for + NEW.team2_score,
      points_against = leaderboard_entries.points_against + NEW.team1_score,
      win_rate = ROUND((leaderboard_entries.wins + CASE WHEN NOT team1_won THEN 1 ELSE 0 END)::DECIMAL / (leaderboard_entries.total_matches + 1) * 100, 2),
      updated_at = NOW();
  END LOOP;
  
  IF array_length(NEW.team1_players, 1) = 2 THEN
    INSERT INTO leaderboard_entries (
      group_id, player_id, partner_id, is_pair,
      wins, losses, total_matches, points_for, points_against, win_rate
    )
    VALUES (
      v_group_id,
      LEAST(NEW.team1_players[1], NEW.team1_players[2]),
      GREATEST(NEW.team1_players[1], NEW.team1_players[2]),
      true,
      CASE WHEN team1_won THEN 1 ELSE 0 END,
      CASE WHEN team1_won THEN 0 ELSE 1 END,
      1, NEW.team1_score, NEW.team2_score,
      CASE WHEN team1_won THEN 100.00 ELSE 0.00 END
    )
    ON CONFLICT (group_id, player_id, partner_id, is_pair)
    DO UPDATE SET
      wins = leaderboard_entries.wins + CASE WHEN team1_won THEN 1 ELSE 0 END,
      losses = leaderboard_entries.losses + CASE WHEN team1_won THEN 0 ELSE 1 END,
      total_matches = leaderboard_entries.total_matches + 1,
      points_for = leaderboard_entries.points_for + NEW.team1_score,
      points_against = leaderboard_entries.points_against + NEW.team2_score,
      win_rate = ROUND((leaderboard_entries.wins + CASE WHEN team1_won THEN 1 ELSE 0 END)::DECIMAL / (leaderboard_entries.total_matches + 1) * 100, 2),
      updated_at = NOW();
    
    INSERT INTO leaderboard_entries (
      group_id, player_id, partner_id, is_pair,
      wins, losses, total_matches, points_for, points_against, win_rate
    )
    VALUES (
      v_group_id,
      LEAST(NEW.team2_players[1], NEW.team2_players[2]),
      GREATEST(NEW.team2_players[1], NEW.team2_players[2]),
      true,
      CASE WHEN NOT team1_won THEN 1 ELSE 0 END,
      CASE WHEN NOT team1_won THEN 0 ELSE 1 END,
      1, NEW.team2_score, NEW.team1_score,
      CASE WHEN NOT team1_won THEN 100.00 ELSE 0.00 END
    )
    ON CONFLICT (group_id, player_id, partner_id, is_pair)
    DO UPDATE SET
      wins = leaderboard_entries.wins + CASE WHEN NOT team1_won THEN 1 ELSE 0 END,
      losses = leaderboard_entries.losses + CASE WHEN NOT team1_won THEN 0 ELSE 1 END,
      total_matches = leaderboard_entries.total_matches + 1,
      points_for = leaderboard_entries.points_for + NEW.team2_score,
      points_against = leaderboard_entries.points_against + NEW.team1_score,
      win_rate = ROUND((leaderboard_entries.wins + CASE WHEN NOT team1_won THEN 1 ELSE 0 END)::DECIMAL / (leaderboard_entries.total_matches + 1) * 100, 2),
      updated_at = NOW();
  END IF;
  
  WITH ranked AS (
    SELECT id, ROW_NUMBER() OVER (ORDER BY wins DESC, win_rate DESC, points_for DESC) as new_rank
    FROM leaderboard_entries
    WHERE group_id = v_group_id AND is_pair = false
  )
  UPDATE leaderboard_entries le SET ranking = r.new_rank FROM ranked r WHERE le.id = r.id;
  
  WITH ranked_pairs AS (
    SELECT id, ROW_NUMBER() OVER (ORDER BY wins DESC, win_rate DESC, points_for DESC) as new_rank
    FROM leaderboard_entries
    WHERE group_id = v_group_id AND is_pair = true
  )
  UPDATE leaderboard_entries le SET ranking = r.new_rank FROM ranked_pairs r WHERE le.id = r.id;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."update_leaderboard_from_match"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_league_rankings"("_match_result_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_result record;
  v_league_id uuid;
  v_team1_avg numeric;
  v_team2_avg numeric;
  v_rating_gap numeric;
  v_score_diff integer;
  v_base_points numeric;
  v_margin_multiplier numeric;
  v_points_exchange numeric;
  v_team1_won boolean;
  v_player_id uuid;
  v_current_points numeric;
  v_max_change integer := 10;
  v_all_enrolled boolean;
begin
  -- Get match result with league_id
  select
    mr.*,
    m.group_id,
    m.league_id
  into v_result
  from match_results mr
  join matches m on m.id = mr.match_id
  where mr.id = _match_result_id;

  v_league_id := v_result.league_id;

  -- If no league attached, skip
  if v_league_id is null then
    raise notice 'Match result % has no league_id — skipping ranking update', _match_result_id;
    return;
  end if;

  -- Check all 4 players are enrolled in this league
  select (
    select count(*) from league_members lm
    where lm.league_id = v_league_id
    and lm.user_id = any(v_result.team1_players || v_result.team2_players)
  ) = array_length(v_result.team1_players || v_result.team2_players, 1)
  into v_all_enrolled;

  if not v_all_enrolled then
    raise notice 'Not all players enrolled in league % — skipping', v_league_id;
    return;
  end if;

  -- Ensure all 4 players have a league_standings row
  insert into league_standings (league_id, user_id, category, ranking_points, matches_played, wins, losses, points_gained)
  select v_league_id, unnest(v_result.team1_players || v_result.team2_players), 'overall', 50, 0, 0, 0, 0
  on conflict (league_id, user_id, category) do nothing;

  -- Get team average ranking points from league_standings
  select avg(ls.ranking_points)
  into v_team1_avg
  from league_standings ls
  where ls.league_id = v_league_id
  and ls.user_id = any(v_result.team1_players)
  and ls.category = 'overall';

  select avg(ls.ranking_points)
  into v_team2_avg
  from league_standings ls
  where ls.league_id = v_league_id
  and ls.user_id = any(v_result.team2_players)
  and ls.category = 'overall';

  -- Rating gap and winner
  v_rating_gap := v_team1_avg - v_team2_avg;
  v_score_diff := abs(v_result.team1_score - v_result.team2_score);
  v_team1_won := v_result.team1_score > v_result.team2_score;

  -- Base points (upset = more points, expected win = fewer)
  if v_team1_won then
    v_base_points := greatest(1, 1 - (v_rating_gap / 10));
  else
    v_base_points := greatest(1, 1 + (v_rating_gap / 10));
  end if;

  -- Margin multiplier
  case
    when v_score_diff >= 5 then v_margin_multiplier := 1.5;
    when v_score_diff >= 3 then v_margin_multiplier := 1.3;
    when v_score_diff >= 2 then v_margin_multiplier := 1.1;
    else v_margin_multiplier := 1.0;
  end case;

  v_points_exchange := least(v_base_points * v_margin_multiplier, v_max_change);

  -- Update winners
  foreach v_player_id in array
    case when v_team1_won then v_result.team1_players else v_result.team2_players end
  loop
    update league_standings
    set
      ranking_points = least(100, ranking_points + v_points_exchange),
      matches_played = matches_played + 1,
      wins = wins + 1,
      points_gained = points_gained + v_points_exchange::integer,
      updated_at = now(),
      last_calculated = now()
    where league_id = v_league_id
    and user_id = v_player_id
    and category = 'overall';
  end loop;

  -- Update losers
  foreach v_player_id in array
    case when v_team1_won then v_result.team2_players else v_result.team1_players end
  loop
    -- Close loss against higher-rated team = reduced penalty
    if v_score_diff <= 1 and (
      (v_team1_won and v_rating_gap > 0) or
      (not v_team1_won and v_rating_gap < 0)
    ) then
      update league_standings
      set
        ranking_points = greatest(0, ranking_points - (v_points_exchange * 0.3)),
        matches_played = matches_played + 1,
        losses = losses + 1,
        updated_at = now(),
        last_calculated = now()
      where league_id = v_league_id
      and user_id = v_player_id
      and category = 'overall';
    else
      update league_standings
      set
        ranking_points = greatest(0, ranking_points - v_points_exchange),
        matches_played = matches_played + 1,
        losses = losses + 1,
        updated_at = now(),
        last_calculated = now()
      where league_id = v_league_id
      and user_id = v_player_id
      and category = 'overall';
    end if;
  end loop;

  -- Mark match result as ranking updated
  update match_results
  set ranking_updated = true
  where id = _match_result_id;

  -- Update giant_killer stat (win vs higher rated team)
  if (v_team1_won and v_rating_gap < 0) or (not v_team1_won and v_rating_gap > 0) then
    foreach v_player_id in array
      case when v_team1_won then v_result.team1_players else v_result.team2_players end
    loop
      update league_standings
      set wins_vs_higher_rated = wins_vs_higher_rated + 1
      where league_id = v_league_id
      and user_id = v_player_id
      and category = 'overall';
    end loop;
  end if;

end;
$$;


ALTER FUNCTION "public"."update_league_rankings"("_match_result_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_match_travel_pickup_time"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_match_datetime TIMESTAMPTZ;
BEGIN
  IF NEW.is_driver THEN
    -- Get match datetime
    SELECT (match_date::TEXT || ' ' || match_time::TEXT)::TIMESTAMPTZ 
    INTO v_match_datetime
    FROM matches
    WHERE id = NEW.match_id;
    
    -- Calculate pickup time by subtracting buffer
    NEW.pickup_time := v_match_datetime - (NEW.pickup_buffer_minutes || ' minutes')::INTERVAL;
  ELSE
    NEW.pickup_time := NULL;
  END IF;
  
  NEW.updated_at := NOW();
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."update_match_travel_pickup_time"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_open_match_range"("p_match_id" "uuid", "p_elo_min" integer, "p_elo_max" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$                                                     
  DECLARE
    v_user_id uuid := auth.uid();
    v_match record;
    v_is_player boolean := false;                                               
    v_is_admin boolean := false;
  BEGIN                                                                         
    IF v_user_id IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
    SELECT * INTO v_match FROM matches WHERE id = p_match_id;                   
    IF NOT FOUND THEN RAISE EXCEPTION 'Match not found'; END IF;
    IF NOT v_match.is_open THEN RAISE EXCEPTION 'Match is not open'; END IF;    
    v_is_player := v_user_id = ANY(COALESCE(v_match.player_ids,
  ARRAY[]::uuid[]));                                                            
    IF NOT v_is_player AND v_match.group_id IS NOT NULL THEN
      SELECT EXISTS (                                                           
        SELECT 1 FROM group_members                                             
        WHERE group_id = v_match.group_id AND user_id = v_user_id AND role =    
  'admin'                                                                       
      ) INTO v_is_admin;                                    
    END IF;                                                                     
    IF NOT v_is_player AND NOT v_is_admin THEN              
      RAISE EXCEPTION 'Only match players or group admins can update range';
    END IF;                                                                     
    IF p_elo_min < 600 OR p_elo_max > 2500 OR p_elo_min >= p_elo_max THEN
      RAISE EXCEPTION 'Invalid ELO range';                                      
    END IF;                                                 
    UPDATE matches                                                              
    SET open_elo_min = p_elo_min, open_elo_max = p_elo_max, updated_at = now()
    WHERE id = p_match_id;                                                      
    RETURN jsonb_build_object('success', true);
  END;                                                                          
  $$;


ALTER FUNCTION "public"."update_open_match_range"("p_match_id" "uuid", "p_elo_min" integer, "p_elo_max" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_paid_player_ids"("p_booking_id" "uuid", "p_paid_player_ids" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_ok  boolean;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  SELECT (b.booked_by = v_uid OR v_uid = ANY(b.player_ids))
    INTO v_ok
  FROM public.bookings b
  WHERE b.id = p_booking_id;

  IF v_ok IS NOT TRUE THEN
    RAISE EXCEPTION 'not_a_participant';
  END IF;

  UPDATE public.bookings
     SET paid_player_ids = p_paid_player_ids
   WHERE id = p_booking_id;
END;
$$;


ALTER FUNCTION "public"."update_paid_player_ids"("p_booking_id" "uuid", "p_paid_player_ids" "jsonb") OWNER TO "postgres";


