CREATE OR REPLACE FUNCTION "public"."validate_voucher"("p_venue_id" "uuid", "p_code" "text", "p_amount_pence" integer DEFAULT 0, "p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v record;
  v_user_redemptions int := 0;
  v_discount int;
begin
  select * into v from public.vouchers
   where venue_id = p_venue_id and upper(code) = upper(trim(p_code))
   limit 1;

  if v.id is null then
    return jsonb_build_object('valid', false, 'reason', 'not_found', 'message', 'That code isn''t recognised.');
  end if;
  if not v.active then
    return jsonb_build_object('valid', false, 'reason', 'inactive', 'message', 'This code is no longer active.');
  end if;
  if v.valid_from is not null and now() < v.valid_from then
    return jsonb_build_object('valid', false, 'reason', 'not_started', 'message', 'This code isn''t valid yet.');
  end if;
  if v.valid_until is not null and now() > v.valid_until then
    return jsonb_build_object('valid', false, 'reason', 'expired', 'message', 'This code has expired.');
  end if;
  if v.max_redemptions is not null and v.times_redeemed >= v.max_redemptions then
    return jsonb_build_object('valid', false, 'reason', 'exhausted', 'message', 'This code has been fully redeemed.');
  end if;
  if v.min_spend_pence is not null and p_amount_pence < v.min_spend_pence then
    return jsonb_build_object('valid', false, 'reason', 'min_spend', 'message', 'Spend more to use this code.');
  end if;
  if p_user_id is not null and v.per_user_limit is not null then
    select count(*) into v_user_redemptions from public.voucher_redemptions
      where voucher_id = v.id and user_id = p_user_id;
    if v_user_redemptions >= v.per_user_limit then
      return jsonb_build_object('valid', false, 'reason', 'user_limit', 'message', 'You''ve already used this code.');
    end if;
  end if;

  if v.discount_type = 'percent' then
    v_discount := round(p_amount_pence * v.discount_value / 100.0)::int;
  else
    v_discount := least(v.discount_value, p_amount_pence);   -- never discount below zero
  end if;

  return jsonb_build_object(
    'valid', true,
    'voucher_id', v.id,
    'code', v.code,
    'discount_type', v.discount_type,
    'discount_value', v.discount_value,
    'discount_pence', v_discount,
    'message', 'Code applied.'
  );
end;
$$;


ALTER FUNCTION "public"."validate_voucher"("p_venue_id" "uuid", "p_code" "text", "p_amount_pence" integer, "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."venue_duplicate_candidates"("p_max_metres" double precision DEFAULT 150, "p_limit" integer DEFAULT 200) RETURNS TABLE("a_venue_id" "uuid", "a_name" "text", "a_courts" integer, "a_booking" boolean, "a_enriched" boolean, "b_venue_id" "uuid", "b_name" "text", "b_courts" integer, "b_booking" boolean, "b_enriched" boolean, "city" "text", "country_code" "text", "metres" integer, "shared_token" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with active as (
    select v.venue_id, v.venue_name, v.city, v.country_code,
           v.latitude::double precision la, v.longitude::double precision lo,
           greatest(coalesce(v.number_of_courts,0),
                    coalesce(v.indoor_courts,0) + coalesce(v.outdoor_courts,0) + coalesce(v.covered_courts,0)) as courts,
           (v.booking_url <> '') as has_booking,
           (v.typical_court_price_peak is not null) as enriched,
           (select w
              from unnest(regexp_split_to_array(lower(v.venue_name), '[^a-z0-9]+')) w
             where length(w) >= 4
               and w not in (
                 'padel','padel1','padels','paddle','tennis','club','clube','clubs','sport','sports',
                 'sportif','sportivo','deporte','deportivo','centre','center','centro','arena','arenas',
                 'academy','academia','academie','indoor','outdoor','court','courts','cancha','canchas',
                 'complex','complejo','city','town','park','parc','parque','the','and','group','zone'
               )
             order by length(w) desc limit 1) as token
      from public.padel_venues v
     where v.status = 'active'
       and v.venue_type = 'club'
       and v.merged_into is null
       and v.latitude is not null and v.longitude is not null
  )
  select a.venue_id, a.venue_name, a.courts, a.has_booking, a.enriched,
         b.venue_id, b.venue_name, b.courts, b.has_booking, b.enriched,
         coalesce(a.city, b.city), a.country_code,
         round(public.haversine_miles(a.la, a.lo, b.la, b.lo) * 1609.34)::integer,
         case when a.token is not null and a.token = b.token then a.token else null end
    from active a
    join active b
      on a.venue_id < b.venue_id
     and a.country_code = b.country_code
     and abs(a.la - b.la) < 0.0025
     and abs(a.lo - b.lo) < 0.0025
   where public.haversine_miles(a.la, a.lo, b.la, b.lo) * 1609.34 <= greatest(p_max_metres, 0)
     and not exists (
       select 1 from public.venue_duplicate_dismissals d
        where d.venue_id_a = a.venue_id and d.venue_id_b = b.venue_id
     )
   order by (case when a.token is not null and a.token = b.token then 0 else 1 end),
            public.haversine_miles(a.la, a.lo, b.la, b.lo)
   limit greatest(1, least(coalesce(p_limit, 200), 1000));
$$;


ALTER FUNCTION "public"."venue_duplicate_candidates"("p_max_metres" double precision, "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."venue_duplicate_candidates"("p_max_metres" double precision, "p_limit" integer) IS 'Ranked duplicate CANDIDATES for human review. Proximity is evidence, not proof - two real clubs can share a complex. Generic words are excluded from the shared-name signal.';



CREATE OR REPLACE FUNCTION "public"."venues_near"("p_lat" double precision, "p_lng" double precision, "p_radius_miles" double precision DEFAULT 50, "p_limit" integer DEFAULT 12, "p_venue_type" "text" DEFAULT 'club'::"text") RETURNS TABLE("venue_id" "uuid", "venues_id" "uuid", "venue_name" "text", "city" "text", "country_code" "text", "postcode" "text", "indoor_courts" integer, "outdoor_courts" integer, "covered_courts" integer, "number_of_courts" integer, "ppa_bookable" boolean, "booking_platform" "text", "booking_url" "text", "price_pence" integer, "price_per_hour" integer, "rating" numeric, "photos" "jsonb", "venue_type" "text", "needs_review" boolean, "distance_miles" double precision, "latitude" double precision, "longitude" double precision)
    LANGUAGE "sql" STABLE
    AS $$
  select v.venue_id, v.venues_id, v.venue_name, v.city, v.country_code, v.postcode,
         v.indoor_courts, v.outdoor_courts, v.covered_courts, v.number_of_courts,
         v.ppa_bookable, v.booking_platform, v.booking_url,
         v.price_pence, v.price_per_hour,
         v.rating, v.photos,
         v.venue_type, v.needs_review,
         public.haversine_miles(p_lat, p_lng, v.latitude::double precision, v.longitude::double precision) as distance_miles,
         v.latitude::double precision, v.longitude::double precision
  from public.padel_venues v
  where v.latitude is not null and v.longitude is not null
    and v.status = 'active'
    -- p_venue_type null means "any type", so a future coaches-near-me screen is
    -- not blocked by today's default.
    and (p_venue_type is null or v.venue_type = p_venue_type)
    and public.haversine_miles(p_lat, p_lng, v.latitude::double precision, v.longitude::double precision) <= greatest(p_radius_miles, 0)
  order by distance_miles asc
  limit greatest(1, least(coalesce(p_limit, 12), 200));
$$;


ALTER FUNCTION "public"."venues_near"("p_lat" double precision, "p_lng" double precision, "p_radius_miles" double precision, "p_limit" integer, "p_venue_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."venues_near_place"("p_query" "text", "p_radius_miles" double precision DEFAULT 25, "p_limit" integer DEFAULT 20, "p_venue_type" "text" DEFAULT 'club'::"text") RETURNS TABLE("venue_id" "uuid", "venues_id" "uuid", "venue_name" "text", "city" "text", "country_code" "text", "postcode" "text", "indoor_courts" integer, "outdoor_courts" integer, "covered_courts" integer, "number_of_courts" integer, "ppa_bookable" boolean, "booking_platform" "text", "booking_url" "text", "price_pence" integer, "price_per_hour" integer, "rating" numeric, "photos" "jsonb", "venue_type" "text", "needs_review" boolean, "distance_miles" double precision, "latitude" double precision, "longitude" double precision, "place_label" "text", "place_kind" "text")
    LANGUAGE "sql" STABLE
    AS $$
  with p as (
    select * from public.resolve_place(p_query) limit 1
  )
  select n.venue_id, n.venues_id, n.venue_name, n.city, n.country_code, n.postcode,
         n.indoor_courts, n.outdoor_courts, n.covered_courts, n.number_of_courts,
         n.ppa_bookable, n.booking_platform, n.booking_url,
         n.price_pence, n.price_per_hour,
         n.rating, n.photos,
         n.venue_type, n.needs_review,
         n.distance_miles, n.latitude, n.longitude,
         p.label, p.match_kind
    from p
    cross join lateral public.venues_near(
      p.lat, p.lng,
      greatest(coalesce(p_radius_miles, 25), 0),
      greatest(1, least(coalesce(p_limit, 20), 200)),
      p_venue_type
    ) n;
$$;


ALTER FUNCTION "public"."venues_near_place"("p_query" "text", "p_radius_miles" double precision, "p_limit" integer, "p_venue_type" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."venues_near_place"("p_query" "text", "p_radius_miles" double precision, "p_limit" integer, "p_venue_type" "text") IS 'Venue search by place: resolves the query to a coordinate, then returns venues_near rows ordered by distance.';



CREATE OR REPLACE FUNCTION "public"."venues_needing_enrichment"("p_source" "text", "p_limit" integer DEFAULT 25) RETURNS TABLE("venue_id" "uuid", "venue_name" "text", "external_ref" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select v.venue_id, v.venue_name, v.external_ref
    from public.padel_venues v
   where v.status = 'active'
     and v.venue_type = 'club'
     and v.external_ref like 'google_places:%'
     -- Already attempted from this source, successfully or not. A place id
     -- Google rejects will keep being rejected; re-fetching it every run pays
     -- again to learn the same thing, so error rows count as attempted and are
     -- cleared deliberately rather than retried by default.
     and not exists (
       select 1 from public.venue_enrichment e
        where e.venue_id = v.venue_id
          and e.source = p_source
     )
   -- Deterministic order, so consecutive batches march through the table
   -- instead of re-rolling the dice and revisiting the same rows.
   order by v.venue_id
   limit greatest(1, least(coalesce(p_limit, 25), 200));
$$;


ALTER FUNCTION "public"."venues_needing_enrichment"("p_source" "text", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."venues_needing_enrichment"("p_source" "text", "p_limit" integer) IS 'Next batch of venues with no venue_enrichment row for the given source. Anti-join stays in Postgres so the batch query does not grow with progress.';



CREATE OR REPLACE FUNCTION "public"."verify_claim_token"("p_venue_id" "uuid", "p_token" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_record public.venue_claim_verifications%ROWTYPE;
  v_anchor uuid;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  SELECT venues_id INTO v_anchor
  FROM public.padel_venues
  WHERE venue_id = p_venue_id;

  IF v_anchor IS NULL THEN
    RAISE EXCEPTION 'venue_not_found';
  END IF;

  SELECT * INTO v_record
  FROM public.venue_claim_verifications
  WHERE user_id = v_user_id
    AND venue_id = p_venue_id
    AND token = p_token
    AND used_at IS NULL
    AND expires_at > now()
  ORDER BY created_at DESC
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_or_expired_code');
  END IF;

  UPDATE public.venue_claim_verifications
  SET used_at = now()
  WHERE id = v_record.id;

  UPDATE public.venue_users
  SET status = 'active'
  WHERE venue_id = v_anchor
    AND user_id = v_user_id
    AND status = 'pending';

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."verify_claim_token"("p_venue_id" "uuid", "p_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wants_push"("p_user_id" "uuid", "p_type" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    coalesce(not (select p.push_opted_out from profiles p where p.id = p_user_id), true)
    and
    coalesce(
      (
        select case
          when p_type like 'open_match%'                                   then np.open_matches
          when p_type like 'poll_%'                                        then np.poll_reminders
          when p_type like 'connection_%'                                  then np.connection_requests
          when p_type like 'chat_%' or p_type like '%message%'             then np.chat_notifications
          when p_type like 'result_%' or p_type like 'match_result%'       then np.match_results
          when p_type like 'match_reminder%' or p_type like 'match_deadline%' then np.match_reminders
          else true
        end
        from notification_preferences np
        where np.user_id = p_user_id
      ),
      true
    );
$$;


ALTER FUNCTION "public"."wants_push"("p_user_id" "uuid", "p_type" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."wants_push"("p_user_id" "uuid", "p_type" "text") IS 'The only question the push pipeline asks: does this player want this kind of push? Combines profiles.push_opted_out (master) with the matching notification_preferences column (category). Absent rows mean yes. Called by the notify-onesignal edge function.';



