CREATE TABLE IF NOT EXISTS "public"."padel_venues" (
    "venue_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "venue_name" "text" NOT NULL,
    "country" "text" NOT NULL,
    "country_code" "text" NOT NULL,
    "city" "text" NOT NULL,
    "postal_code" "text",
    "full_address" "text" NOT NULL,
    "latitude" numeric(10,8),
    "longitude" numeric(11,8),
    "phone" "text",
    "email" "text",
    "website_url" "text",
    "booking_url" "text" DEFAULT ''::"text" NOT NULL,
    "booking_platform" "text",
    "number_of_courts" integer NOT NULL,
    "indoor_courts" integer DEFAULT 0,
    "outdoor_courts" integer DEFAULT 0,
    "singles_courts" integer DEFAULT 0,
    "doubles_courts" integer DEFAULT 0,
    "panoramic_courts" integer DEFAULT 0,
    "membership_required" boolean DEFAULT false,
    "pay_per_play" boolean DEFAULT true,
    "booking_advance_nonmember_days" integer NOT NULL,
    "booking_advance_member_days" integer NOT NULL,
    "booking_advance_info" "text",
    "typical_court_price_offpeak" numeric(10,2),
    "typical_court_price_peak" numeric(10,2),
    "currency" "text" DEFAULT 'EUR'::"text" NOT NULL,
    "amenities" "jsonb" DEFAULT '[]'::"jsonb",
    "equipment_rental" boolean DEFAULT false,
    "coaching_available" boolean DEFAULT false,
    "parking_available" boolean DEFAULT false,
    "cafe_bar" boolean DEFAULT false,
    "changing_rooms" boolean DEFAULT false,
    "rating" numeric(2,1),
    "total_reviews" integer DEFAULT 0,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "verified" boolean DEFAULT false,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "whatsapp_number" "text",
    "has_roof" boolean DEFAULT false,
    "booking_type" "text",
    "ppa_bookable" boolean DEFAULT false,
    "price_pence" integer DEFAULT 3600,
    "price_per_player_pence" integer DEFAULT 900,
    "covered_courts" integer DEFAULT 0,
    "opening_hours" "jsonb" DEFAULT '{"friday": {"open": "07:00", "close": "22:00"}, "monday": {"open": "07:00", "close": "22:00"}, "sunday": {"open": "08:00", "close": "21:00"}, "tuesday": {"open": "07:00", "close": "22:00"}, "saturday": {"open": "08:00", "close": "21:00"}, "thursday": {"open": "07:00", "close": "22:00"}, "wednesday": {"open": "07:00", "close": "22:00"}}'::"jsonb",
    "pricing_tier" integer DEFAULT 2,
    "price_per_hour" integer DEFAULT 0,
    "facilities" "jsonb" DEFAULT '[]'::"jsonb",
    "photos" "jsonb" DEFAULT '[]'::"jsonb",
    "description" "text",
    "surface_type" "text" DEFAULT 'artificial_grass'::"text",
    "is_members_only" boolean DEFAULT false,
    "membership_note" "text",
    "instagram" "text",
    "website" "text",
    "postcode" "text",
    "review_count" integer DEFAULT 0,
    "is_verified" boolean DEFAULT false,
    "last_verified_at" timestamp with time zone,
    "venues_id" "uuid",
    "external_ref" "text",
    "dynamic_pricing_enabled" boolean DEFAULT false NOT NULL,
    "dynamic_pricing_threshold_pct" integer DEFAULT 70 NOT NULL,
    "dynamic_pricing_surcharge_pct" integer DEFAULT 15 NOT NULL,
    "venue_type" "text" DEFAULT 'club'::"text" NOT NULL,
    "classified_by" "text",
    "needs_review" boolean DEFAULT false NOT NULL,
    "review_reason" "text",
    "classified_at" timestamp with time zone,
    "merged_into" "uuid",
    CONSTRAINT "padel_venues_amenities_is_array" CHECK ((("amenities" IS NULL) OR ("jsonb_typeof"("amenities") = 'array'::"text"))),
    CONSTRAINT "padel_venues_booking_type_check" CHECK (("booking_type" = ANY (ARRAY['link'::"text", 'whatsapp'::"text", 'widget'::"text", 'contact'::"text", NULL::"text"]))),
    CONSTRAINT "padel_venues_coach_offers_coaching" CHECK ((("venue_type" IS DISTINCT FROM 'coach'::"text") OR COALESCE("coaching_available", false))),
    CONSTRAINT "padel_venues_dyn_surcharge_chk" CHECK ((("dynamic_pricing_surcharge_pct" >= 0) AND ("dynamic_pricing_surcharge_pct" <= 200))),
    CONSTRAINT "padel_venues_dyn_threshold_chk" CHECK ((("dynamic_pricing_threshold_pct" >= 0) AND ("dynamic_pricing_threshold_pct" <= 100))),
    CONSTRAINT "padel_venues_facilities_is_array" CHECK ((("facilities" IS NULL) OR ("jsonb_typeof"("facilities") = 'array'::"text"))),
    CONSTRAINT "padel_venues_opening_hours_is_object" CHECK ((("opening_hours" IS NULL) OR ("jsonb_typeof"("opening_hours") = 'object'::"text"))),
    CONSTRAINT "padel_venues_photos_is_array" CHECK ((("photos" IS NULL) OR ("jsonb_typeof"("photos") = 'array'::"text"))),
    CONSTRAINT "padel_venues_rating_check" CHECK ((("rating" >= (0)::numeric) AND ("rating" <= (5)::numeric))),
    CONSTRAINT "padel_venues_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'closed'::"text", 'coming_soon'::"text", 'merged'::"text"]))),
    CONSTRAINT "padel_venues_venue_type_check" CHECK (("venue_type" = ANY (ARRAY['club'::"text", 'coach'::"text", 'not_padel'::"text"]))),
    CONSTRAINT "valid_court_counts" CHECK (("number_of_courts" >= (COALESCE("indoor_courts", 0) + COALESCE("outdoor_courts", 0))))
);


ALTER TABLE "public"."padel_venues" OWNER TO "postgres";


COMMENT ON TABLE "public"."padel_venues" IS 'Directory of padel venues worldwide';



COMMENT ON COLUMN "public"."padel_venues"."postal_code" IS 'DEPRECATED — use postcode. Retained only so the backfill stays reversible and the two conflicting rows can be resolved by hand. Do not read in application code.';



COMMENT ON COLUMN "public"."padel_venues"."booking_advance_nonmember_days" IS 'How many days in advance non-members can book courts';



COMMENT ON COLUMN "public"."padel_venues"."booking_advance_member_days" IS 'How many days in advance members can book courts';



COMMENT ON COLUMN "public"."padel_venues"."amenities" IS 'Array of amenities like ["bar", "parking", "pro_shop", "showers"]';



COMMENT ON COLUMN "public"."padel_venues"."status" IS 'Venue status: active, closed, or coming_soon';



COMMENT ON COLUMN "public"."padel_venues"."verified" IS 'Whether the venue data has been verified by admins';



COMMENT ON COLUMN "public"."padel_venues"."external_ref" IS 'Import dedup key, e.g. "google_places:<place_id>". Null for hand-created/claimed venues.';



COMMENT ON COLUMN "public"."padel_venues"."venue_type" IS 'club = a place with courts; coach = an individual/coaching business with no courts of its own; not_padel = ingested in error. Default club: only set another value on evidence.';



COMMENT ON COLUMN "public"."padel_venues"."needs_review" IS 'True when automated classification was not confident. The row stays VISIBLE; this is a work queue, not a filter.';



COMMENT ON COLUMN "public"."padel_venues"."classified_at" IS 'When venue_type was last set. Written only by admin_classify_venue and the initial auto-classification.';



COMMENT ON COLUMN "public"."padel_venues"."merged_into" IS 'When set, this row is a duplicate of the venue it points at. The row is kept so existing /venues/<id> links still resolve; the app redirects. Set only by admin_merge_venues.';



