    CONSTRAINT "events_event_type_check" CHECK (("event_type" = ANY (ARRAY['demo'::"text", 'coaching'::"text", 'social'::"text", 'tournament'::"text", 'competition'::"text", 'other'::"text"]))),
    CONSTRAINT "events_group_visibility_needs_group" CHECK (((("visibility")::"text" <> 'group'::"text") OR ("group_id" IS NOT NULL))),
    CONSTRAINT "events_latlng_both_or_neither" CHECK ((("latitude" IS NULL) = ("longitude" IS NULL))),
