    "booking_status" "text" DEFAULT 'not_booked'::"text",
    "booked_venue_name" "text",
    "booking_reference" "text",
    "booked_at" timestamp with time zone,
    "booked_by" "uuid",
    "created_by" "uuid",
    "created_manually" boolean DEFAULT false,
    "bypassed_conflicts" boolean DEFAULT false,
    "venue_details" "jsonb",
    "organizer_notes" "text",
    "requires_confirmation" boolean DEFAULT true,
    "confirmed_players" "uuid"[] DEFAULT ARRAY[]::"uuid"[],
    "booking_claimed_by" "uuid",
    "booking_claimed_at" timestamp with time zone,
    "booking_notes" "text",
    "voided_at" timestamp with time zone,
