    "booked_court_number" integer,
    "league_id" "uuid",
    "voting_closes_at" timestamp with time zone,
    "context_type" "text" DEFAULT 'open'::"text",
    "result_type" "text",
    "winner_team" "text",
    "score_sets" "jsonb",
    "result_submitted_by" "uuid",
    "result_submitted_at" timestamp with time zone,
    "travel_notes" "text",
    "drivers" "jsonb" DEFAULT '[]'::"jsonb",
    "team1_player_ids" "uuid"[],
    "team2_player_ids" "uuid"[],
    "push_result_prompt_sent" boolean DEFAULT false,
    "push_deadline_sent" boolean DEFAULT false,
    "is_open" boolean DEFAULT false NOT NULL,
    "open_elo_min" integer,
    "open_elo_max" integer,
    "opened_by" "uuid",
    "opened_at" timestamp with time zone,
    "team1_id" "uuid",
    "team2_id" "uuid",
    "round_number" integer,
    "exclude_from_league" boolean DEFAULT false NOT NULL,
    "push_reminder_sent" boolean DEFAULT false,
    "court_requirement" "text" DEFAULT 'needed'::"text" NOT NULL,
    "poll_slot_id" "text",
    "window_start" time without time zone,
    "window_end" time without time zone,
    "duration_minutes" integer,
    "open_audience" "text" DEFAULT 'open'::"text" NOT NULL,
