    CONSTRAINT "matches_booking_status_check" CHECK (("booking_status" = ANY (ARRAY['not_booked'::"text", 'claimed'::"text", 'booked'::"text", 'booked_with_changes'::"text"]))),
    CONSTRAINT "matches_conflict_status_check" CHECK (("conflict_status" = ANY (ARRAY['none'::"text", 'amber'::"text", 'red'::"text", 'resolved'::"text"]))),
    CONSTRAINT "matches_context_type_check" CHECK ((("context_type" = ANY (ARRAY['league'::"text", 'group'::"text", 'poll'::"text", 'casual'::"text", 'open'::"text", 'friendly'::"text", 'competitive'::"text", 'practice'::"text"])) OR ("context_type" IS NULL))),
    CONSTRAINT "matches_court_requirement_check" CHECK (("court_requirement" = ANY (ARRAY['needed'::"text", 'not_needed'::"text"]))),
    CONSTRAINT "matches_match_type_check" CHECK (("match_type" = ANY (ARRAY['group'::"text", 'casual'::"text", 'competitive'::"text", 'friendly'::"text", 'practice'::"text"]))),
    CONSTRAINT "matches_open_audience_check" CHECK (("open_audience" = ANY (ARRAY['connections'::"text", 'groups'::"text", 'open'::"text"]))),
    CONSTRAINT "matches_player_ids_check" CHECK ((("array_length"("player_ids", 1) >= 1) AND ("array_length"("player_ids", 1) <= 4))),
    CONSTRAINT "matches_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'scheduled'::"text", 'confirmed'::"text", 'open'::"text", 'completed'::"text", 'cancelled'::"text", 'suggested'::"text"])))
);


ALTER TABLE "public"."matches" OWNER TO "postgres";


COMMENT ON COLUMN "public"."matches"."ringer_info" IS 'Stores information about external "ringer" players not in the system. Format: { name: string, playtomic_level: number }';



COMMENT ON COLUMN "public"."matches"."conflict_status" IS 'Tracks household conflict severity: none (no conflicts), amber (potential conflicts warned), red (critical conflicts requiring resolution), resolved (conflicts acknowledged and resolved)';



COMMENT ON COLUMN "public"."matches"."additional_options" IS 'Stores additional poll options selected by players in this match (e.g., {"I can drive": ["user_id_1", "user_id_2"], "I''m up for a drink after": ["user_id_3"]})';



COMMENT ON COLUMN "public"."matches"."booking_status" IS 'Status of court booking: not_booked, booked, confirmed';



COMMENT ON COLUMN "public"."matches"."booked_venue_name" IS 'Name of venue where court was booked';



COMMENT ON COLUMN "public"."matches"."booking_reference" IS 'Booking reference or confirmation number';



COMMENT ON COLUMN "public"."matches"."booked_at" IS 'Timestamp when booking was marked as complete';



COMMENT ON COLUMN "public"."matches"."booked_by" IS 'User who marked the booking as complete';



COMMENT ON COLUMN "public"."matches"."duration_minutes" IS 'Optional per-match override for scheduled length in minutes. When null, the linked booking''s duration_minutes is used, falling back to 90.';



COMMENT ON COLUMN "public"."matches"."open_audience" IS 'Who an is_open match is visible to. open = anyone (the default, and what Push-to-open creates). connections = the creator''s accepted player_connections only. groups = members of the creator''s groups. Meaningless when is_open is false.';



CREATE OR REPLACE VIEW "public"."league_team_standings" AS
 SELECT "t"."id" AS "team_id",
    "t"."league_id",
    "t"."team_name",
    "t"."player1_id",
    "t"."player2_id",
    COALESCE("s1"."wins", 0) AS "wins",
    COALESCE("s1"."losses", 0) AS "losses",
    COALESCE("s1"."draws", 0) AS "draws",
    COALESCE("s1"."matches_played", 0) AS "matches_played",
    COALESCE("s1"."ranking_points", (0)::numeric) AS "ranking_points",
    COALESCE("gd"."games_won", (0)::bigint) AS "games_won",
    COALESCE("gd"."games_lost", (0)::bigint) AS "games_lost",
    (COALESCE("gd"."games_won", (0)::bigint) - COALESCE("gd"."games_lost", (0)::bigint)) AS "game_difference"
   FROM (("public"."league_teams" "t"
     LEFT JOIN "public"."league_standings" "s1" ON ((("s1"."league_id" = "t"."league_id") AND ("s1"."user_id" = "t"."player1_id"))))
     LEFT JOIN LATERAL ( SELECT "sum"(
                CASE
                    WHEN ("mr"."team1_players" @> ARRAY["t"."player1_id"]) THEN COALESCE((("s"."val" ->> 'team1'::"text"))::integer, (("s"."val" ->> 'team1_score'::"text"))::integer, 0)
                    ELSE COALESCE((("s"."val" ->> 'team2'::"text"))::integer, (("s"."val" ->> 'team2_score'::"text"))::integer, 0)
                END) AS "games_won",
            "sum"(
                CASE
                    WHEN ("mr"."team1_players" @> ARRAY["t"."player1_id"]) THEN COALESCE((("s"."val" ->> 'team2'::"text"))::integer, (("s"."val" ->> 'team2_score'::"text"))::integer, 0)
                    ELSE COALESCE((("s"."val" ->> 'team1'::"text"))::integer, (("s"."val" ->> 'team1_score'::"text"))::integer, 0)
                END) AS "games_lost"
           FROM (("public"."match_results" "mr"
             CROSS JOIN LATERAL "jsonb_array_elements"("mr"."sets_data") "s"("val"))
             JOIN "public"."matches" "m" ON ((("m"."id" = "mr"."match_id") AND ("m"."league_id" = "t"."league_id"))))
          WHERE (("mr"."verification_status" = 'verified'::"text") AND (("mr"."team1_players" @> ARRAY["t"."player1_id"]) OR ("mr"."team2_players" @> ARRAY["t"."player1_id"])))) "gd" ON (true));


ALTER VIEW "public"."league_team_standings" OWNER TO "postgres";


