CREATE OR REPLACE VIEW "public"."profiles_with_privacy" AS
 SELECT "id",
    "name",
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM "public"."profile_privacy_settings" "ps"
              WHERE (("ps"."user_id" = "p"."id") AND ("ps"."show_email_to_group" = true)))) THEN "email"
            ELSE NULL::"text"
        END AS "email",
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM "public"."profile_privacy_settings" "ps"
              WHERE (("ps"."user_id" = "p"."id") AND ("ps"."show_phone_to_group" = true)))) THEN "phone"
            ELSE NULL::"text"
        END AS "phone",
    "playtomic_level",
    "reliability_percent",
    "availability_preferences",
    "household_partner_id",
    "internal_ranking",
    "best_partner_id",
    "worst_partner_id",
    "created_at",
    "updated_at"
   FROM "public"."profiles" "p";


