    "booking_url" "text",
    "source_platform" "text",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "booking_type" "text" DEFAULT 'link'::"text",
    "booking_embed_code" "text",
    "has_app_booking" boolean DEFAULT true,
    "commission_rate_bps" integer DEFAULT 350 NOT NULL,
    "plan_tier" "text" DEFAULT 'core'::"text" NOT NULL,
    "is_founding_venue" boolean DEFAULT false NOT NULL,
    "stripe_customer_id" "text",
    "stripe_subscription_id" "text",
    "subscription_status" "text",
    "subscription_current_period_end" timestamp with time zone,
    "subscription_free_until" timestamp with time zone,
    "monthly_price_pence" integer,
    "deal_notes" "text",
    "grandfathered_ppa_bookable" boolean DEFAULT false NOT NULL,
    "currency" "text",
    CONSTRAINT "venues_commission_rate_bps_check" CHECK ((("commission_rate_bps" >= 0) AND ("commission_rate_bps" <= 1000))),
    CONSTRAINT "venues_plan_tier_check" CHECK (("plan_tier" = ANY (ARRAY['core'::"text", 'plus'::"text", 'pro'::"text"])))
);


ALTER TABLE "public"."venues" OWNER TO "postgres";


COMMENT ON COLUMN "public"."venues"."commission_rate_bps" IS 'Per-booking platform commission in basis points (350 = 3.5%). Read by create-booking-payment / create-event-payment. Default 3.5%; tier/founding venues set lower via set_venue_commission().';



COMMENT ON COLUMN "public"."venues"."subscription_status" IS 'Stripe subscription status for the SaaS plan (active/past_due/canceled/…); null = Core (no subscription).';



CREATE TABLE IF NOT EXISTS "public"."voucher_redemptions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "voucher_id" "uuid" NOT NULL,
    "venue_id" "uuid" NOT NULL,
    "user_id" "uuid",
    "booking_id" "uuid",
    "amount_pence" integer NOT NULL,
    "redeemed_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."voucher_redemptions" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."vouchers" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "venue_id" "uuid" NOT NULL,
    "code" "text" NOT NULL,
    "description" "text",
    "discount_type" "text" NOT NULL,
    "discount_value" integer NOT NULL,
    "currency" "text",
    "min_spend_pence" integer,
    "max_redemptions" integer,
    "times_redeemed" integer DEFAULT 0 NOT NULL,
    "per_user_limit" integer DEFAULT 1,
    "valid_from" timestamp with time zone,
    "valid_until" timestamp with time zone,
    "active" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "vouchers_discount_type_check" CHECK (("discount_type" = ANY (ARRAY['percent'::"text", 'fixed'::"text"]))),
    CONSTRAINT "vouchers_discount_value_check" CHECK (("discount_value" > 0)),
    CONSTRAINT "vouchers_percent_range" CHECK ((("discount_type" <> 'percent'::"text") OR (("discount_value" >= 1) AND ("discount_value" <= 100))))
);


ALTER TABLE "public"."vouchers" OWNER TO "postgres";


