CREATE POLICY "A member joins on the group's terms" ON "public"."group_members" FOR INSERT TO "authenticated" WITH CHECK ((("user_id" = "auth"."uid"()) AND (EXISTS ( SELECT 1
   FROM "public"."groups" "g"
  WHERE (("g"."id" = "group_members"."group_id") AND ((("group_members"."status" = 'approved'::"text") AND ("g"."admin_id" = "auth"."uid"())) OR (("group_members"."status" = 'approved'::"text") AND (COALESCE("g"."auto_approve_requests", false) OR COALESCE("g"."auto_approve", false)) AND COALESCE("g"."allow_join_requests", false)) OR (("group_members"."status" = 'pending'::"text") AND COALESCE("g"."allow_join_requests", false)) OR (("group_members"."status" = 'pending_ringer'::"text") AND COALESCE("g"."allow_ringers", false))))))));



CREATE POLICY "Active venue members can create bookings for their venue" ON "public"."bookings" FOR INSERT TO "authenticated" WITH CHECK ((EXISTS ( SELECT 1
   FROM "public"."venue_users" "vu"
  WHERE (("vu"."venue_id" = "bookings"."venue_id") AND ("vu"."user_id" = "auth"."uid"()) AND ("vu"."status" = 'active'::"text")))));



CREATE POLICY "Active venue members can update their venue's bookings" ON "public"."bookings" FOR UPDATE TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM "public"."venue_users" "vu"
  WHERE (("vu"."venue_id" = "bookings"."venue_id") AND ("vu"."user_id" = "auth"."uid"()) AND ("vu"."status" = 'active'::"text")))));



CREATE POLICY "Active venue members can view their venue's bookings" ON "public"."bookings" FOR SELECT TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM "public"."venue_users" "vu"
  WHERE (("vu"."venue_id" = "bookings"."venue_id") AND ("vu"."user_id" = "auth"."uid"()) AND ("vu"."status" = 'active'::"text")))));



CREATE POLICY "Admins can delete match results" ON "public"."match_results" FOR DELETE USING ((EXISTS ( SELECT 1
   FROM ("public"."matches" "m"
     JOIN "public"."groups" "g" ON (("g"."id" = "m"."group_id")))
  WHERE (("m"."id" = "match_results"."match_id") AND ("g"."admin_id" = "auth"."uid"())))));



CREATE POLICY "Admins can delete polls" ON "public"."polls" FOR DELETE USING ((EXISTS ( SELECT 1
   FROM ("public"."groups" "g"
     LEFT JOIN "public"."group_members" "gm" ON ((("gm"."group_id" = "g"."id") AND ("gm"."user_id" = "auth"."uid"()))))
  WHERE (("g"."id" = "polls"."group_id") AND (("g"."admin_id" = "auth"."uid"()) OR (("gm"."role" = 'admin'::"public"."group_role") AND ("gm"."status" = 'approved'::"text")))))));



