     LEFT JOIN "public"."group_members" "gm" ON ((("gm"."group_id" = "g"."id") AND ("gm"."user_id" = "auth"."uid"()))))
  WHERE (("p"."id" = "poll_deadline_changes"."poll_id") AND (("g"."admin_id" = "auth"."uid"()) OR (("gm"."role" = 'admin'::"public"."group_role") AND ("gm"."status" = 'approved'::"text")))))));



